import type { Language } from '../i18n/translations'

export const PARAM_HELP: Record<string, Partial<Record<Language, string>>> = {
  'lcz_anomaly.x': { en: 'The classified LCZ raster used to look up which zone type each station sits in, for example an urban LCZ map covering Rio de Janeiro.', pt: 'O raster LCZ classificado usado para identificar em qual tipo de zona cada estação está localizada, por exemplo um mapa LCZ urbano cobrindo o Rio de Janeiro.', es: 'El ráster LCZ clasificado usado para determinar en qué tipo de zona se encuentra cada estación, por ejemplo un mapa LCZ urbano que cubre Río de Janeiro.', zh: '用于查询每个站点所处区域类型的 LCZ 分类栅格，例如覆盖里约热内卢的城市 LCZ 地图。' },
  'lcz_anomaly.data_frame': { en: 'The table of station observations to analyze. It must include columns for latitude, longitude, date, the measured variable, and a station identifier.', pt: 'A tabela de observações das estações a analisar. Deve incluir colunas de latitude, longitude, data, a variável medida e um identificador de estação.', es: 'La tabla de observaciones de estaciones a analizar. Debe incluir columnas para latitud, longitud, fecha, la variable medida y un identificador de estación.', zh: '要分析的站点观测数据表，必须包含纬度、经度、日期、被测变量以及站点标识列。' },
  'lcz_anomaly.var': { en: 'The name of the column in your data that holds the measurement to analyze, such as "temperature" or "air_temp_c".', pt: 'O nome da coluna nos seus dados que contém a medição a analisar, como "temperature" ou "air_temp_c".', es: 'El nombre de la columna de sus datos que contiene la medición a analizar, como "temperature" o "air_temp_c".', zh: '数据中保存待分析测量值的列名，例如“temperature”或“air_temp_c”。' },
  'lcz_anomaly.station_id': { en: 'The name of the column that uniquely identifies each weather station, so readings from different stations aren\'t mixed together.', pt: 'O nome da coluna que identifica exclusivamente cada estação meteorológica, para que leituras de estações diferentes não se misturem.', es: 'El nombre de la columna que identifica de forma única a cada estación meteorológica, para que las lecturas de estaciones distintas no se mezclen entre sí.', zh: '唯一标识每个气象站的列名，避免不同站点的读数被混在一起。' },
  'lcz_anomaly.plot_type': { en: 'The chart style used to display anomalies: "diverging_bar" (default, horizontal bars spreading left/right from zero), "bar" (vertical bars colored red for warm and blue for cool), "dot" (each station\'s value plotted against the network average, connected by a line), "lollipop" (a stem from zero to the value topped with a circle sized by how large the anomaly is), or "scatter" (LCZ class on one axis against mean temperature on the other, useful for comparing zones directly).', pt: 'O estilo de gráfico usado para exibir as anomalias: "diverging_bar" (padrão, barras horizontais que se espalham para os lados a partir do zero), "bar" (barras verticais coloridas em vermelho para calor e azul para frio), "dot" (o valor de cada estação plotado contra a média da rede, ligado por uma linha), "lollipop" (uma haste do zero até o valor, encimada por um círculo cujo tamanho reflete a magnitude da anomalia), ou "scatter" (classe LCZ em um eixo contra a temperatura média no outro, útil para comparar zonas diretamente).', es: 'El estilo de gráfico usado para mostrar las anomalías: "diverging_bar" (por defecto, barras horizontales que se extienden a izquierda/derecha desde cero), "bar" (barras verticales coloreadas en rojo para calor y azul para frío), "dot" (el valor de cada estación graficado frente al promedio de la red, unidos por una línea), "lollipop" (un vástago de cero al valor, rematado por un círculo cuyo tamaño refleja la magnitud de la anomalía), o "scatter" (clase LCZ en un eje frente a temperatura media en el otro, útil para comparar zonas directamente).', zh: '用于展示异常值的图表样式：“diverging_bar”（默认，水平条形从零点向左右两侧延伸）、“bar”（垂直条形，暖色标红、冷色标蓝）、“dot”（每个站点的数值相对于全网平均值绘制，并用线条连接）、“lollipop”（从零到数值的一根杆，顶端有一个大小随异常幅度变化的圆点），或“scatter”（一个轴为 LCZ 类别，另一个轴为平均温度，便于直接比较各区域）。' },
  'lcz_anomaly.by': { en: 'Splits the results into separate panels grouped by a time period or category, such as "year", "season", "month", "weekday" versus "weekend", or "daylight" versus "nighttime" hours. Leave unset for one combined chart covering the whole period.', pt: 'Divide os resultados em painéis separados agrupados por período de tempo ou categoria, como "year", "season", "month", "weekday" versus "weekend", ou horas de "daylight" versus "nighttime". Deixe em branco para um único gráfico combinado cobrindo todo o período.', es: 'Divide los resultados en paneles separados agrupados por un periodo de tiempo o categoría, como "año", "estación del año", "mes", "día laborable" frente a "fin de semana", o "horas diurnas" frente a "nocturnas". Déjelo sin definir para un solo gráfico combinado de todo el periodo.', zh: '按时间段或类别（如“year”“season”“month”“weekday”对“weekend”，或“daylight”对“nighttime”）将结果拆分为多个独立面板。留空则生成覆盖整个时间段的单一综合图表。' },
  'lcz_anomaly.iplot': { en: 'Turn this off to get back just the numeric anomaly results as a table, without generating a chart.', pt: 'Desative para obter apenas os resultados numéricos da anomalia em forma de tabela, sem gerar um gráfico.', es: 'Desactívelo para obtener únicamente los resultados numéricos de la anomalía como tabla, sin generar ningún gráfico.', zh: '关闭此项可仅获得数值型异常结果表，而不生成图表。' },
  'lcz_anomaly.isave': { en: 'When turned on, saves the chart to the LCZ4r_output folder instead of only showing it on screen.', pt: 'Quando ativado, salva o gráfico na pasta de saída do aplicativo em vez de apenas exibi-lo em tela.', es: 'Al activarlo, guarda el gráfico en la carpeta de salida de la aplicación en lugar de mostrarlo solo en pantalla.', zh: '开启后会将图表保存到应用的输出文件夹，而不仅仅在屏幕上显示。' },
  'lcz_anomaly.save_extension': { en: 'The file format for the saved chart: "html" for an interactive version you can zoom and hover over, or "png"/"pdf" for a static image.', pt: 'O formato de arquivo para o gráfico salvo: "html" para uma versão interativa com zoom e passagem do mouse, ou "png"/"pdf" para uma imagem estática.', es: 'El formato de archivo para el gráfico guardado: "html" para una versión interactiva con zoom y datos al pasar el cursor, o "png"/"pdf" para una imagen estática.', zh: '保存图表所用的文件格式：“html”生成可缩放悬停的交互式版本，“png”/“pdf”生成静态图片。' },
  'lcz_anomaly.inclusive': { en: 'Switches to a colorblind-friendly version of the LCZ color scheme so zone colors stay distinguishable for all viewers.', pt: 'Troca para uma versão do esquema de cores LCZ adequada para daltônicos, para que as cores das zonas continuem distinguíveis para todos os públicos.', es: 'Cambia a una versión apta para daltónicos del esquema de colores LCZ, para que los colores de las zonas sigan siendo distinguibles para todos los usuarios.', zh: '切换为色盲友好版的 LCZ 配色方案，使各区域颜色对所有观众都保持可辨识。' },
  'lcz_anomaly.title': { en: 'Custom text to use as the chart\'s title, replacing the default one generated automatically.', pt: 'Texto personalizado a usar como título do gráfico, substituindo o gerado automaticamente por padrão.', es: 'Texto personalizado para usar como título del gráfico, en lugar del generado automáticamente por defecto.', zh: '用作图表标题的自定义文字，替换自动生成的默认标题。' },
  'lcz_anomaly.caption': { en: 'A short note added below the chart, for example crediting the data source or explaining the reference period used.', pt: 'Uma nota curta adicionada abaixo do gráfico, por exemplo para creditar a fonte dos dados ou explicar o período de referência usado.', es: 'Una nota breve añadida debajo del gráfico, por ejemplo para citar la fuente de datos o explicar el periodo de referencia usado.', zh: '图表下方添加的简短说明，例如注明数据来源或解释所使用的参照期。' },
  'lcz_anomaly.year': { en: 'Restrict the analysis to one or more specific years, for example 2022, instead of using the full date range in your data.', pt: 'Restringe a análise a um ou mais anos específicos, por exemplo 2022, em vez de usar todo o intervalo de datas dos seus dados.', es: 'Restringe el análisis a uno o varios años concretos, por ejemplo 2022, en lugar de usar todo el rango de fechas de sus datos.', zh: '将分析限定为一个或多个具体年份，例如 2022，而不是使用数据中的完整日期范围。' },
  'lcz_anomaly.month': { en: 'Restrict the analysis to specific calendar months (1–12), for example limiting results to June–August for a summer-only anomaly check.', pt: 'Restringe a análise a meses específicos do calendário (1–12), por exemplo limitando os resultados a junho–agosto para verificar apenas anomalias de verão.', es: 'Restringe el análisis a meses del calendario concretos (1-12), por ejemplo limitando los resultados a junio-agosto para revisar solo las anomalías de verano.', zh: '将分析限定为具体的日历月份（1-12），例如只保留 6-8 月以进行夏季专项异常检查。' },
  'lcz_anomaly.day': { en: 'Restrict the analysis to specific days of the month, useful for narrowing in on an unusual event.', pt: 'Restringe a análise a dias específicos do mês, útil para focar em um evento incomum.', es: 'Restringe el análisis a días concretos del mes, útil para acotar un evento inusual.', zh: '将分析限定为月份中的具体日期，适合聚焦某次异常事件。' },
  'lcz_anomaly.hour': { en: 'Restrict the analysis to specific hours of the day (0–23), for example isolating afternoon readings to study daytime heat buildup.', pt: 'Restringe a análise a horas específicas do dia (0–23), por exemplo isolando leituras vespertinas para estudar o acúmulo de calor diurno.', es: 'Restringe el análisis a horas concretas del día (0-23), por ejemplo aislando las lecturas de la tarde para estudiar la acumulación de calor diurno.', zh: '将分析限定为一天中的具体小时（0-23），例如只保留午后读数以研究白天热量积累。' },
  'lcz_anomaly.start': { en: 'The earliest date to include in the analysis, letting you cut off data before a certain point.', pt: 'A data mais antiga a incluir na análise, permitindo cortar dados anteriores a um determinado ponto.', es: 'La fecha más temprana a incluir en el análisis, para descartar datos anteriores a un punto determinado.', zh: '分析中要包含的最早日期，让你可以排除某个时间点之前的数据。' },
  'lcz_anomaly.end': { en: 'The latest date to include in the analysis, letting you cut off data after a certain point.', pt: 'A data mais recente a incluir na análise, permitindo cortar dados posteriores a um determinado ponto.', es: 'La fecha más tardía a incluir en el análisis, para descartar datos posteriores a un punto determinado.', zh: '分析中要包含的最晚日期，让你可以排除某个时间点之后的数据。' },
  'lcz_anomaly_map.x': { en: 'The classified LCZ raster that defines the exact grid, extent, and coordinate system the output anomaly map will be produced on.', pt: 'O raster LCZ classificado que define a grade, a extensão e o sistema de coordenadas exatos em que o mapa de anomalia de saída será produzido.', es: 'El ráster LCZ clasificado que define la cuadrícula, la extensión y el sistema de coordenadas exactos en los que se generará el mapa de anomalías.', zh: '定义输出异常地图确切网格、范围和坐标系统的 LCZ 分类栅格。' },
  'lcz_anomaly_map.data_frame': { en: 'The table of station observations to interpolate. It must include columns for latitude, longitude, date, the measured variable, and a station identifier.', pt: 'A tabela de observações das estações a interpolar. Deve incluir colunas de latitude, longitude, data, a variável medida e um identificador de estação.', es: 'La tabla de observaciones de estaciones a interpolar. Debe incluir columnas para latitud, longitud, fecha, la variable medida y un identificador de estación.', zh: '要插值的站点观测数据表，必须包含纬度、经度、日期、被测变量以及站点标识列。' },
  'lcz_anomaly_map.var': { en: 'The name of the column in your data holding the value to map, such as "temperature".', pt: 'O nome da coluna nos seus dados que contém o valor a mapear, como "temperature".', es: 'El nombre de la columna de sus datos que contiene el valor a mapear, como "temperature".', zh: '数据中保存待绘制数值的列名，例如“temperature”。' },
  'lcz_anomaly_map.station_id': { en: 'The name of the column that uniquely identifies each station.', pt: 'O nome da coluna que identifica exclusivamente cada estação.', es: 'El nombre de la columna que identifica de forma única a cada estación.', zh: '唯一标识每个站点的列名。' },
  'lcz_anomaly_map.sp_res': { en: 'The size of each output map pixel, in meters. For example, 100 produces a map with 100-meter grid cells; smaller values give finer detail but take longer to compute.', pt: 'O tamanho de cada pixel do mapa de saída, em metros. Por exemplo, 100 produz um mapa com células de grade de 100 metros; valores menores dão mais detalhe, mas levam mais tempo para calcular.', es: 'El tamaño de cada píxel del mapa de salida, en metros. Por ejemplo, 100 produce un mapa con celdas de 100 metros; valores más pequeños dan más detalle pero tardan más en calcularse.', zh: '输出地图每个像元的大小，单位为米。例如 100 会生成 100 米网格的地图；数值越小细节越丰富，但计算耗时也越长。' },
  'lcz_anomaly_map.tp_res': { en: 'How readings are averaged over time before mapping, for example "hour" (default) to produce one map per hour, or "day" to produce one map per day.', pt: 'Como as leituras são calculadas na média ao longo do tempo antes de mapear, por exemplo "hour" (padrão) para produzir um mapa por hora, ou "day" para produzir um mapa por dia.', es: 'Cómo se promedian las lecturas en el tiempo antes de mapear, por ejemplo "hour" (por defecto) para producir un mapa por hora, o "day" para un mapa por día.', zh: '在绘图前如何对读数进行时间平均，例如“hour”（默认，每小时生成一张地图）或“day”（每天生成一张地图）。' },
  'lcz_anomaly_map.by': { en: 'Groups all time steps within a category — such as "month", "season", or "weekday" versus "weekend" — and produces one averaged anomaly map per group instead of one map per time step. Leave unset to get a separate map for every individual time step.', pt: 'Agrupa todos os passos de tempo dentro de uma categoria — como "month", "season", ou "weekday" versus "weekend" — e produz um mapa de anomalia médio por grupo em vez de um mapa por passo de tempo. Deixe em branco para obter um mapa separado para cada passo de tempo individual.', es: 'Agrupa todos los pasos temporales dentro de una categoría —como "month", "season" o "weekday" frente a "weekend"— y produce un mapa de anomalía promediado por grupo en lugar de un mapa por cada paso temporal. Déjelo sin definir para obtener un mapa distinto por cada paso temporal individual.', zh: '按类别（如“month”“season”，或“weekday”对“weekend”）将所有时间步分组，为每组生成一张平均异常地图，而不是每个时间步一张。留空则为每个单独的时间步生成一张地图。' },
  'lcz_anomaly_map.method': { en: 'The interpolation technique used to fill the gaps between stations: "krige" (default, statistically optimal and can factor in each station\'s LCZ class as extra information, but requires the pykrige library), or the faster alternatives "rbf"/"idw" which ignore LCZ class and simply weight by distance.', pt: 'A técnica de interpolação usada para preencher os espaços entre estações: "krige" (padrão, estatisticamente ótima e capaz de considerar a classe LCZ de cada estação como informação adicional, mas exige a biblioteca pykrige), ou as alternativas mais rápidas "rbf"/"idw", que ignoram a classe LCZ e simplesmente ponderam por distância.', es: 'La técnica de interpolación usada para rellenar los espacios entre estaciones: "krige" (por defecto, estadísticamente óptima y capaz de incorporar la clase LCZ de cada estación como información adicional, pero requiere la biblioteca pykrige), o las alternativas más rápidas "rbf"/"idw", que ignoran la clase LCZ y simplemente ponderan según la distancia.', zh: '用于填补站点间空隙的插值技术：“krige”（默认，统计上最优，可以将每个站点的 LCZ 类别作为额外信息，但需要 pykrige 库），或速度更快的替代方案“rbf”/“idw”，它们不考虑 LCZ 类别，仅按距离加权。' },
  'lcz_anomaly_map.vg_model': { en: 'The mathematical curve shape used to describe how similarity between stations decays with distance, when using kriging: "Sph" (Spherical, a common general-purpose default), "Exp" (Exponential), "Gau" (Gaussian, smoother), or "Ste" (Matérn/Stein). Most users can leave this at the default unless a specific model fits their data better.', pt: 'O formato da curva matemática usada para descrever como a semelhança entre estações decai com a distância, ao usar krigagem: "Sph" (Esférico, um padrão geral comum), "Exp" (Exponencial), "Gau" (Gaussiano, mais suave), ou "Ste" (Matérn/Stein). A maioria dos usuários pode deixar no padrão, a menos que um modelo específico se ajuste melhor aos seus dados.', es: 'La forma matemática de la curva usada para describir cómo decae con la distancia la similitud entre estaciones, al usar kriging: "Sph" (esférico, un valor por defecto habitual de uso general), "Exp" (exponencial), "Gau" (gaussiano, más suave) o "Ste" (Matérn/Stein). La mayoría de los usuarios puede dejarlo en su valor por defecto salvo que un modelo concreto se ajuste mejor a sus datos.', zh: '使用克里金法时，用于描述站点间相似度随距离衰减规律的数学曲线形状：“Sph”（球状模型，常用的通用默认值）、“Exp”（指数模型）、“Gau”（高斯模型，更平滑）或“Ste”（马特恩/斯坦模型）。除非某个特定模型更适合你的数据，否则大多数用户可保持默认设置。' },
  'lcz_anomaly_map.isave': { en: 'When turned on, saves the resulting anomaly map as a GeoTIFF file to the LCZ4r_output folder instead of only keeping it in memory.', pt: 'Quando ativado, salva o mapa de anomalia resultante como um arquivo GeoTIFF na pasta de saída do aplicativo, em vez de mantê-lo apenas em memória.', es: 'Al activarlo, guarda el mapa de anomalías resultante como archivo GeoTIFF en la carpeta de salida de la aplicación en lugar de mantenerlo solo en memoria.', zh: '开启后会将生成的异常地图以 GeoTIFF 文件形式保存到应用的输出文件夹，而不只是保留在内存中。' },
  'lcz_anomaly_map.LCZinterp': { en: 'When turned on (default) and your stations span at least two different LCZ classes, the interpolation uses each station\'s zone type as extra information to produce a more realistic map. Turn it off to interpolate on distance alone.', pt: 'Quando ativado (padrão) e suas estações abrangem pelo menos duas classes LCZ diferentes, a interpolação usa o tipo de zona de cada estação como informação adicional para produzir um mapa mais realista. Desative para interpolar apenas com base na distância.', es: 'Cuando está activado (por defecto) y sus estaciones abarcan al menos dos clases LCZ distintas, la interpolación usa el tipo de zona de cada estación como información adicional para producir un mapa más realista. Desactívelo para interpolar solo por distancia.', zh: '开启此项（默认）且你的站点跨越至少两个不同的 LCZ 类别时，插值会将每个站点的区域类型作为额外信息，以生成更贴近实际的地图。关闭此项则仅按距离进行插值。' },
  'lcz_anomaly_map.n_jobs': { en: 'How many CPU cores to use for processing. The default (-1) uses every core available on your computer to finish faster; set it to a smaller number if you need to leave capacity for other tasks.', pt: 'Quantos núcleos de CPU usar no processamento. O padrão (-1) usa todos os núcleos disponíveis no computador para terminar mais rápido; defina um número menor se precisar deixar capacidade livre para outras tarefas.', es: 'Cuántos núcleos de CPU usar para el procesamiento. El valor por defecto (-1) usa todos los núcleos disponibles en su computadora para terminar más rápido; fíjelo en un número menor si necesita dejar capacidad para otras tareas.', zh: '用于处理的 CPU 核心数。默认值（-1）会使用电脑上所有可用核心以尽快完成；如果需要为其他任务保留处理能力，可设置为较小的数值。' },
  'lcz_anomaly_map.year': { en: 'Restrict the map to one or more specific years, for example 2022.', pt: 'Restringe o mapa a um ou mais anos específicos, por exemplo 2022.', es: 'Restringe el mapa a uno o varios años concretos, por ejemplo 2022.', zh: '将地图限定为一个或多个具体年份，例如 2022。' },
  'lcz_anomaly_map.month': { en: 'Restrict the map to specific calendar months (1–12), for example June–August only.', pt: 'Restringe o mapa a meses específicos do calendário (1–12), por exemplo apenas junho–agosto.', es: 'Restringe el mapa a meses del calendario concretos (1-12), por ejemplo solo junio-agosto.', zh: '将地图限定为具体的日历月份（1-12），例如仅限 6-8 月。' },
  'lcz_anomaly_map.day': { en: 'Restrict the map to specific days of the month.', pt: 'Restringe o mapa a dias específicos do mês.', es: 'Restringe el mapa a días concretos del mes.', zh: '将地图限定为月份中的具体日期。' },
  'lcz_anomaly_map.hour': { en: 'Restrict the map to specific hours of the day (0–23), for example afternoon hours only.', pt: 'Restringe o mapa a horas específicas do dia (0–23), por exemplo apenas horas da tarde.', es: 'Restringe el mapa a horas concretas del día (0-23), por ejemplo solo las horas de la tarde.', zh: '将地图限定为一天中的具体小时（0-23），例如仅限午后时段。' },
  'lcz_anomaly_map.start': { en: 'The earliest date to include when building the map.', pt: 'A data mais antiga a incluir na construção do mapa.', es: 'La fecha más temprana a incluir al construir el mapa.', zh: '构建地图时要包含的最早日期。' },
  'lcz_anomaly_map.end': { en: 'The latest date to include when building the map.', pt: 'A data mais recente a incluir na construção do mapa.', es: 'La fecha más tardía a incluir al construir el mapa.', zh: '构建地图时要包含的最晚日期。' },
  'lcz_anthropogenic_heat.lcz_classes': { en: 'The grid of LCZ class codes (1 to 17) for your study area, the same kind of raster produced by an LCZ classification map. Every cell\'s anthropogenic heat estimate is based on its LCZ code here.', pt: 'A grade de códigos de classe LCZ (1 a 17) da sua área de estudo, o mesmo tipo de raster produzido por um mapa de classificação LCZ. A estimativa de calor antropogênico de cada célula é baseada no seu código LCZ aqui.', es: 'La cuadrícula de códigos de clase LCZ (1 a 17) de su área de estudio, el mismo tipo de ráster producido por un mapa de clasificación LCZ. La estimación de calor antropogénico de cada celda se basa en su código LCZ aquí.', zh: '研究区的 LCZ 类别代码网格（1 至 17），与 LCZ 分类地图产生的栅格类型相同。此处每个像元的人为产热估算都基于其 LCZ 编码。' },
  'lcz_anthropogenic_heat.method': { en: 'Choose "simple" to use standard literature-based heat ranges per LCZ class (fast and works with just the class map), or "detailed" to compute heat from an actual energy balance using building surface fraction, impervious surface fraction, and roughness element height. Stick with "simple" unless you already have those extra building parameters on hand.', pt: 'Escolha "simple" para usar faixas de calor padrão baseadas na literatura por classe LCZ (rápido e funciona apenas com o mapa de classes), ou "detailed" para calcular o calor a partir de um balanço de energia real usando fração de superfície construída, fração de superfície impermeável e altura dos elementos de rugosidade. Fique com "simple" a menos que você já tenha esses parâmetros adicionais de edificação em mãos.', es: 'Elija "simple" para usar rangos de calor estándar basados en la literatura por clase LCZ (rápido y funciona solo con el mapa de clases), o "detailed" para calcular el calor a partir de un balance energético real usando la fracción de superficie construida, la fracción de superficie impermeable y la altura de los elementos de rugosidad. Manténgase en "simple" salvo que ya disponga de esos parámetros adicionales de los edificios.', zh: '选择“simple”使用基于文献的标准热量区间（速度快，仅需类别地图即可），或选择“detailed”，通过建筑表面比例、不透水面比例和粗糙元素高度计算真实的能量平衡。除非你已具备这些额外的建筑参数，否则建议使用“simple”。' },
  'lcz_anthropogenic_heat.params': { en: 'An optional way to override the default heat ranges used by the "simple" method, for example if local studies give you better numbers for your city. Provide a minimum and maximum watts-per-square-meter value for each LCZ class you want to override; leave this out to use the built-in defaults.', pt: 'Uma forma opcional de sobrepor as faixas de calor padrão usadas pelo método "simple", por exemplo se estudos locais fornecerem números melhores para sua cidade. Informe um valor mínimo e máximo em watts por metro quadrado para cada classe LCZ que você quiser sobrepor; deixe em branco para usar os padrões embutidos.', es: 'Una forma opcional de anular los rangos de calor por defecto usados por el método "simple", por ejemplo si estudios locales le dan mejores cifras para su ciudad. Indique un valor mínimo y máximo en vatios por metro cuadrado para cada clase LCZ que quiera sustituir; omítalo para usar los valores por defecto integrados.', zh: '一种可选方式，用于覆盖“simple”方法所用的默认热量区间，例如当地研究为你的城市提供了更准确的数值时。为想要覆盖的每个 LCZ 类别提供最小值和最大值（单位瓦特每平方米）；不提供则使用内置默认值。' },
  'lcz_cal_area.x': { en: 'The LCZ map you want to measure, given as a path to a GeoTIFF raster file (or an already-open raster). This is the classified map produced by an earlier LCZ mapping step.', pt: 'O mapa LCZ a medir, informado como caminho para um arquivo raster GeoTIFF (ou um raster já aberto). É o mapa classificado produzido por uma etapa anterior de mapeamento LCZ.', es: 'El mapa LCZ que quiere medir, indicado como ruta a un archivo ráster GeoTIFF (o un ráster ya abierto). Es el mapa clasificado producido en un paso previo de mapeo LCZ.', zh: '要测量的 LCZ 地图，以 GeoTIFF 栅格文件路径（或已打开的栅格）形式提供。这是此前 LCZ 制图步骤生成的分类地图。' },
  'lcz_cal_area.plot_type': { en: 'Which chart style to draw: "bar" (default, best for comparing exact areas), "pie" or "donut" (good for showing proportions at a glance), or "sunburst"/"treemap" (best when you have many classes and want a compact, hierarchical view).', pt: 'Qual estilo de gráfico desenhar: "bar" (padrão, melhor para comparar áreas exatas), "pie" ou "donut" (bons para mostrar proporções rapidamente), ou "sunburst"/"treemap" (melhores quando há muitas classes e você quer uma visão compacta e hierárquica).', es: 'Qué estilo de gráfico dibujar: "bar" (por defecto, ideal para comparar áreas exactas), "pie" o "donut" (buenos para mostrar proporciones de un vistazo), o "sunburst"/"treemap" (mejores cuando hay muchas clases y se quiere una vista compacta y jerárquica).', zh: '要绘制的图表样式：“bar”（默认，最适合比较精确面积）、“pie”或“donut”（适合一眼看出比例关系），或“sunburst”/“treemap”（适合类别较多、需要紧凑的层级视图时使用）。' },
  'lcz_cal_area.iplot': { en: 'Turn this off if you only want the underlying area-by-class table (a spreadsheet-like result) and don\'t need a chart drawn at all — useful when you plan to export the numbers elsewhere.', pt: 'Desative se você só quiser a tabela de área por classe (um resultado tipo planilha) e não precisar de gráfico algum — útil quando o plano é exportar os números para outro lugar.', es: 'Desactívelo si solo quiere la tabla subyacente de área por clase (un resultado tipo hoja de cálculo) y no necesita ningún gráfico, útil cuando piensa exportar los números a otro lugar.', zh: '如果你只想要底层的按类别面积表（类似电子表格的结果）而不需要绘制图表，可关闭此项——适合计划将数据导出到其他地方使用的场景。' },
  'lcz_cal_area.isave': { en: 'When turned on, saves both the chart image and a CSV table of areas to disk, so you have a permanent copy instead of just the on-screen view.', pt: 'Quando ativado, salva tanto a imagem do gráfico quanto uma tabela CSV de áreas em disco, para você ter uma cópia permanente e não apenas a visualização em tela.', es: 'Al activarlo, guarda tanto la imagen del gráfico como una tabla CSV de áreas en disco, para tener una copia permanente además de la vista en pantalla.', zh: '开启后会将图表图片和面积 CSV 表同时保存到磁盘，而不只是屏幕上的临时视图。' },
  'lcz_cal_area.save_extension': { en: 'The file format used when saving: "html" keeps the chart interactive (zoomable, hoverable) for viewing in a browser, while "png" or "pdf" produce a static image suitable for printing or inserting into a report.', pt: 'O formato de arquivo usado ao salvar: "html" mantém o gráfico interativo (com zoom e passagem do mouse) para ver no navegador, enquanto "png" ou "pdf" produzem uma imagem estática adequada para impressão ou inserção em um relatório.', es: 'El formato de archivo usado al guardar: "html" mantiene el gráfico interactivo (con zoom y datos al pasar el cursor) para verlo en un navegador, mientras que "png" o "pdf" producen una imagen estática apta para imprimir o insertar en un informe.', zh: '保存时使用的文件格式：“html”保留图表的交互性（可缩放、可悬停查看），适合在浏览器中查看；“png”或“pdf”则生成适合打印或插入报告的静态图片。' },
  'lcz_cal_area.show_legend': { en: 'Shows or hides the color-to-class legend on the chart. Interactive charts always keep the legend visible regardless of this setting.', pt: 'Mostra ou oculta a legenda de cor por classe no gráfico. Gráficos interativos sempre mantêm a legenda visível, independentemente desta configuração.', es: 'Muestra u oculta la leyenda de color por clase en el gráfico. Los gráficos interactivos siempre mantienen la leyenda visible, independientemente de este ajuste.', zh: '显示或隐藏图表上颜色与类别的对照图例。交互式图表始终保持图例可见，不受此设置影响。' },
  'lcz_cal_area.inclusive': { en: 'Switches to a colorblind-friendly version of the standard LCZ color palette, so class colors remain distinguishable for viewers with color vision deficiencies.', pt: 'Troca para uma versão adequada para daltônicos da paleta de cores LCZ padrão, para que as cores das classes permaneçam distinguíveis para pessoas com deficiência de percepção de cores.', es: 'Cambia a una versión apta para daltónicos de la paleta de colores estándar de LCZ, para que los colores de las clases sigan siendo distinguibles para personas con deficiencias en la visión del color.', zh: '切换为色盲友好版的标准 LCZ 配色方案，使各类别颜色对色觉障碍观众依然易于区分。' },
  'lcz_cal_area.use_duckdb': { en: 'Uses a fast in-memory database engine to add up pixel areas, which speeds things up considerably on large rasters. Leave this on unless you run into an environment where that engine isn\'t available.', pt: 'Usa um mecanismo de banco de dados rápido em memória para somar as áreas dos pixels, o que acelera bastante em rasters grandes. Deixe ativado a menos que você esteja em um ambiente onde esse mecanismo não esteja disponível.', es: 'Usa un motor de base de datos en memoria muy rápido para sumar las áreas de píxeles, lo que acelera considerablemente el proceso en rásteres grandes. Déjelo activado salvo que trabaje en un entorno donde ese motor no esté disponible.', zh: '使用快速的内存数据库引擎累加像元面积，在大型栅格上能显著提速。除非你的运行环境不支持该引擎，否则保持开启。' },
  'lcz_cal_area.use_geoarrow': { en: 'An internal setting that produces the results in a specific columnar data format (GeoArrow) for faster downstream processing. Most users can leave this at its default.', pt: 'Uma configuração interna que produz os resultados em um formato de dados colunar específico (GeoArrow) para processamento posterior mais rápido. A maioria dos usuários pode deixar no padrão.', es: 'Un ajuste interno que produce los resultados en un formato de datos columnar específico (GeoArrow) para un procesamiento posterior más rápido. La mayoría de los usuarios puede dejarlo en su valor por defecto.', zh: '一项内部设置，以特定的列式数据格式（GeoArrow）生成结果，便于后续处理提速。大多数用户可保持默认设置。' },
  'lcz_cal_area.xlab': { en: 'The text label shown on the horizontal axis of a bar chart, for example "LCZ code". Only applies when plot_type is "bar".', pt: 'O rótulo de texto exibido no eixo horizontal de um gráfico de barras, por exemplo "Código LCZ". Aplica-se apenas quando plot_type é "bar".', es: 'El texto mostrado en el eje horizontal de un gráfico de barras, por ejemplo "Código LCZ". Solo se aplica cuando plot_type es "bar".', zh: '条形图水平轴上显示的文字标签，例如“LCZ 编码”。仅在 plot_type 为“bar”时生效。' },
  'lcz_cal_area.ylab': { en: 'The text label shown on the vertical axis of a bar chart, for example "Area [km²]". Only applies when plot_type is "bar".', pt: 'O rótulo de texto exibido no eixo vertical de um gráfico de barras, por exemplo "Área [km²]". Aplica-se apenas quando plot_type é "bar".', es: 'El texto mostrado en el eje vertical de un gráfico de barras, por ejemplo "Área [km²]". Solo se aplica cuando plot_type es "bar".', zh: '条形图垂直轴上显示的文字标签，例如“面积 [km²]”。仅在 plot_type 为“bar”时生效。' },
  'lcz_cal_area.title': { en: 'Custom title text to display above the chart, replacing the automatically generated one.', pt: 'Texto de título personalizado a exibir acima do gráfico, substituindo o título gerado automaticamente.', es: 'Texto de título personalizado para mostrar encima del gráfico, en lugar del generado automáticamente.', zh: '显示在图表上方的自定义标题文字，替换自动生成的标题。' },
  'lcz_cal_area.subtitle': { en: 'Optional secondary line of text shown just below the title, useful for adding context such as the study area name or date.', pt: 'Linha secundária de texto opcional exibida logo abaixo do título, útil para adicionar contexto como o nome da área de estudo ou a data.', es: 'Línea secundaria de texto opcional mostrada justo debajo del título, útil para añadir contexto como el nombre del área de estudio o la fecha.', zh: '显示在标题正下方的可选副标题文字，适合补充研究区名称或日期等背景信息。' },
  'lcz_cal_area.caption': { en: 'Optional small note shown below the chart, for example a data source citation or units clarification.', pt: 'Nota pequena opcional exibida abaixo do gráfico, por exemplo uma citação da fonte de dados ou esclarecimento de unidades.', es: 'Nota opcional de letra pequeña mostrada debajo del gráfico, por ejemplo una cita de la fuente de datos o una aclaración de unidades.', zh: '显示在图表下方的可选小字说明，例如数据来源引用或单位说明。' },
  'lcz_cal_indexes.x': { en: 'The LCZ map file (GeoTIFF) that your gridded data was cropped to match, for example the same map you used when downloading the CHIRPS or ERA5 grid.', pt: 'O arquivo de mapa LCZ (GeoTIFF) ao qual seus dados em grade foram recortados para corresponder, por exemplo o mesmo mapa que você usou ao baixar a grade CHIRPS ou ERA5.', es: 'El archivo de mapa LCZ (GeoTIFF) con el que se recortaron sus datos en cuadrícula, por ejemplo el mismo mapa que usó al descargar la cuadrícula de CHIRPS o ERA5.', zh: '你的网格化数据所裁剪匹配的 LCZ 地图文件（GeoTIFF），例如你在下载 CHIRPS 或 ERA5 网格时使用的同一张地图。' },
  'lcz_cal_indexes.grid_result': { en: 'The gridded variable to summarize, i.e. the result you got back from a grid-download function such as the CHIRPS or ERA5 grid tools.', pt: 'A variável em grade a resumir, ou seja, o resultado que você obteve de uma função de download de grade, como as ferramentas de grade CHIRPS ou ERA5.', es: 'La variable en cuadrícula a resumir, es decir, el resultado que obtuvo de una función de descarga de cuadrícula como las herramientas de CHIRPS o ERA5.', zh: '要汇总的网格化变量，即你从网格下载功能（如 CHIRPS 或 ERA5 网格工具）获得的结果。' },
  'lcz_cal_indexes.band': { en: 'Which single time-slice or band of the grid to summarize, chosen by number or by its label. Leave this unset (the default) to pool all bands together, e.g. to summarize an entire year of daily rainfall at once instead of one day.', pt: 'Qual fatia de tempo ou banda única da grade resumir, escolhida por número ou por seu rótulo. Deixe sem definir (padrão) para agrupar todas as bandas juntas, por exemplo para resumir um ano inteiro de chuva diária de uma só vez, em vez de um único dia.', es: 'Qué banda o instante temporal único de la cuadrícula resumir, elegido por número o por su etiqueta. Déjelo sin definir (por defecto) para agrupar todas las bandas juntas, por ejemplo para resumir un año entero de lluvia diaria de una sola vez en lugar de un solo día.', zh: '要汇总的网格单一时间切片或波段，可按编号或标签选择。留空（默认）则将所有波段合并汇总，例如一次性汇总一整年的逐日降水量而不是仅一天的数据。' },
  'lcz_cal_indexes.variable_name': { en: 'A label used to identify the variable in the output table and chart, such as "rainfall" or "LST". If left blank, a name is generated automatically from the data.', pt: 'Um rótulo usado para identificar a variável na tabela e no gráfico de saída, como "chuva" ou "LST". Se deixado em branco, um nome é gerado automaticamente a partir dos dados.', es: 'Una etiqueta usada para identificar la variable en la tabla y el gráfico de salida, como "lluvia" o "LST". Si se deja en blanco, se genera un nombre automáticamente a partir de los datos.', zh: '用于在输出表格和图表中标识该变量的标签，例如“降水”或“LST”。留空则根据数据自动生成名称。' },
  'lcz_cal_indexes.inclusive': { en: 'Switch on to use the colorblind-friendly version of the standard LCZ color scheme in the chart.', pt: 'Ative para usar a versão adequada para daltônicos do esquema de cores LCZ padrão no gráfico.', es: 'Actívelo para usar la versión apta para daltónicos del esquema de colores LCZ estándar en el gráfico.', zh: '开启后在图表中使用色盲友好版的标准 LCZ 配色方案。' },
  'lcz_cal_indexes.iplot': { en: 'Turn off if you only want the summary table back and don\'t need the chart, which can save time for large datasets.', pt: 'Desative se você só quiser a tabela-resumo de volta e não precisar do gráfico, o que pode economizar tempo em conjuntos de dados grandes.', es: 'Desactívelo si solo quiere la tabla de resumen y no necesita el gráfico, lo que puede ahorrar tiempo con conjuntos de datos grandes.', zh: '如果你只想要汇总表而不需要图表，可关闭此项，这对于大型数据集能节省时间。' },
  'lcz_cal_indexes.isave': { en: 'Turn on to save both the chart and the underlying data table to a folder named LCZ4r_output so you can reuse them later or share them.', pt: 'Ative para salvar tanto o gráfico quanto a tabela de dados subjacente em uma pasta chamada LCZ4r_output, para que você possa reutilizá-los depois ou compartilhá-los.', es: 'Actívelo para guardar tanto el gráfico como la tabla de datos subyacente en una carpeta llamada LCZ4r_output, para poder reutilizarlos más tarde o compartirlos.', zh: '开启后会将图表和底层数据表都保存到名为 LCZ4r_output 的文件夹，便于日后重复使用或分享。' },
  'lcz_cal_indexes.save_extension': { en: 'The file format for the saved chart: "html" (the default) produces an interactive chart you can zoom and pan in a browser, while an image format such as "png" produces a static picture suitable for a report or slide.', pt: 'O formato de arquivo para o gráfico salvo: "html" (padrão) produz um gráfico interativo que você pode ampliar e mover no navegador, enquanto um formato de imagem como "png" produz uma imagem estática adequada para um relatório ou slide.', es: 'El formato de archivo para el gráfico guardado: "html" (por defecto) produce un gráfico interactivo que se puede acercar y desplazar en un navegador, mientras que un formato de imagen como "png" produce una imagen estática apta para un informe o una diapositiva.', zh: '保存图表所用的文件格式：“html”（默认）生成可在浏览器中缩放平移的交互式图表，而“png”等图片格式生成适合报告或幻灯片的静态图片。' },
  'lcz_cal_indices.lcz_map': { en: 'The LCZ classification map (GeoTIFF, classes 1-17) that lines up pixel-for-pixel with the indices you\'re summarizing.', pt: 'O mapa de classificação LCZ (GeoTIFF, classes 1-17) que está alinhado pixel a pixel com os índices que você está resumindo.', es: 'El mapa de clasificación LCZ (GeoTIFF, clases 1-17) que coincide píxel a píxel con los índices que está resumiendo.', zh: '与你要汇总的指数逐像元对齐的 LCZ 分类地图（GeoTIFF，类别 1-17）。' },
  'lcz_cal_indices.indices_x': { en: 'The spectral indices to summarize, given either as the file path to the index stack or as the result object returned directly by lcz_get_indices.', pt: 'Os índices espectrais a resumir, informados como o caminho de arquivo da pilha de índices ou como o objeto de resultado retornado diretamente por lcz_get_indices.', es: 'Los índices espectrales a resumir, indicados ya sea como la ruta al archivo de la pila de índices o como el objeto resultado devuelto directamente por lcz_get_indices.', zh: '要汇总的光谱指数，可以是指数堆栈文件的路径，也可以是 lcz_get_indices 直接返回的结果对象。' },
  'lcz_cal_indices.indices': { en: 'Which specific indices to include, such as ["NDVI", "NDBI"]. Leave unset to use every index available in indices_x; note that a scatter plot needs its x, y, and (optional) size indices included in this list if you set it.', pt: 'Quais índices específicos incluir, como ["NDVI", "NDBI"]. Deixe em branco para usar todos os índices disponíveis em indices_x; observe que um gráfico de dispersão precisa que seus índices x, y e (opcional) de tamanho estejam incluídos nesta lista, caso você a defina.', es: 'Qué índices concretos incluir, como ["NDVI", "NDBI"]. Déjelo sin definir para usar todos los índices disponibles en indices_x; tenga en cuenta que un gráfico de dispersión necesita que sus índices x, y y (opcionalmente) de tamaño estén incluidos en esta lista si la fija.', zh: '要包含的具体指数，例如 ["NDVI", "NDBI"]。留空则使用 indices_x 中的所有可用指数；注意如果设置此项，散点图所需的 x、y 以及（可选的）size 指数都必须包含在此列表中。' },
  'lcz_cal_indices.plot_type': { en: 'The kind of chart to produce: "box" shows the distribution of values per LCZ class, "bar" shows the class average with a confidence interval, "scatter" plots one index against another (colored by LCZ class), "radar" compares multiple indices per class on a spider chart, "correlation" shows how indices relate to each other, "effect_size" ranks how strongly each index separates built-up from natural zones, and "all" produces every applicable chart at once. "both" returns both the box and bar charts together.', pt: 'O tipo de gráfico a produzir: "box" mostra a distribuição de valores por classe LCZ, "bar" mostra a média da classe com um intervalo de confiança, "scatter" plota um índice contra outro (colorido por classe LCZ), "radar" compara vários índices por classe em um gráfico tipo aranha, "correlation" mostra como os índices se relacionam entre si, "effect_size" ranqueia o quanto cada índice separa zonas construídas de zonas naturais, e "all" produz todos os gráficos aplicáveis de uma vez. "both" retorna os gráficos de caixa e de barras juntos.', es: 'El tipo de gráfico a producir: "box" muestra la distribución de valores por clase LCZ, "bar" muestra el promedio de cada clase con un intervalo de confianza, "scatter" grafica un índice frente a otro (coloreado por clase LCZ), "radar" compara varios índices por clase en un gráfico de araña, "correlation" muestra cómo se relacionan los índices entre sí, "effect_size" clasifica cuán fuertemente separa cada índice lo construido de las zonas naturales, y "all" produce todos los gráficos aplicables a la vez. "both" devuelve juntos el gráfico de caja y el de barras.', zh: '要生成的图表类型：“box”展示每个 LCZ 类别的数值分布，“bar”展示类别平均值及其置信区间，“both”同时返回箱形图和条形图，“scatter”将一个指数相对于另一个指数绘制（按 LCZ 类别着色），“radar”在蜘蛛图上比较各类别的多个指数，“correlation”展示指数之间的相关关系，“effect_size”按各指数区分建成区与自然区域的能力排序，“all”一次性生成所有适用图表。' },
  'lcz_cal_indices.index_x': { en: 'The index to plot on the horizontal axis; only needed when plot_type is "scatter", for example "NDVI" against a built-up index.', pt: 'O índice a plotar no eixo horizontal; necessário apenas quando plot_type é "scatter", por exemplo "NDVI" contra um índice de área construída.', es: 'El índice a graficar en el eje horizontal; solo se necesita cuando plot_type es "scatter", por ejemplo "NDVI" frente a un índice de área construida.', zh: '水平轴上绘制的指数；仅在 plot_type 为“scatter”时需要，例如以 NDVI 对照某个建成指数。' },
  'lcz_cal_indices.index_y': { en: 'The index to plot on the vertical axis; only needed when plot_type is "scatter", for example "NDBI".', pt: 'O índice a plotar no eixo vertical; necessário apenas quando plot_type é "scatter", por exemplo "NDBI".', es: 'El índice a graficar en el eje vertical; solo se necesita cuando plot_type es "scatter", por ejemplo "NDBI".', zh: '垂直轴上绘制的指数；仅在 plot_type 为“scatter”时需要，例如“NDBI”。' },
  'lcz_cal_indices.size_by': { en: 'An optional third index that controls the size of each point in the scatter plot, useful for showing a third dimension such as land-surface temperature alongside NDVI vs. NDBI.', pt: 'Um terceiro índice opcional que controla o tamanho de cada ponto no gráfico de dispersão, útil para mostrar uma terceira dimensão, como temperatura de superfície, junto com NDVI vs. NDBI.', es: 'Un tercer índice opcional que controla el tamaño de cada punto en el gráfico de dispersión, útil para mostrar una tercera dimensión, como la temperatura de superficie junto con NDVI frente a NDBI.', zh: '可选的第三个指数，用于控制散点图中每个点的大小，便于在 NDVI 与 NDBI 的对比之外展示第三个维度，例如地表温度。' },
  'lcz_cal_indices.lcz_classes': { en: 'Restrict the radar chart to specific LCZ classes, such as [1, 2, 6, 11] to compare only compact urban forms against dense trees. Leave unset to include every class present in your data.', pt: 'Restringe o gráfico radar a classes LCZ específicas, como [1, 2, 6, 11], para comparar apenas formas urbanas compactas contra árvores densas. Deixe em branco para incluir todas as classes presentes nos seus dados.', es: 'Restringe el gráfico de radar a clases LCZ concretas, como [1, 2, 6, 11] para comparar solo formas urbanas compactas frente a árboles densos. Déjelo sin definir para incluir todas las clases presentes en sus datos.', zh: '将雷达图限定为特定的 LCZ 类别，例如 [1, 2, 6, 11]，只比较紧凑城市形态与密林之间的差异。留空则包含数据中出现的所有类别。' },
  'lcz_cal_indices.normalize_radar': { en: 'Rescale each index onto a common 0-1 axis on the radar chart so indices with very different natural ranges (like NDVI\'s -1 to 1 versus a soil index in the hundreds) remain visually comparable. Leave this on unless you specifically need the original units shown.', pt: 'Reescala cada índice para um eixo comum de 0 a 1 no gráfico radar, para que índices com faixas naturais muito diferentes (como o NDVI de -1 a 1 versus um índice de solo na casa das centenas) permaneçam comparáveis visualmente. Deixe ativado a menos que você precise especificamente ver as unidades originais.', es: 'Reescala cada índice a un eje común de 0 a 1 en el gráfico de radar, para que índices con rangos naturales muy distintos (como el NDVI, de -1 a 1, frente a un índice de suelo en cientos) sigan siendo comparables visualmente. Déjelo activado salvo que necesite específicamente ver las unidades originales.', zh: '在雷达图上将每个指数重新缩放到统一的 0-1 坐标轴，使自然量程差异很大的指数（如 NDVI 的 -1 到 1 与数值可达数百的土壤指数）在视觉上仍可比较。除非你特别需要显示原始单位，否则保持开启。' },
  'lcz_cal_indices.iplot': { en: 'Turn off if you only want the statistics table back without generating any chart.', pt: 'Desative se você só quiser a tabela de estatísticas de volta, sem gerar gráfico algum.', es: 'Desactívelo si solo quiere la tabla de estadísticas sin generar ningún gráfico.', zh: '如果你只想要统计表而不需要生成任何图表，可关闭此项。' },
  'lcz_cal_indices.isave': { en: 'Turn on to save the chart(s) and the underlying statistics table to the LCZ4r_output folder.', pt: 'Ative para salvar o(s) gráfico(s) e a tabela de estatísticas subjacente na pasta LCZ4r_output.', es: 'Actívelo para guardar el gráfico o gráficos y la tabla de estadísticas subyacente en la carpeta LCZ4r_output.', zh: '开启后会将图表和底层统计表保存到 LCZ4r_output 文件夹。' },
  'lcz_cal_indices.save_extension': { en: 'The file format to save charts in: "html" for an interactive chart, or "png"/"pdf" for a static image suitable for a publication.', pt: 'O formato de arquivo para salvar gráficos: "html" para um gráfico interativo, ou "png"/"pdf" para uma imagem estática adequada para uma publicação.', es: 'El formato de archivo para guardar los gráficos: "html" para un gráfico interactivo, o "png"/"pdf" para una imagen estática apta para una publicación.', zh: '保存图表所用的文件格式：“html”为交互式图表，“png”/“pdf”为适合出版物使用的静态图片。' },
  'lcz_cal_indices.inclusive': { en: 'Switch on to use the colorblind-friendly version of the standard LCZ color scheme.', pt: 'Ative para usar a versão adequada para daltônicos do esquema de cores LCZ padrão.', es: 'Actívelo para usar la versión apta para daltónicos del esquema de colores LCZ estándar.', zh: '开启后使用色盲友好版的标准 LCZ 配色方案。' },
  'lcz_cal_indices.confidence': { en: 'The confidence level used for the error bars on the bar chart, for example 0.95 for a standard 95% confidence interval.', pt: 'O nível de confiança usado para as barras de erro no gráfico de barras, por exemplo 0,95 para um intervalo de confiança padrão de 95%.', es: 'El nivel de confianza usado para las barras de error en el gráfico de barras, por ejemplo 0,95 para un intervalo de confianza estándar del 95%.', zh: '条形图误差棒所用的置信水平，例如 0.95 表示标准的 95% 置信区间。' },
  'lcz_cal_indices.title': { en: 'Optional custom title text to add above the chart.', pt: 'Texto de título personalizado opcional a adicionar acima do gráfico.', es: 'Texto de título personalizado opcional para añadir encima del gráfico.', zh: '在图表上方添加的可选自定义标题文字。' },
  'lcz_cal_indices.subtitle': { en: 'Optional custom subtitle text to add below the title.', pt: 'Texto de subtítulo personalizado opcional a adicionar abaixo do título.', es: 'Texto de subtítulo personalizado opcional para añadir debajo del título.', zh: '在标题下方添加的可选自定义副标题文字。' },
  'lcz_cal_indices.caption': { en: 'Optional custom caption text to add below the chart, useful for citing a data source.', pt: 'Texto de legenda personalizado opcional a adicionar abaixo do gráfico, útil para citar uma fonte de dados.', es: 'Texto de nota al pie personalizado opcional para añadir debajo del gráfico, útil para citar una fuente de datos.', zh: '在图表下方添加的可选自定义说明文字，适合注明数据来源。' },
  'lcz_clear_cache.cache_dir': { en: 'The folder to clear. Leave this unset to clear the default cache location used by other functions; only set it if you previously used a custom cache folder.', pt: 'A pasta a ser limpa. Deixe em branco para limpar o local de cache padrão usado pelas outras funções; defina apenas se você tiver usado anteriormente uma pasta de cache personalizada.', es: 'La carpeta que se va a limpiar. Déjela sin definir para limpiar la ubicación de caché por defecto que usan las demás funciones; defínala solo si antes usó una carpeta de caché personalizada.', zh: '要清除的文件夹。留空则清除其他功能使用的默认缓存位置；只有此前使用过自定义缓存文件夹时才需要设置此项。' },
  'lcz_climate_compute_spei.df': { en: 'The input table of monthly climate data. It must contain a municipality code column, a monthly date column, a rainfall column, and either a pre-computed evapotranspiration column or a temperature column (depending on pet_method).', pt: 'A tabela de entrada de dados climáticos mensais. Deve conter uma coluna de código do município, uma coluna de data mensal, uma coluna de chuva e, dependendo de pet_method, uma coluna de evapotranspiração já calculada ou uma coluna de temperatura.', es: 'La tabla de entrada con datos climáticos mensuales. Debe contener una columna de código de municipio, una columna de fecha mensual, una columna de lluvia y, según pet_method, ya sea una columna de evapotranspiración precalculada o una columna de temperatura.', zh: '月度气候数据输入表，必须包含市镇代码列、月度日期列、降雨量列，以及一个预先计算好的蒸散量列或气温列（取决于 pet_method）。' },
  'lcz_climate_compute_spei.rain_var': { en: 'The name of the column holding monthly rainfall totals in millimeters, for example "rainfall_chirps_mm" (the default).', pt: 'O nome da coluna que contém os totais mensais de chuva em milímetros, por exemplo "rainfall_chirps_mm" (padrão).', es: 'El nombre de la columna que contiene los totales de lluvia mensual en milímetros, por ejemplo "rainfall_chirps_mm" (valor por defecto).', zh: '保存月度降雨总量（毫米）的列名，例如“rainfall_chirps_mm”（默认）。' },
  'lcz_climate_compute_spei.pet_var': { en: 'The name of the column holding monthly potential evapotranspiration in millimeters, used only when pet_method is set to "column" (i.e., you\'re supplying pre-computed evapotranspiration rather than having it estimated).', pt: 'O nome da coluna que contém a evapotranspiração potencial mensal em milímetros, usada somente quando pet_method é "column" (ou seja, quando você fornece a evapotranspiração já calculada em vez de estimá-la).', es: 'El nombre de la columna que contiene la evapotranspiración potencial mensual en milímetros, usada solo cuando pet_method está fijado en "column" (es decir, cuando usted aporta la evapotranspiración ya calculada en lugar de que se estime).', zh: '保存月度潜在蒸散量（毫米）的列名，仅在 pet_method 设为“column”时使用（即你直接提供预先计算好的蒸散量，而不是让函数估算）。' },
  'lcz_climate_compute_spei.pet_method': { en: 'How evapotranspiration is obtained: "column" (default, reads it directly from pet_var) or "thornthwaite" (estimates it from monthly temperature using the Thornthwaite formula, so you don\'t need separate evapotranspiration data).', pt: 'Como a evapotranspiração é obtida: "column" (padrão, lê diretamente de pet_var) ou "thornthwaite" (estima a partir da temperatura média mensal usando a fórmula de Thornthwaite, dispensando dados de evapotranspiração separados).', es: 'Cómo se obtiene la evapotranspiración: "column" (por defecto, la lee directamente de pet_var) o "thornthwaite" (la estima a partir de la temperatura media mensual usando la fórmula de Thornthwaite, así no necesita datos de evapotranspiración por separado).', zh: '蒸散量的获取方式：“column”（默认，直接从 pet_var 读取）或“thornthwaite”（使用 Thornthwaite 公式根据月度气温估算蒸散量，因此无需单独的蒸散数据）。' },
  'lcz_climate_compute_spei.temp_var': { en: 'The name of the column holding monthly mean temperature in Celsius, used only when pet_method is "thornthwaite" to estimate evapotranspiration.', pt: 'O nome da coluna que contém a temperatura média mensal em Celsius, usada somente quando pet_method é "thornthwaite" para estimar a evapotranspiração.', es: 'El nombre de la columna que contiene la temperatura media mensual en grados Celsius, usada solo cuando pet_method es "thornthwaite" para estimar la evapotranspiración.', zh: '保存月度平均气温（摄氏度）的列名，仅在 pet_method 为“thornthwaite”时用于估算蒸散量。' },
  'lcz_climate_compute_spei.scales': { en: 'The list of timescales, in months, at which to compute SPEI, for example [1, 3, 6, 12] (the default) to get short-term (1-month), seasonal (3- and 6-month), and annual (12-month) drought signals together.', pt: 'A lista de escalas de tempo, em meses, nas quais calcular o SPEI, por exemplo [1, 3, 6, 12] (padrão) para obter sinais de seca de curto prazo (1 mês), sazonais (3 e 6 meses) e anuais (12 meses) ao mesmo tempo.', es: 'La lista de escalas temporales, en meses, en las que calcular el SPEI, por ejemplo [1, 3, 6, 12] (valor por defecto) para obtener juntas señales de sequía de corto plazo (1 mes), estacionales (3 y 6 meses) y anuales (12 meses).', zh: '计算 SPEI 的时间尺度列表，单位为月，例如 [1, 3, 6, 12]（默认），可同时得到短期（1 个月）、季节性（3、6 个月）和年度（12 个月）的干旱信号。' },
  'lcz_climate_compute_spei.ref_start': { en: 'The start date of the reference period used to calibrate what counts as "normal" versus "dry"/"wet". Leave unset to calibrate using your entire dataset.', pt: 'A data inicial do período de referência usado para calibrar o que conta como "normal" versus "seco"/"úmido". Deixe em branco para calibrar usando todo o seu conjunto de dados.', es: 'La fecha de inicio del periodo de referencia usado para calibrar qué se considera "normal" frente a "seco"/"húmedo". Déjela sin definir para calibrar usando todo su conjunto de datos.', zh: '用于校准“正常”与“干旱/湿润”标准的参照期起始日期。留空则使用你的全部数据集进行校准。' },
  'lcz_climate_compute_spei.ref_end': { en: 'The end date of the calibration reference period. Leave unset to calibrate using your entire dataset.', pt: 'A data final do período de referência de calibração. Deixe em branco para calibrar usando todo o seu conjunto de dados.', es: 'La fecha de fin del periodo de referencia de calibración. Déjela sin definir para calibrar usando todo su conjunto de datos.', zh: '校准参照期的结束日期。留空则使用你的全部数据集进行校准。' },
  'lcz_climate_compute_spei.min_n': { en: 'The minimum number of valid monthly values a municipality must have in the calibration period to compute a reliable index; municipalities with fewer are skipped. The default of 24 requires at least two years of data.', pt: 'O número mínimo de valores mensais válidos que um município deve ter no período de calibração para que um índice confiável seja calculado; municípios com menos valores são ignorados. O padrão de 24 exige pelo menos dois anos de dados.', es: 'El número mínimo de valores mensuales válidos que debe tener un municipio en el periodo de calibración para calcular un índice fiable; los municipios con menos se omiten. El valor por defecto de 24 exige al menos dos años de datos.', zh: '市镇在校准期内必须具备的最少有效月度数值数量，才能计算出可靠的指数；不足此数的市镇将被跳过。默认值 24 要求至少两年的数据。' },
  'lcz_climate_compute_spei.verbose': { en: 'When turned on (default), prints progress messages while the calculation runs, which is useful for tracking long computations over many municipalities.', pt: 'Quando ativado (padrão), imprime mensagens de progresso durante o cálculo, útil para acompanhar processamentos longos envolvendo muitos municípios.', es: 'Cuando está activado (por defecto), imprime mensajes de progreso mientras se ejecuta el cálculo, útil para seguir cómputos largos sobre muchos municipios.', zh: '开启时（默认），计算过程中会打印进度信息，便于跟踪涉及多个市镇的长时间计算。' },
  'lcz_climate_compute_spi.df': { en: 'The input table of monthly rainfall data. It must contain a municipality code column, a monthly date column, and a precipitation column — typically the output of a monthly rainfall extraction step such as lcz_grid_chirps.', pt: 'A tabela de entrada de dados mensais de chuva. Deve conter uma coluna de código do município, uma coluna de data mensal e uma coluna de precipitação — normalmente a saída de uma etapa de extração de chuva mensal como o lcz_grid_chirps.', es: 'La tabla de entrada con datos mensuales de lluvia. Debe contener una columna de código de municipio, una columna de fecha mensual y una columna de precipitación, típicamente la salida de un paso de extracción de lluvia mensual como lcz_grid_chirps.', zh: '月度降雨数据输入表，必须包含市镇代码列、月度日期列和降水量列——通常是月度降雨提取步骤（如 lcz_grid_chirps）的输出。' },
  'lcz_climate_compute_spi.var': { en: 'The name of the column holding monthly rainfall totals in millimeters, for example "rainfall_chirps_mm" (the default).', pt: 'O nome da coluna que contém os totais mensais de chuva em milímetros, por exemplo "rainfall_chirps_mm" (padrão).', es: 'El nombre de la columna que contiene los totales de lluvia mensual en milímetros, por ejemplo "rainfall_chirps_mm" (valor por defecto).', zh: '保存月度降雨总量（毫米）的列名，例如“rainfall_chirps_mm”（默认）。' },
  'lcz_climate_compute_spi.scales': { en: 'The list of timescales, in months, at which to compute SPI, for example [1, 3, 6, 12] (the default) to capture both short-term and long-term drought conditions.', pt: 'A lista de escalas de tempo, em meses, nas quais calcular o SPI, por exemplo [1, 3, 6, 12] (padrão) para capturar condições de seca de curto e de longo prazo.', es: 'La lista de escalas temporales, en meses, en las que calcular el SPI, por ejemplo [1, 3, 6, 12] (valor por defecto) para captar condiciones de sequía tanto de corto como de largo plazo.', zh: '计算 SPI 的时间尺度列表，单位为月，例如 [1, 3, 6, 12]（默认），可同时捕捉短期和长期的干旱状况。' },
  'lcz_climate_compute_spi.ref_start': { en: 'The start date of the reference period used to fit the statistical model of "normal" rainfall. Leave unset to use your entire dataset; the World Meteorological Organization recommends at least 30 years of data for a stable result.', pt: 'A data inicial do período de referência usado para ajustar o modelo estatístico de chuva "normal". Deixe em branco para usar todo o seu conjunto de dados; a Organização Meteorológica Mundial recomenda pelo menos 30 anos de dados para um resultado estável.', es: 'La fecha de inicio del periodo de referencia usado para ajustar el modelo estadístico de la lluvia "normal". Déjela sin definir para usar todo su conjunto de datos; la Organización Meteorológica Mundial recomienda al menos 30 años de datos para un resultado estable.', zh: '用于拟合“正常”降雨统计模型的参照期起始日期。留空则使用你的全部数据集；世界气象组织建议至少使用 30 年的数据以获得稳定结果。' },
  'lcz_climate_compute_spi.ref_end': { en: 'The end date of the reference calibration period. Leave unset to use your entire dataset.', pt: 'A data final do período de referência de calibração. Deixe em branco para usar todo o seu conjunto de dados.', es: 'La fecha de fin del periodo de referencia de calibración. Déjela sin definir para usar todo su conjunto de datos.', zh: '参照校准期的结束日期。留空则使用你的全部数据集。' },
  'lcz_climate_compute_spi.min_n': { en: 'The minimum number of valid monthly rainfall values a municipality must have in the calibration period before an index is computed for it; municipalities with fewer are skipped. The default of 24 requires at least two years of data.', pt: 'O número mínimo de valores mensais de chuva válidos que um município deve ter no período de calibração antes de um índice ser calculado para ele; municípios com menos valores são ignorados. O padrão de 24 exige pelo menos dois anos de dados.', es: 'El número mínimo de valores mensuales válidos de lluvia que debe tener un municipio en el periodo de calibración antes de calcularle un índice; los municipios con menos se omiten. El valor por defecto de 24 exige al menos dos años de datos.', zh: '在校准期内，市镇必须具备的最少有效月度降雨数值数量，才会为其计算指数；不足此数的市镇将被跳过。默认值 24 要求至少两年的数据。' },
  'lcz_climate_compute_spi.verbose': { en: 'When turned on (default), prints progress messages while the calculation runs, useful for tracking progress across many municipalities.', pt: 'Quando ativado (padrão), imprime mensagens de progresso durante o cálculo, útil para acompanhar o andamento em muitos municípios.', es: 'Cuando está activado (por defecto), imprime mensajes de progreso mientras se ejecuta el cálculo, útil para seguir el avance en muchos municipios.', zh: '开启时（默认），计算过程中会打印进度信息，便于跟踪涉及多个市镇的处理进度。' },
  'lcz_degree_hours.x': { en: 'The LCZ raster map used to determine which LCZ class each weather station falls into, based on its location.', pt: 'O raster LCZ usado para determinar em qual classe LCZ cada estação meteorológica se encontra, com base em sua localização.', es: 'El mapa ráster LCZ usado para determinar en qué clase LCZ cae cada estación meteorológica, según su ubicación.', zh: '根据位置判断每个气象站所属 LCZ 类别的 LCZ 栅格地图。' },
  'lcz_degree_hours.data_frame': { en: 'Your table of station observations, with columns for date, station ID, the variable being measured, and each station\'s latitude/longitude.', pt: 'Sua tabela de observações de estações, com colunas para data, ID da estação, a variável medida e latitude/longitude de cada estação.', es: 'Su tabla de observaciones de estaciones, con columnas para fecha, identificador de estación, la variable medida y la latitud/longitud de cada estación.', zh: '你的站点观测数据表，包含日期、站点 ID、被测变量以及每个站点的经纬度列。' },
  'lcz_degree_hours.var': { en: 'The name of the column holding the temperature values to use for the calculation, for example "temp_c".', pt: 'O nome da coluna que contém os valores de temperatura usados no cálculo, por exemplo "temp_c".', es: 'El nombre de la columna que contiene los valores de temperatura a usar en el cálculo, por ejemplo "temp_c".', zh: '保存用于计算的温度数值的列名，例如“temp_c”。' },
  'lcz_degree_hours.station_id': { en: 'The name of the column that identifies which station each row of data belongs to.', pt: 'O nome da coluna que identifica a qual estação cada linha de dados pertence.', es: 'El nombre de la columna que identifica a qué estación pertenece cada fila de datos.', zh: '标识每行数据所属站点的列名。' },
  'lcz_degree_hours.base_temp': { en: 'The comfort-threshold temperature in degrees Celsius that separates "needs cooling" from "needs heating" conditions. Defaults to 18.0°C, a commonly used building-comfort baseline; raise or lower it to match a specific standard or climate.', pt: 'A temperatura de limite de conforto, em graus Celsius, que separa as condições que "precisam de resfriamento" das que "precisam de aquecimento". O padrão é 18,0°C, uma referência de conforto de edificações comumente usada; aumente ou diminua para se ajustar a uma norma ou clima específico.', es: 'La temperatura umbral de confort, en grados Celsius, que separa las condiciones que "necesitan refrigeración" de las que "necesitan calefacción". Por defecto 18,0 °C, una base de confort de edificios muy usada; súbala o bájela para ajustarse a una norma o clima concretos.', zh: '以摄氏度表示的舒适阈值温度，用于区分“需要制冷”与“需要供暖”的状态。默认值为 18.0°C，是常用的建筑舒适基准；可根据特定标准或气候上调或下调。' },
  'lcz_degree_hours.degree_type': { en: 'Choose "cooling" to compute Cooling Degree Hours (heat load above the comfort threshold, relevant for air-conditioning demand) or "heating" to compute Heating Degree Hours (cold load below the threshold, relevant for heating demand).', pt: 'Escolha "cooling" para calcular Graus-Hora de Resfriamento (carga de calor acima do limite de conforto, relevante para a demanda de ar-condicionado) ou "heating" para calcular Graus-Hora de Aquecimento (carga de frio abaixo do limite, relevante para a demanda de aquecimento).', es: 'Elija "cooling" para calcular los Grados-Hora de Refrigeración (carga de calor por encima del umbral de confort, relevante para la demanda de aire acondicionado) o "heating" para calcular los Grados-Hora de Calefacción (carga de frío por debajo del umbral, relevante para la demanda de calefacción).', zh: '选择“cooling”计算制冷度时（超过舒适阈值的热负荷，与空调需求相关），或选择“heating”计算供暖度时（低于阈值的冷负荷，与供暖需求相关）。' },
  'lcz_degree_hours.sp_res': { en: 'The spatial resolution, in meters, of the LCZ raster being used. This is informational metadata only and does not change the calculation — you can generally leave it at the default.', pt: 'A resolução espacial, em metros, do raster LCZ usado. É apenas um metadado informativo e não altera o cálculo — geralmente você pode deixá-lo no padrão.', es: 'La resolución espacial, en metros, del ráster LCZ usado. Es solo metadato informativo y no altera el cálculo; por lo general puede dejarlo en su valor por defecto.', zh: '所用 LCZ 栅格的空间分辨率，单位为米。这仅是说明性的元数据，不会改变计算结果——通常可保持默认值。' },
  'lcz_degree_hours.by': { en: 'Splits the results into separate panels by a time grouping, such as "month" or "season", so you can compare patterns across periods. Leave unset for one combined result.', pt: 'Divide os resultados em painéis separados por um agrupamento temporal, como "month" ou "season", para que você possa comparar padrões entre períodos. Deixe em branco para um resultado único combinado.', es: 'Divide los resultados en paneles separados según una agrupación temporal, como "month" o "season", para poder comparar patrones entre periodos. Déjelo sin definir para un resultado combinado único.', zh: '按时间分组（如“month”或“season”）将结果拆分为多个独立面板，便于跨时段比较。留空则生成单一的综合结果。' },
  'lcz_degree_hours.year': { en: 'Restrict the analysis to one or more specific years. Leave blank to use all available years.', pt: 'Restringe a análise a um ou mais anos específicos. Deixe em branco para usar todos os anos disponíveis.', es: 'Restringe el análisis a uno o varios años concretos. Déjelo en blanco para usar todos los años disponibles.', zh: '将分析限定为一个或多个具体年份。留空则使用所有可用年份。' },
  'lcz_degree_hours.month': { en: 'Restrict the analysis to specific months (1-12). Leave blank to use all months.', pt: 'Restringe a análise a meses específicos (1-12). Deixe em branco para usar todos os meses.', es: 'Restringe el análisis a meses concretos (1-12). Déjelo en blanco para usar todos los meses.', zh: '将分析限定为具体月份（1-12）。留空则使用所有月份。' },
  'lcz_degree_hours.day': { en: 'Restrict the analysis to specific days of the month. Leave blank to use all days.', pt: 'Restringe a análise a dias específicos do mês. Deixe em branco para usar todos os dias.', es: 'Restringe el análisis a días concretos del mes. Déjelo en blanco para usar todos los días.', zh: '将分析限定为月份中的具体日期。留空则使用所有日期。' },
  'lcz_degree_hours.hour': { en: 'Restrict the analysis to specific hours of the day (0-23). Leave blank to use all hours.', pt: 'Restringe a análise a horas específicas do dia (0-23). Deixe em branco para usar todas as horas.', es: 'Restringe el análisis a horas concretas del día (0-23). Déjelo en blanco para usar todas las horas.', zh: '将分析限定为一天中的具体小时（0-23）。留空则使用所有小时。' },
  'lcz_degree_hours.start': { en: 'The earliest date to include, for example "2023-06-01". Leave blank to start from the beginning of your data.', pt: 'A data mais antiga a incluir, por exemplo "2023-06-01". Deixe em branco para começar do início dos seus dados.', es: 'La fecha más temprana a incluir, por ejemplo "2023-06-01". Déjela en blanco para empezar desde el inicio de sus datos.', zh: '要包含的最早日期，例如“2023-06-01”。留空则从数据起始处开始。' },
  'lcz_degree_hours.end': { en: 'The latest date to include, for example "2023-08-31". Leave blank to run through the end of your data.', pt: 'A data mais recente a incluir, por exemplo "2023-08-31". Deixe em branco para ir até o fim dos seus dados.', es: 'La fecha más tardía a incluir, por ejemplo "2023-08-31". Déjela en blanco para llegar hasta el final de sus datos.', zh: '要包含的最晚日期，例如“2023-08-31”。留空则运行至数据末尾。' },
  'lcz_dtr.x': { en: 'The LCZ raster map used to determine which LCZ class each weather station falls into, based on its location.', pt: 'O raster LCZ usado para determinar em qual classe LCZ cada estação meteorológica se encontra, com base em sua localização.', es: 'El mapa ráster LCZ usado para determinar en qué clase LCZ cae cada estación meteorológica, según su ubicación.', zh: '根据位置判断每个气象站所属 LCZ 类别的 LCZ 栅格地图。' },
  'lcz_dtr.data_frame': { en: 'Your table of station observations, with columns for date, station ID, the variable being measured, and each station\'s latitude/longitude.', pt: 'Sua tabela de observações de estações, com colunas para data, ID da estação, a variável medida e latitude/longitude de cada estação.', es: 'Su tabla de observaciones de estaciones, con columnas para fecha, identificador de estación, la variable medida y la latitud/longitud de cada estación.', zh: '你的站点观测数据表，包含日期、站点 ID、被测变量以及每个站点的经纬度列。' },
  'lcz_dtr.var': { en: 'The name of the column holding the temperature values to use for the calculation, for example "temp_c".', pt: 'O nome da coluna que contém os valores de temperatura usados no cálculo, por exemplo "temp_c".', es: 'El nombre de la columna que contiene los valores de temperatura a usar en el cálculo, por ejemplo "temp_c".', zh: '保存用于计算的温度数值的列名，例如“temp_c”。' },
  'lcz_dtr.station_id': { en: 'The name of the column that identifies which station each row of data belongs to.', pt: 'O nome da coluna que identifica a qual estação cada linha de dados pertence.', es: 'El nombre de la columna que identifica a qué estación pertenece cada fila de datos.', zh: '标识每行数据所属站点的列名。' },
  'lcz_dtr.sp_res': { en: 'The spatial resolution, in meters, of the LCZ raster being used. This is informational metadata only and does not change the calculation — you can generally leave it at the default.', pt: 'A resolução espacial, em metros, do raster LCZ usado. É apenas um metadado informativo e não altera o cálculo — geralmente você pode deixá-lo no padrão.', es: 'La resolución espacial, en metros, del ráster LCZ usado. Es solo metadato informativo y no altera el cálculo; por lo general puede dejarlo en su valor por defecto.', zh: '所用 LCZ 栅格的空间分辨率，单位为米。这仅是说明性的元数据，不会改变计算结果——通常可保持默认值。' },
  'lcz_dtr.tp_res': { en: 'The time window over which the daily high and low are found. Currently only "day" is supported, meaning each calendar day\'s own high and low temperatures are used.', pt: 'A janela de tempo dentro da qual a máxima e mínima diárias são encontradas. Atualmente só "day" é suportado, significando que a máxima e a mínima de cada dia do calendário são usadas.', es: 'La ventana temporal en la que se buscan el máximo y el mínimo diarios. Actualmente solo se admite "day", es decir, se usan la temperatura máxima y mínima propias de cada día natural.', zh: '用于寻找每日最高和最低温度的时间窗口。目前仅支持“day”，即使用每个日历日各自的最高和最低气温。' },
  'lcz_dtr.by': { en: 'Splits the results into separate panels by a time grouping, such as "season" or "month", so you can compare DTR patterns across periods. Leave unset for one combined result.', pt: 'Divide os resultados em painéis separados por um agrupamento temporal, como "season" ou "month", para que você possa comparar padrões de DTR entre períodos. Deixe em branco para um resultado único combinado.', es: 'Divide los resultados en paneles separados según una agrupación temporal, como "season" o "month", para poder comparar patrones de DTR entre periodos. Déjelo sin definir para un resultado combinado único.', zh: '按时间分组（如“season”或“month”）将结果拆分为多个独立面板，便于跨时段比较 DTR 模式。留空则生成单一的综合结果。' },
  'lcz_dtr.year': { en: 'Restrict the analysis to one or more specific years. Leave blank to use all available years.', pt: 'Restringe a análise a um ou mais anos específicos. Deixe em branco para usar todos os anos disponíveis.', es: 'Restringe el análisis a uno o varios años concretos. Déjelo en blanco para usar todos los años disponibles.', zh: '将分析限定为一个或多个具体年份。留空则使用所有可用年份。' },
  'lcz_dtr.month': { en: 'Restrict the analysis to specific months (1-12). Leave blank to use all months.', pt: 'Restringe a análise a meses específicos (1-12). Deixe em branco para usar todos os meses.', es: 'Restringe el análisis a meses concretos (1-12). Déjelo en blanco para usar todos los meses.', zh: '将分析限定为具体月份（1-12）。留空则使用所有月份。' },
  'lcz_dtr.day': { en: 'Restrict the analysis to specific days of the month. Leave blank to use all days.', pt: 'Restringe a análise a dias específicos do mês. Deixe em branco para usar todos os dias.', es: 'Restringe el análisis a días concretos del mes. Déjelo en blanco para usar todos los días.', zh: '将分析限定为月份中的具体日期。留空则使用所有日期。' },
  'lcz_dtr.hour': { en: 'Restrict the analysis to specific hours of the day (0-23). Leave blank to use all hours.', pt: 'Restringe a análise a horas específicas do dia (0-23). Deixe em branco para usar todas as horas.', es: 'Restringe el análisis a horas concretas del día (0-23). Déjelo en blanco para usar todas las horas.', zh: '将分析限定为一天中的具体小时（0-23）。留空则使用所有小时。' },
  'lcz_dtr.start': { en: 'The earliest date to include, for example "2023-01-01". Leave blank to start from the beginning of your data.', pt: 'A data mais antiga a incluir, por exemplo "2023-01-01". Deixe em branco para começar do início dos seus dados.', es: 'La fecha más temprana a incluir, por ejemplo "2023-01-01". Déjela en blanco para empezar desde el inicio de sus datos.', zh: '要包含的最早日期，例如“2023-01-01”。留空则从数据起始处开始。' },
  'lcz_dtr.end': { en: 'The latest date to include, for example "2023-12-31". Leave blank to run through the end of your data.', pt: 'A data mais recente a incluir, por exemplo "2023-12-31". Deixe em branco para ir até o fim dos seus dados.', es: 'La fecha más tardía a incluir, por ejemplo "2023-12-31". Déjela en blanco para llegar hasta el final de sus datos.', zh: '要包含的最晚日期，例如“2023-12-31”。留空则运行至数据末尾。' },
  'lcz_get_indices.x': { en: 'The satellite image band stack to compute indices from, either the file path saved by lcz_get_planetary_computer or its result object directly.', pt: 'A pilha de bandas de imagem de satélite a partir da qual calcular os índices, seja o caminho de arquivo salvo por lcz_get_planetary_computer ou seu objeto de resultado diretamente.', es: 'La pila de bandas de la imagen satelital a partir de la cual calcular índices, ya sea la ruta del archivo guardado por lcz_get_planetary_computer o su objeto de resultado directamente.', zh: '用于计算指数的卫星影像波段堆栈，可以是 lcz_get_planetary_computer 保存的文件路径，也可以是其直接返回的结果对象。' },
  'lcz_get_indices.indices': { en: 'Which specific indices to compute, for example ["NDVI", "NDBI", "NDWI"]. Leave unset to automatically compute every index that can be derived from the bands you downloaded (vegetation, water, urban, soil, and thermal indices are all supported, depending on data availability).', pt: 'Quais índices específicos calcular, por exemplo ["NDVI", "NDBI", "NDWI"]. Deixe em branco para calcular automaticamente todos os índices possíveis a partir das bandas que você baixou (índices de vegetação, água, área urbana, solo e térmicos são todos suportados, dependendo da disponibilidade dos dados).', es: 'Qué índices concretos calcular, por ejemplo ["NDVI", "NDBI", "NDWI"]. Déjelo sin definir para calcular automáticamente todos los índices que se puedan derivar de las bandas descargadas (se admiten índices de vegetación, agua, área urbana, suelo y térmicos, según la disponibilidad de datos).', zh: '要计算的具体指数，例如 ["NDVI", "NDBI", "NDWI"]。留空则自动计算所下载波段能够推导出的所有指数（根据数据可用情况，支持植被、水体、城市、土壤和热红外等各类指数）。' },
  'lcz_get_indices.isave': { en: 'Turn on to also save the computed index stack as a GeoTIFF file in the LCZ4r_output folder, so you can reuse it without recomputing.', pt: 'Ative para também salvar a pilha de índices calculada como um arquivo GeoTIFF na pasta LCZ4r_output, para que você possa reutilizá-la sem recalcular.', es: 'Actívelo para guardar además la pila de índices calculada como archivo GeoTIFF en la carpeta LCZ4r_output, y así poder reutilizarla sin volver a calcularla.', zh: '开启后还会将计算出的指数堆栈以 GeoTIFF 文件形式保存到 LCZ4r_output 文件夹，便于日后重复使用而无需重新计算。' },
  'lcz_get_indices.verbose': { en: 'Turn off to silence the log messages that list each index as it\'s computed; leave it on if you want visibility into the calculation progress.', pt: 'Desative para silenciar as mensagens de log que listam cada índice conforme é calculado; deixe ativado se quiser visibilidade sobre o progresso do cálculo.', es: 'Desactívelo para silenciar los mensajes de registro que enumeran cada índice a medida que se calcula; déjelo activado si quiere visibilidad sobre el progreso del cálculo.', zh: '关闭此项可屏蔽逐一列出每个已计算指数的日志信息；如果想了解计算进度，可保持开启。' },
  'lcz_get_lst.x': { en: 'The LCZ map file (GeoTIFF) whose geographic footprint defines the area to download temperature data for, such as one produced by lcz_get_map.', pt: 'O arquivo de mapa LCZ (GeoTIFF) cuja pegada geográfica define a área para baixar dados de temperatura, como um produzido por lcz_get_map.', es: 'El archivo de mapa LCZ (GeoTIFF) cuya huella geográfica define el área para la que descargar datos de temperatura, como uno producido por lcz_get_map.', zh: '定义要下载温度数据区域的 LCZ 地图文件（GeoTIFF），例如由 lcz_get_map 生成的地图。' },
  'lcz_get_lst.source': { en: 'Which satellite data source to pull LST from: "goes" (roughly 2km resolution, but only covers the Americas), "sentinel3" (global coverage at roughly 1km resolution), or "both" (uses GOES where available and falls back to Sentinel-3 on days or areas it can\'t cover).', pt: 'De qual fonte de satélite obter os dados de LST: "goes" (resolução de aproximadamente 2 km, mas cobre apenas as Américas), "sentinel3" (cobertura global, com resolução de aproximadamente 1 km), ou "both" (usa GOES onde disponível e recorre ao Sentinel-3 nos dias ou áreas que ele não consegue cobrir).', es: 'De qué fuente satelital obtener la LST: "goes" (unos 2 km de resolución, pero cubre solo las Américas), "sentinel3" (cobertura global a unos 1 km de resolución), o "both" (usa GOES donde esté disponible y recurre a Sentinel-3 en los días o áreas que no pueda cubrir).', zh: '要获取 LST 数据的卫星数据源：“goes”（约 2 公里分辨率，但仅覆盖美洲）、“sentinel3”（全球覆盖，约 1 公里分辨率），或“both”（在可用区域优先使用 GOES，在无法覆盖的日期或区域回退使用 Sentinel-3）。' },
  'lcz_get_lst.start_date': { en: 'The first date to include, written as "YYYY-MM-DD" (e.g. "2023-07-01"). The full range is inclusive of both start and end dates.', pt: 'A primeira data a incluir, escrita como "AAAA-MM-DD" (por exemplo "2023-07-01"). O intervalo completo inclui tanto a data inicial quanto a final.', es: 'La primera fecha a incluir, escrita como "AAAA-MM-DD" (por ejemplo "2023-07-01"). El rango completo incluye tanto la fecha de inicio como la de fin.', zh: '要包含的最早日期，格式为“YYYY-MM-DD”（例如“2023-07-01”）。整个日期范围包含起止日期在内。' },
  'lcz_get_lst.end_date': { en: 'The last date to include, written as "YYYY-MM-DD" (e.g. "2023-07-31").', pt: 'A última data a incluir, escrita como "AAAA-MM-DD" (por exemplo "2023-07-31").', es: 'La última fecha a incluir, escrita como "AAAA-MM-DD" (por ejemplo "2023-07-31").', zh: '要包含的最晚日期，格式为“YYYY-MM-DD”（例如“2023-07-31”）。' },
  'lcz_get_lst.satellite': { en: 'Which specific GOES satellite to pull from when your source includes GOES data, such as "goes16", "goes17", or "goes18". The default, "goes16", covers the Americas and is fine for most users.', pt: 'Qual satélite GOES específico usar quando sua fonte inclui dados GOES, como "goes16", "goes17", ou "goes18". O padrão, "goes16", cobre as Américas e serve bem para a maioria dos usuários.', es: 'Qué satélite GOES concreto usar cuando su fuente incluye datos de GOES, como "goes16", "goes17" o "goes18". El valor por defecto, "goes16", cubre las Américas y es adecuado para la mayoría de los usuarios.', zh: '当数据源包含 GOES 数据时，要使用的具体 GOES 卫星，如“goes16”“goes17”或“goes18”。默认值“goes16”覆盖美洲地区，适用于大多数用户。' },
  'lcz_get_lst.target_hour': { en: 'The local solar hour of day to target when picking each day\'s GOES image, so that every day in the stack represents roughly the same time (avoiding a mix of daytime-hot and nighttime-cool pixels). The default, 13.0 (1 PM local solar time), captures near-peak daytime heating; this setting is ignored for Sentinel-3 data.', pt: 'A hora solar local do dia a ter como alvo ao escolher a imagem GOES de cada dia, para que todo dia da pilha represente aproximadamente o mesmo horário (evitando misturar pixels quentes de dia com frios de noite). O padrão, 13,0 (13h no horário solar local), captura o aquecimento diurno próximo ao pico; esta configuração é ignorada para dados Sentinel-3.', es: 'La hora solar local del día a la que apuntar al elegir la imagen GOES de cada día, de modo que todos los días de la pila representen aproximadamente la misma hora (evitando mezclar píxeles calientes de día con píxeles frescos de noche). El valor por defecto, 13,0 (1 p. m. hora solar local), capta el calentamiento diurno cercano al máximo; este ajuste se ignora para los datos de Sentinel-3.', zh: '选取每日 GOES 影像时所针对的本地太阳时，使堆栈中每一天大致代表相同的时刻（避免白天高温像元和夜间低温像元混杂）。默认值 13.0（本地太阳时下午 1 点）能捕捉接近日间升温峰值的时刻；此设置对 Sentinel-3 数据无效。' },
  'lcz_get_lst.units': { en: 'The temperature units for the output: "C" for Celsius (the default) or "K" for Kelvin. Switching this between calls is free and doesn\'t trigger a new download, since the cached data is always stored in Kelvin.', pt: 'As unidades de temperatura para a saída: "C" para Celsius (padrão) ou "K" para Kelvin. Alternar entre elas é gratuito e não dispara um novo download, já que os dados em cache são sempre armazenados em Kelvin.', es: 'Las unidades de temperatura de la salida: "C" para Celsius (por defecto) o "K" para Kelvin. Cambiar esto entre llamadas es gratuito y no dispara una nueva descarga, ya que los datos en caché siempre se almacenan en Kelvin.', zh: '输出的温度单位：“C”表示摄氏度（默认），“K”表示开尔文。在两次调用之间切换此项是免费的，不会触发新的下载，因为缓存数据始终以开尔文存储。' },
  'lcz_get_lst.isave': { en: 'Turn on to also save a copy of the downloaded stack as lcz_lst_stack.tif in the LCZ4r_output folder.', pt: 'Ative para também salvar uma cópia da pilha baixada como lcz_lst_stack.tif na pasta LCZ4r_output.', es: 'Actívelo para guardar además una copia de la pila descargada como lcz_lst_stack.tif en la carpeta LCZ4r_output.', zh: '开启后还会将下载的堆栈副本以 lcz_lst_stack.tif 的名称保存到 LCZ4r_output 文件夹。' },
  'lcz_get_lst.cache': { en: 'Leave this on (the default) to reuse a previously downloaded stack when you repeat the same request, which saves time and avoids re-downloading identical data; turn it off only if you specifically need a fresh download.', pt: 'Deixe ativado (padrão) para reutilizar uma pilha previamente baixada ao repetir o mesmo pedido, economizando tempo e evitando rebaixar dados idênticos; desative apenas se precisar especificamente de um download novo.', es: 'Déjelo activado (por defecto) para reutilizar una pila descargada previamente cuando repita la misma solicitud, lo que ahorra tiempo y evita volver a descargar los mismos datos; desactívelo solo si necesita específicamente una descarga nueva.', zh: '保持开启（默认）可在重复相同请求时复用此前下载的堆栈，节省时间并避免重复下载相同数据；只有在你确实需要重新下载时才关闭此项。' },
  'lcz_get_lst.cache_dir': { en: 'The folder on your computer used to store downloaded data for reuse. This is an internal/advanced setting; most users can leave it at its default location, a hidden folder in your home directory.', pt: 'A pasta no seu computador usada para armazenar dados baixados para reutilização. É uma configuração interna/avançada; a maioria dos usuários pode deixá-la no local padrão, uma pasta oculta no diretório do usuário.', es: 'La carpeta de su computadora usada para almacenar los datos descargados para reutilizarlos. Es un ajuste interno/avanzado; la mayoría de los usuarios puede dejarlo en su ubicación por defecto, una carpeta oculta en su directorio de usuario.', zh: '用于存储已下载数据以便复用的电脑文件夹。这是一个内部/高级设置；大多数用户可保持默认位置，即用户主目录下的一个隐藏文件夹。' },
  'lcz_get_lst.verbose': { en: 'Turn off to silence the warning messages logged for individual days that had to be skipped, for example due to missing satellite coverage.', pt: 'Desative para silenciar as mensagens de aviso registradas para dias individuais que precisaram ser ignorados, por exemplo por falta de cobertura de satélite.', es: 'Desactívelo para silenciar los mensajes de advertencia registrados para los días individuales que hubo que omitir, por ejemplo por falta de cobertura satelital.', zh: '关闭此项可屏蔽针对个别日期（例如因缺少卫星覆盖而被跳过）记录的警告信息。' },
  'lcz_get_map.city': { en: 'The name of the city or place you want the map for, e.g. "Natal, Brazil" or "Berlin, Germany". Leave this empty if you are instead supplying your own region boundary with the roi parameter.', pt: 'O nome da cidade ou do lugar para o qual você quer o mapa, por exemplo "Natal, Brasil" ou "Berlim, Alemanha". Deixe vazio se você preferir informar seu próprio limite de região com o parâmetro roi.', es: 'El nombre de la ciudad o lugar para el que quiere el mapa, por ejemplo "Natal, Brasil" o "Berlín, Alemania". Déjelo vacío si en cambio va a aportar su propio límite de región con el parámetro roi.', zh: '你想获取地图的城市或地点名称，例如“Natal, Brazil”或“Berlin, Germany”。如果你改用 roi 参数提供自定义区域边界，此项可留空。' },
  'lcz_get_map.roi': { en: 'An optional region-of-interest boundary (a polygon layer you\'ve loaded, such as a district or study-area shapefile) to clip the map to, used instead of typing a city name. Use this when your study area doesn\'t match a single city name or has a custom shape.', pt: 'Um limite de área de interesse opcional (uma camada de polígono que você carregou, como um distrito ou um shapefile de área de estudo) para recortar o mapa, usado no lugar de digitar o nome de uma cidade. Use quando sua área de estudo não corresponder a uma única cidade ou tiver uma forma personalizada.', es: 'Un límite de área de interés opcional (una capa de polígono que haya cargado, como un shapefile de un distrito o de su área de estudio) para recortar el mapa, usado en lugar de escribir el nombre de una ciudad. Úselo cuando su área de estudio no coincida con una sola ciudad o tenga una forma personalizada.', zh: '可选的研究区边界（你已载入的多边形图层，例如区县或研究区 shapefile），用于代替输入城市名称对地图进行裁剪。适用于研究区不对应单一城市名称或具有不规则形状的情况。' },
  'lcz_get_map.isave_map': { en: 'When turned on, saves the downloaded map to a file on your computer in addition to loading it in the app. Turn this on if you want to reuse the map later without re-downloading it.', pt: 'Quando ativado, salva o mapa baixado em um arquivo no seu computador, além de carregá-lo no aplicativo. Ative se quiser reutilizar o mapa depois sem precisar rebaixá-lo.', es: 'Al activarlo, guarda el mapa descargado en un archivo en su computadora además de cargarlo en la aplicación. Actívelo si quiere reutilizar el mapa más tarde sin volver a descargarlo.', zh: '开启后，会将下载的地图在载入应用的同时保存到电脑上的文件。如果你想在之后重复使用该地图而无需重新下载，可开启此项。' },
  'lcz_get_map.cache': { en: 'When turned on (the default), the app remembers maps you\'ve already downloaded so it doesn\'t fetch the same data again next time, making repeat requests much faster.', pt: 'Quando ativado (padrão), o aplicativo lembra dos mapas que você já baixou, para não buscar os mesmos dados de novo, tornando pedidos repetidos muito mais rápidos.', es: 'Cuando está activado (por defecto), la aplicación recuerda los mapas que ya ha descargado, de modo que no vuelve a obtener los mismos datos la próxima vez, haciendo mucho más rápidas las solicitudes repetidas.', zh: '开启时（默认），应用会记住此前已下载过的地图，避免下次再次获取相同数据，使重复请求速度大大加快。' },
  'lcz_get_map.cache_dir': { en: 'The folder on your computer where cached (previously downloaded) maps are stored. This is an internal setting most users can safely leave at its default location.', pt: 'A pasta no seu computador onde mapas em cache (previamente baixados) são armazenados. É uma configuração interna que a maioria dos usuários pode deixar com segurança no local padrão.', es: 'La carpeta de su computadora donde se guardan los mapas en caché (descargados previamente). Es un ajuste interno que la mayoría de los usuarios puede dejar sin problema en su ubicación por defecto.', zh: '存储缓存（此前已下载）地图的电脑文件夹。这是一个内部设置，大多数用户可以放心保持默认位置。' },
  'lcz_get_map.verbose': { en: 'When turned on (the default), the app prints progress messages while downloading so you can see what\'s happening. Turn this off if you\'d prefer a quieter, silent download.', pt: 'Quando ativado (padrão), o aplicativo imprime mensagens de progresso durante o download para você ver o que está acontecendo. Desative se preferir um download mais silencioso.', es: 'Cuando está activado (por defecto), la aplicación imprime mensajes de progreso durante la descarga para que pueda ver lo que ocurre. Desactívelo si prefiere una descarga más silenciosa.', zh: '开启时（默认），应用会在下载过程中打印进度信息，让你了解进展情况。如果想要更安静的静默下载，可关闭此项。' },
  'lcz_get_map_euro.city': { en: 'The name of the European city or place you want the map for, e.g. "Rotterdam, Netherlands". Leave this empty if you are instead supplying your own region boundary with the roi parameter.', pt: 'O nome da cidade ou do lugar europeu para o qual você quer o mapa, por exemplo "Roterdã, Países Baixos". Deixe vazio se você preferir informar seu próprio limite de região com o parâmetro roi.', es: 'El nombre de la ciudad o lugar europeo para el que quiere el mapa, por ejemplo "Róterdam, Países Bajos". Déjelo vacío si en cambio va a aportar su propio límite de región con el parámetro roi.', zh: '你想获取地图的欧洲城市或地点名称，例如“Rotterdam, Netherlands”。如果你改用 roi 参数提供自定义区域边界，此项可留空。' },
  'lcz_get_map_euro.roi': { en: 'An optional region-of-interest boundary (a polygon layer you\'ve loaded) to clip the map to, used instead of typing a city name. Useful when your study area doesn\'t align with a single city.', pt: 'Um limite de área de interesse opcional (uma camada de polígono que você carregou) para recortar o mapa, usado no lugar de digitar o nome de uma cidade. Útil quando sua área de estudo não se alinha a uma única cidade.', es: 'Un límite de área de interés opcional (una capa de polígono que haya cargado) para recortar el mapa, usado en lugar de escribir el nombre de una ciudad. Útil cuando su área de estudio no se alinea con una sola ciudad.', zh: '可选的研究区边界（你已载入的多边形图层），用于代替输入城市名称对地图进行裁剪。适用于研究区与单一城市不对应的情况。' },
  'lcz_get_map_euro.isave_map': { en: 'When turned on, saves the final clipped map to a file on your computer in addition to loading it in the app.', pt: 'Quando ativado, salva o mapa final recortado em um arquivo no seu computador, além de carregá-lo no aplicativo.', es: 'Al activarlo, guarda el mapa final recortado en un archivo en su computadora además de cargarlo en la aplicación.', zh: '开启后，会将最终裁剪出的地图在载入应用的同时保存到电脑上的文件。' },
  'lcz_get_map_euro.isave_euro': { en: 'When turned on, also saves the full, un-clipped European map to a file, which is useful if you plan to look at other areas within Europe later without re-downloading the whole continent.', pt: 'Quando ativado, também salva o mapa europeu completo, não recortado, em um arquivo, o que é útil se você planeja olhar outras áreas dentro da Europa depois sem rebaixar o continente inteiro.', es: 'Al activarlo, guarda además el mapa europeo completo, sin recortar, en un archivo, útil si planea revisar otras áreas de Europa más adelante sin volver a descargar todo el continente.', zh: '开启后，还会将完整、未裁剪的欧洲地图保存到文件，适合日后想查看欧洲其他地区而无需重新下载整块大陆数据的情况。' },
  'lcz_get_map_euro.cache': { en: 'When turned on (the default), the app remembers previously downloaded data so repeat requests are much faster and don\'t re-download the same files.', pt: 'Quando ativado (padrão), o aplicativo lembra dos dados baixados anteriormente, tornando pedidos repetidos muito mais rápidos e evitando rebaixar os mesmos arquivos.', es: 'Cuando está activado (por defecto), la aplicación recuerda los datos descargados previamente, de modo que las solicitudes repetidas son mucho más rápidas y no vuelven a descargar los mismos archivos.', zh: '开启时（默认），应用会记住此前已下载的数据，使重复请求速度大大加快，也不会重复下载相同文件。' },
  'lcz_get_map_euro.cache_dir': { en: 'The folder on your computer where cached (previously downloaded) map data is stored. This is an internal setting most users can safely leave at its default location.', pt: 'A pasta no seu computador onde dados de mapa em cache (previamente baixados) são armazenados. É uma configuração interna que a maioria dos usuários pode deixar com segurança no local padrão.', es: 'La carpeta de su computadora donde se guardan los datos de mapa en caché (descargados previamente). Es un ajuste interno que la mayoría de los usuarios puede dejar sin problema en su ubicación por defecto.', zh: '存储缓存（此前已下载）地图数据的电脑文件夹。这是一个内部设置，大多数用户可以放心保持默认位置。' },
  'lcz_get_map_euro.verbose': { en: 'When turned on (the default), the app prints progress messages while downloading. Turn this off for a quieter, silent download.', pt: 'Quando ativado (padrão), o aplicativo imprime mensagens de progresso durante o download. Desative para um download mais silencioso.', es: 'Cuando está activado (por defecto), la aplicación imprime mensajes de progreso durante la descarga. Desactívelo para una descarga más silenciosa.', zh: '开启时（默认），应用会在下载过程中打印进度信息。如需更安静的静默下载，可关闭此项。' },
  'lcz_get_map_generator.id': { en: 'The identifier of the LCZ Generator job whose map you want to download; you find this ID on the LCZ Generator website page for your submitted job.', pt: 'O identificador do job do LCZ Generator cujo mapa você quer baixar; você encontra esse ID na página do site LCZ Generator referente ao seu job enviado.', es: 'El identificador del trabajo de LCZ Generator cuyo mapa quiere descargar; lo encontrará en la página del sitio LCZ Generator correspondiente a su trabajo enviado.', zh: '你想下载其地图的 LCZ Generator 作业标识符；可在 LCZ Generator 网站上你提交的作业页面上找到该 ID。' },
  'lcz_get_map_generator.band': { en: 'Which data layer to pull from the job\'s output. The default, "lczFilter", is the standard filtered LCZ classification most users want; only change this if you specifically need a different, unfiltered layer from the same job.', pt: 'Qual camada de dados extrair da saída do job. O padrão, "lczFilter", é a classificação LCZ filtrada padrão que a maioria dos usuários deseja; altere apenas se precisar especificamente de uma camada diferente, não filtrada, do mesmo job.', es: 'Qué capa de datos obtener de la salida del trabajo. El valor por defecto, "lczFilter", es la clasificación LCZ filtrada estándar que quiere la mayoría de los usuarios; cámbielo solo si necesita específicamente otra capa sin filtrar del mismo trabajo.', zh: '要从该作业输出中提取的数据图层。默认值“lczFilter”是大多数用户想要的标准过滤后 LCZ 分类；只有当你特别需要同一作业中另一个未过滤的图层时才需要更改此项。' },
  'lcz_get_map_generator.isave_map': { en: 'When turned on, saves the downloaded map to a file on your computer in addition to loading it in the app.', pt: 'Quando ativado, salva o mapa baixado em um arquivo no seu computador, além de carregá-lo no aplicativo.', es: 'Al activarlo, guarda el mapa descargado en un archivo en su computadora además de cargarlo en la aplicación.', zh: '开启后，会将下载的地图在载入应用的同时保存到电脑上的文件。' },
  'lcz_get_map_generator.save_extension': { en: 'The file format to save the map in when isave_map is turned on, such as "tif" (a standard GIS raster format that works well with most mapping software).', pt: 'O formato de arquivo para salvar o mapa quando isave_map está ativado, como "tif" (um formato raster de SIG padrão que funciona bem com a maioria dos softwares de mapeamento).', es: 'El formato de archivo en que guardar el mapa cuando isave_map está activado, como "tif" (un formato ráster SIG estándar que funciona bien con la mayoría del software de mapeo).', zh: 'isave_map 开启时保存地图所用的文件格式，例如“tif”（一种能与大多数制图软件良好兼容的标准 GIS 栅格格式）。' },
  'lcz_get_map_usa.city': { en: 'The name of the US city or place you want the map for, e.g. "Phoenix, Arizona". Leave this empty if you are instead supplying your own region boundary with the roi parameter.', pt: 'O nome da cidade ou do lugar dos EUA para o qual você quer o mapa, por exemplo "Phoenix, Arizona". Deixe vazio se você preferir informar seu próprio limite de região com o parâmetro roi.', es: 'El nombre de la ciudad o lugar de EE. UU. para el que quiere el mapa, por ejemplo "Phoenix, Arizona". Déjelo vacío si en cambio va a aportar su propio límite de región con el parámetro roi.', zh: '你想获取地图的美国城市或地点名称，例如“Phoenix, Arizona”。如果你改用 roi 参数提供自定义区域边界，此项可留空。' },
  'lcz_get_map_usa.roi': { en: 'An optional region-of-interest boundary (a polygon layer you\'ve loaded) to clip the map to, used instead of typing a city name. Useful when your study area doesn\'t align with a single city.', pt: 'Um limite de área de interesse opcional (uma camada de polígono que você carregou) para recortar o mapa, usado no lugar de digitar o nome de uma cidade. Útil quando sua área de estudo não se alinha a uma única cidade.', es: 'Un límite de área de interés opcional (una capa de polígono que haya cargado) para recortar el mapa, usado en lugar de escribir el nombre de una ciudad. Útil cuando su área de estudio no se alinea con una sola ciudad.', zh: '可选的研究区边界（你已载入的多边形图层），用于代替输入城市名称对地图进行裁剪。适用于研究区与单一城市不对应的情况。' },
  'lcz_get_map_usa.isave_map': { en: 'When turned on, saves the final clipped map to a file on your computer in addition to loading it in the app.', pt: 'Quando ativado, salva o mapa final recortado em um arquivo no seu computador, além de carregá-lo no aplicativo.', es: 'Al activarlo, guarda el mapa final recortado en un archivo en su computadora además de cargarlo en la aplicación.', zh: '开启后，会将最终裁剪出的地图在载入应用的同时保存到电脑上的文件。' },
  'lcz_get_map_usa.isave_usa': { en: 'When turned on, also saves the full, un-clipped US map to a file, useful if you plan to study other US locations later without re-downloading the whole country.', pt: 'Quando ativado, também salva o mapa completo dos EUA, não recortado, em um arquivo, útil se você planeja estudar outras localidades dos EUA depois sem rebaixar o país inteiro.', es: 'Al activarlo, guarda además el mapa completo de EE. UU., sin recortar, en un archivo, útil si planea estudiar otras ubicaciones de EE. UU. más adelante sin volver a descargar todo el país.', zh: '开启后，还会将完整、未裁剪的美国地图保存到文件，适合日后想研究美国其他地区而无需重新下载整个国家数据的情况。' },
  'lcz_get_map_usa.cache': { en: 'When turned on (the default), the app remembers previously downloaded data so repeat requests are much faster and don\'t re-download the same files.', pt: 'Quando ativado (padrão), o aplicativo lembra dos dados baixados anteriormente, tornando pedidos repetidos muito mais rápidos e evitando rebaixar os mesmos arquivos.', es: 'Cuando está activado (por defecto), la aplicación recuerda los datos descargados previamente, de modo que las solicitudes repetidas son mucho más rápidas y no vuelven a descargar los mismos archivos.', zh: '开启时（默认），应用会记住此前已下载的数据，使重复请求速度大大加快，也不会重复下载相同文件。' },
  'lcz_get_map_usa.cache_dir': { en: 'The folder on your computer where cached (previously downloaded) map data is stored. This is an internal setting most users can safely leave at its default location.', pt: 'A pasta no seu computador onde dados de mapa em cache (previamente baixados) são armazenados. É uma configuração interna que a maioria dos usuários pode deixar com segurança no local padrão.', es: 'La carpeta de su computadora donde se guardan los datos de mapa en caché (descargados previamente). Es un ajuste interno que la mayoría de los usuarios puede dejar sin problema en su ubicación por defecto.', zh: '存储缓存（此前已下载）地图数据的电脑文件夹。这是一个内部设置，大多数用户可以放心保持默认位置。' },
  'lcz_get_map_usa.verbose': { en: 'When turned on (the default), the app prints progress messages while downloading. Turn this off for a quieter, silent download.', pt: 'Quando ativado (padrão), o aplicativo imprime mensagens de progresso durante o download. Desative para um download mais silencioso.', es: 'Cuando está activado (por defecto), la aplicación imprime mensajes de progreso durante la descarga. Desactívelo para una descarga más silenciosa.', zh: '开启时（默认），应用会在下载过程中打印进度信息。如需更安静的静默下载，可关闭此项。' },
  'lcz_get_parameters.x': { en: 'The LCZ classification map to analyze, given as the path to a GeoTIFF raster file (classes 1-17).', pt: 'O mapa de classificação LCZ a analisar, informado como caminho para um raster GeoTIFF (classes 1 a 17).', es: 'El mapa de clasificación LCZ que se va a analizar, indicado como la ruta a un archivo ráster GeoTIFF (clases 1-17).', zh: '要分析的 LCZ 分类地图，以 GeoTIFF 栅格文件路径的形式提供（类别 1-17）。' },
  'lcz_get_parameters.iselect': { en: 'Limits the output to just the parameters you care about, e.g. only "Building Surface Fraction" and "Sky View Factor" instead of all 34. Leave it unset to get everything.', pt: 'Limita a saída apenas aos parâmetros que interessam, por exemplo somente "Fração de Superfície Construída" e "Fator de Visão do Céu", em vez de todos os 34. Deixe em branco para obter todos.', es: 'Limita la salida solo a los parámetros que le interesan, por ejemplo únicamente "Fracción de Superficie Construida" y "Factor de Visión del Cielo" en lugar de los 34. Déjelo sin definir para obtenerlos todos.', zh: '将输出限定为你关心的参数，例如仅保留“建筑表面比例”和“天空可视因子”，而不是全部 34 项。留空则输出全部参数。' },
  'lcz_get_parameters.istack': { en: 'When left on (the default) and no specific parameters are chosen with iselect, returns all parameters together as one multi-layer raster stack, which is convenient for loading into other GIS tools in one step.', pt: 'Quando ativado (padrão) e nenhum parâmetro específico é escolhido em iselect, retorna todos os parâmetros juntos como uma única pilha raster multicamadas, prática para carregar em outras ferramentas de SIG de uma só vez.', es: 'Cuando está activado (opción por defecto) y no se elige ningún parámetro concreto con iselect, devuelve todos los parámetros juntos como una sola pila ráster multicapa, lo que resulta cómodo para cargarlos de una vez en otras herramientas SIG.', zh: '保持默认开启且未通过 iselect 指定具体参数时，会将所有参数合并为一个多图层栅格堆栈返回，便于一次性导入其他 GIS 工具。' },
  'lcz_get_parameters.ishp': { en: 'Turn this on to get the results as a polygon layer (one shape per LCZ patch with its parameter values attached) instead of a raster, which is useful if you want to view the results as a vector map or export to a shapefile-like format.', pt: 'Ative para obter os resultados como uma camada de polígonos (uma forma por mancha LCZ com os valores de parâmetro associados) em vez de um raster, útil para visualizar os resultados como mapa vetorial ou exportar em formato tipo shapefile.', es: 'Actívelo para obtener los resultados como una capa de polígonos (una forma por parche LCZ con sus valores de parámetros asociados) en lugar de un ráster, útil si quiere ver los resultados como mapa vectorial o exportarlos a un formato tipo shapefile.', zh: '开启后，结果将以多边形图层形式返回（每个 LCZ 图斑对应一个形状并附带其参数值），而不是栅格，适合以矢量地图形式查看或导出为类 shapefile 格式。' },
  'lcz_get_parameters.isave': { en: 'Turn this on to automatically save the output files to the project\'s LCZ4r_output folder instead of only returning them in memory.', pt: 'Ative para salvar automaticamente os arquivos de saída na pasta LCZ4r_output do projeto, em vez de mantê-los apenas em memória.', es: 'Actívelo para guardar automáticamente los archivos de salida en la carpeta LCZ4r_output del proyecto en lugar de devolverlos solo en memoria.', zh: '开启后会自动将输出文件保存到项目的 LCZ4r_output 文件夹，而不仅仅在内存中返回结果。' },
  'lcz_get_parameters.use_duckdb': { en: 'An internal performance option that speeds up merging polygons of the same class using the DuckDB Spatial engine. Leave this on (the default); most users never need to touch it.', pt: 'Uma opção interna de desempenho que acelera a fusão de polígonos da mesma classe usando o mecanismo espacial do DuckDB. Deixe ativado (padrão); a maioria dos usuários nunca precisa mexer aqui.', es: 'Una opción de rendimiento interna que acelera la fusión de polígonos de la misma clase mediante el motor espacial de DuckDB. Déjela activada (opción por defecto); la mayoría de los usuarios nunca necesita tocarla.', zh: '一项内部性能选项，使用 DuckDB 空间引擎加速同类别多边形的合并。保持默认开启即可，大多数用户无需调整。' },
  'lcz_get_parameters.use_geoarrow': { en: 'An internal performance option that produces the polygon output in the efficient GeoArrow format. Leave it on the default unless you have a specific reason to disable it.', pt: 'Uma opção interna de desempenho que produz a saída de polígonos no formato eficiente GeoArrow. Deixe no padrão a menos que tenha um motivo específico para desativá-la.', es: 'Una opción de rendimiento interna que produce la salida de polígonos en el formato eficiente GeoArrow. Déjela en su valor por defecto salvo que tenga un motivo concreto para desactivarla.', zh: '一项内部性能选项，以高效的 GeoArrow 格式生成多边形输出。除非有特殊原因，否则保持默认开启。' },
  'lcz_get_parameters.use_pyogrio': { en: 'An internal performance option that uses the faster Pyogrio library for reading and writing files. Leave it on the default; it only affects processing speed, not the results.', pt: 'Uma opção interna de desempenho que usa a biblioteca Pyogrio, mais rápida, para ler e gravar arquivos. Deixe no padrão; afeta apenas a velocidade do processamento, não os resultados.', es: 'Una opción de rendimiento interna que usa la biblioteca Pyogrio, más rápida, para leer y escribir archivos. Déjela en su valor por defecto; solo afecta a la velocidad de procesamiento, no a los resultados.', zh: '一项内部性能选项，使用速度更快的 Pyogrio 库进行文件读写。保持默认开启即可，它只影响处理速度，不影响结果。' },
  'lcz_get_planetary_computer.x': { en: 'The LCZ map file (GeoTIFF) whose geographic footprint defines the area to download data for.', pt: 'O arquivo de mapa LCZ (GeoTIFF) cuja pegada geográfica define a área para a qual baixar dados.', es: 'El archivo de mapa LCZ (GeoTIFF) cuya huella geográfica define el área para la que descargar datos.', zh: '定义要下载数据区域的 LCZ 地图文件（GeoTIFF）。' },
  'lcz_get_planetary_computer.collection': { en: 'Which data product to download, given as a short name (like "sentinel-2-l2a" for Sentinel-2 imagery) or a raw Planetary Computer collection identifier if you need one that isn\'t pre-configured.', pt: 'Qual produto de dados baixar, informado como um nome curto (como "sentinel-2-l2a" para imagens Sentinel-2) ou um identificador bruto de coleção do Planetary Computer, caso você precise de uma que não esteja pré-configurada.', es: 'Qué producto de datos descargar, indicado como un nombre corto (como "sentinel-2-l2a" para imágenes Sentinel-2) o un identificador de colección de Planetary Computer sin procesar si necesita una que no esté preconfigurada.', zh: '要下载的数据产品，可以是简短名称（如“sentinel-2-l2a”表示 Sentinel-2 影像），也可以是原始的 Planetary Computer 数据集标识符（如果你需要的数据集未预先配置）。' },
  'lcz_get_planetary_computer.assets': { en: 'Which specific bands or layers to extract from the collection, such as ["B04", "B08"] for red and near-infrared bands. Leave unset to use the sensible default set of bands for common collections; required if you specify a collection that isn\'t one of the built-in shortcuts.', pt: 'Quais bandas ou camadas específicas extrair da coleção, como ["B04", "B08"] para as bandas do vermelho e do infravermelho próximo. Deixe em branco para usar o conjunto padrão de bandas sensato para coleções comuns; obrigatório se você especificar uma coleção que não seja um dos atalhos embutidos.', es: 'Qué bandas o capas concretas extraer de la colección, como ["B04", "B08"] para las bandas roja e infrarroja cercana. Déjelo sin definir para usar el conjunto de bandas por defecto razonable para las colecciones más comunes; obligatorio si especifica una colección que no sea uno de los atajos integrados.', zh: '要从该数据集中提取的具体波段或图层，例如 ["B04", "B08"] 表示红光和近红外波段。留空则对常见数据集使用合理的默认波段组合；如果你指定的数据集不是内置的快捷方式之一，则此项为必填。' },
  'lcz_get_planetary_computer.start_date': { en: 'The earliest date to search for imagery, written as "YYYY-MM-DD" (e.g. "2023-01-01"). Needed together with end_date for imagery that changes over time (ignored for unchanging data like land-cover or elevation maps); if you leave both unset, the most recent available imagery is used.', pt: 'A data mais antiga para buscar imagens, escrita como "AAAA-MM-DD" (por exemplo "2023-01-01"). Necessário junto com end_date para imagens que mudam ao longo do tempo (ignorado para dados invariáveis, como mapas de cobertura do solo ou elevação); se ambos forem deixados em branco, a imagem disponível mais recente é usada.', es: 'La fecha más temprana para buscar imágenes, escrita como "AAAA-MM-DD" (por ejemplo "2023-01-01"). Se necesita junto con end_date para imágenes que cambian con el tiempo (se ignora para datos invariables como mapas de cobertura del suelo o de elevación); si deja ambas sin definir, se usan las imágenes disponibles más recientes.', zh: '开始搜索影像的最早日期，格式为“YYYY-MM-DD”（例如“2023-01-01”）。对于随时间变化的影像（对不随时间变化的数据，如地表覆盖或高程地图，此项会被忽略），需要与 end_date 一起使用；如果两者都留空，会使用最新的可用影像。' },
  'lcz_get_planetary_computer.end_date': { en: 'The latest date to search for imagery, written as "YYYY-MM-DD" (e.g. "2023-03-31"). Needed together with start_date for time-varying imagery.', pt: 'A data mais recente para buscar imagens, escrita como "AAAA-MM-DD" (por exemplo "2023-03-31"). Necessário junto com start_date para imagens que variam no tempo.', es: 'La fecha más tardía para buscar imágenes, escrita como "AAAA-MM-DD" (por ejemplo "2023-03-31"). Se necesita junto con start_date para imágenes variables en el tiempo.', zh: '搜索影像的最晚日期，格式为“YYYY-MM-DD”（例如“2023-03-31”）。对于随时间变化的影像，需要与 start_date 一起使用。' },
  'lcz_get_planetary_computer.max_cloud_cover': { en: 'The maximum percentage of cloud cover allowed in an image before it\'s excluded, for optical imagery like Sentinel-2 or Landsat that reports cloud cover. The default of 30 means images with more than 30% clouds are skipped; lower it (e.g. to 10) for a cleaner but possibly sparser stack. Ignored for data types that don\'t report cloud cover.', pt: 'A porcentagem máxima de cobertura de nuvens permitida em uma imagem antes de ela ser excluída, para imagens ópticas como Sentinel-2 ou Landsat que informam cobertura de nuvens. O padrão de 30 significa que imagens com mais de 30% de nuvens são ignoradas; reduza (por exemplo, para 10) para uma pilha mais limpa, porém possivelmente mais esparsa. Ignorado para tipos de dados que não informam cobertura de nuvens.', es: 'El porcentaje máximo de cobertura de nubes permitido en una imagen antes de excluirla, para imágenes ópticas como Sentinel-2 o Landsat que reportan cobertura de nubes. El valor por defecto de 30 significa que se omiten las imágenes con más de un 30% de nubes; redúzcalo (por ejemplo a 10) para una pila más limpia pero posiblemente más escasa. Se ignora para tipos de datos que no reportan cobertura de nubes.', zh: '影像被排除前允许的最大云量百分比，适用于会报告云量的光学影像，如 Sentinel-2 或 Landsat。默认值 30 表示云量超过 30% 的影像会被跳过；调低（例如 10）可获得更干净但可能更稀疏的影像堆栈。对不报告云量的数据类型此项会被忽略。' },
  'lcz_get_planetary_computer.cloud_cover_property': { en: 'The exact technical field name used to filter by cloud cover. This is an advanced override you\'ll rarely need to touch, since the built-in collection shortcuts already set the correct value.', pt: 'O nome técnico exato do campo usado para filtrar por cobertura de nuvens. É uma opção avançada que você raramente precisará tocar, já que os atalhos de coleção embutidos já definem o valor correto.', es: 'El nombre técnico exacto del campo usado para filtrar por cobertura de nubes. Es una anulación avanzada que rara vez necesitará tocar, ya que los atajos de colección integrados ya fijan el valor correcto.', zh: '用于按云量筛选的确切技术字段名称。这是一个高级覆盖选项，你几乎不需要调整，因为内置的数据集快捷方式已经设置了正确的值。' },
  'lcz_get_planetary_computer.max_items': { en: 'The maximum number of separate satellite scenes that can be combined to fill your area of interest, picked by best-cloud/most-recent first and merged to cover any gaps at tile edges. The default of 10 is enough for most cases; a small study area rarely needs more.', pt: 'O número máximo de cenas de satélite separadas que podem ser combinadas para preencher sua área de interesse, escolhidas primeiro pela menor cobertura de nuvens/mais recentes e mescladas para cobrir eventuais lacunas nas bordas dos blocos. O padrão de 10 é suficiente para a maioria dos casos; uma área de estudo pequena raramente precisa de mais.', es: 'El número máximo de escenas satelitales distintas que se pueden combinar para cubrir su área de interés, elegidas primero por menor nubosidad/más recientes y fusionadas para cubrir cualquier hueco en los bordes de las teselas. El valor por defecto de 10 basta para la mayoría de los casos; un área de estudio pequeña rara vez necesita más.', zh: '为覆盖你的研究区可以合并的最多独立卫星场景数量，按云量最优/最新优先选取并合并以填补图幅边缘的空隙。默认值 10 对大多数情况已足够；小型研究区很少需要更多。' },
  'lcz_get_planetary_computer.resampling': { en: 'The method used to resample pixels when reprojecting the data, such as "bilinear" for smooth continuous data like temperature or reflectance, or "nearest" to preserve exact category codes in categorical data like land-cover maps. Leave unset to use the recommended default for your chosen collection.', pt: 'O método usado para reamostrar pixels ao reprojetar os dados, como "bilinear" para dados contínuos suaves, como temperatura ou refletância, ou "nearest" para preservar códigos de categoria exatos em dados categóricos, como mapas de cobertura do solo. Deixe em branco para usar o padrão recomendado para a coleção escolhida.', es: 'El método usado para remuestrear los píxeles al reproyectar los datos, como "bilinear" para datos continuos suaves como temperatura o reflectancia, o "nearest" para conservar los códigos de categoría exactos en datos categóricos como los mapas de cobertura del suelo. Déjelo sin definir para usar el valor recomendado por defecto de la colección elegida.', zh: '重投影数据时用于重采样像元的方法，例如“bilinear”适用于气温或反射率等平滑连续数据，“nearest”适用于保留地表覆盖地图等类别数据的精确类别编码。留空则使用所选数据集推荐的默认方法。' },
  'lcz_get_planetary_computer.isave': { en: 'Turn on to also save the downloaded stack as a GeoTIFF file (named lcz_pc_<collection>_stack.tif) in the LCZ4r_output folder.', pt: 'Ative para também salvar a pilha baixada como um arquivo GeoTIFF (chamado lcz_pc_<coleção>_stack.tif) na pasta LCZ4r_output.', es: 'Actívelo para guardar además la pila descargada como archivo GeoTIFF (llamado lcz_pc_<colección>_stack.tif) en la carpeta LCZ4r_output.', zh: '开启后还会将下载的堆栈以 GeoTIFF 文件形式（命名为 lcz_pc_<collection>_stack.tif）保存到 LCZ4r_output 文件夹。' },
  'lcz_get_planetary_computer.cache': { en: 'Leave this on (the default) to reuse a previously downloaded stack for an identical request, saving time on repeated calls; turn it off only if you need to force a fresh download.', pt: 'Deixe ativado (padrão) para reutilizar uma pilha previamente baixada para um pedido idêntico, economizando tempo em chamadas repetidas; desative apenas se precisar forçar um novo download.', es: 'Déjelo activado (por defecto) para reutilizar una pila descargada previamente para una solicitud idéntica, ahorrando tiempo en llamadas repetidas; desactívelo solo si necesita forzar una descarga nueva.', zh: '保持开启（默认）可在请求完全相同时复用此前下载的堆栈，节省重复调用的时间；只有在需要强制重新下载时才关闭此项。' },
  'lcz_get_planetary_computer.cache_dir': { en: 'The folder on your computer used to store downloaded data for reuse. This is an internal/advanced setting; most users can leave it at its default location, a hidden folder in your home directory.', pt: 'A pasta no seu computador usada para armazenar dados baixados para reutilização. É uma configuração interna/avançada; a maioria dos usuários pode deixá-la no local padrão, uma pasta oculta no diretório do usuário.', es: 'La carpeta de su computadora usada para almacenar los datos descargados para reutilizarlos. Es un ajuste interno/avanzado; la mayoría de los usuarios puede dejarlo en su ubicación por defecto, una carpeta oculta en su directorio de usuario.', zh: '用于存储已下载数据以便复用的电脑文件夹。这是一个内部/高级设置；大多数用户可保持默认位置，即用户主目录下的一个隐藏文件夹。' },
  'lcz_get_planetary_computer.verbose': { en: 'Turn off to silence progress messages and warnings about partial coverage of your area of interest.', pt: 'Desative para silenciar mensagens de progresso e avisos sobre cobertura parcial da sua área de interesse.', es: 'Desactívelo para silenciar los mensajes de progreso y las advertencias sobre cobertura parcial de su área de interés.', zh: '关闭此项可屏蔽进度信息以及关于研究区部分覆盖的警告。' },
  'lcz_get_ucp.lcz_map': { en: 'The LCZ classification raster that defines the study area\'s boundary and grid; all downloaded parameters are processed to match its extent and resolution.', pt: 'O raster de classificação LCZ que define o limite e a grade da área de estudo; todos os parâmetros baixados são processados para corresponder à sua extensão e resolução.', es: 'El ráster de clasificación LCZ que define el límite y la cuadrícula del área de estudio; todos los parámetros descargados se procesan para ajustarse a su extensión y resolución.', zh: '定义研究区边界和网格的 LCZ 分类栅格；所有下载的参数都会被处理为与其范围和分辨率一致。' },
  'lcz_get_ucp.stations': { en: 'An optional table of station locations (with coordinates) at which to read off parameter values, e.g. your weather station network. If left unset, no point extraction happens and the function instead saves a full raster stack of all parameters, cropped to the map\'s extent, as lcz_ucp_stack.tif.', pt: 'Uma tabela opcional de localizações de estações (com coordenadas) nas quais ler os valores dos parâmetros, por exemplo sua rede de estações meteorológicas. Se não for informada, não há extração pontual e a função salva em vez disso uma pilha raster completa de todos os parâmetros, recortada à extensão do mapa, como lcz_ucp_stack.tif.', es: 'Una tabla opcional con las ubicaciones de las estaciones (con sus coordenadas) en las que leer los valores de los parámetros, por ejemplo la red de estaciones meteorológicas. Si se deja sin definir, no se extrae ningún punto y la función guarda en su lugar una pila ráster completa de todos los parámetros, recortada a la extensión del mapa, como lcz_ucp_stack.tif.', zh: '可选的站点位置表（含坐标），函数会在这些点位读取参数值，例如你的气象站网络。若留空，则不进行点位提取，函数会改为保存一个裁剪到地图范围的完整参数栅格堆栈，命名为 lcz_ucp_stack.tif。' },
  'lcz_get_ucp.cache_dir': { en: 'The folder used to store downloaded data between runs so it doesn\'t have to be re-downloaded every time. This is an internal setting; the default folder name ("lcz4r_cache") works fine for almost everyone.', pt: 'A pasta usada para armazenar os dados baixados entre execuções, para que não precisem ser rebaixados a cada vez. É uma configuração interna; o nome de pasta padrão ("lcz4r_cache") funciona bem para quase todos.', es: 'La carpeta usada para almacenar los datos descargados entre ejecuciones, de modo que no haya que volver a descargarlos cada vez. Es un ajuste interno; el nombre de carpeta por defecto ("lcz4r_cache") sirve para casi todos los casos.', zh: '用于在多次运行之间存储已下载数据的文件夹，避免每次都重新下载。这是一个内部设置，默认文件夹名（“lcz4r_cache”）对绝大多数用户都适用。' },
  'lcz_get_ucp.n_workers': { en: 'How many parallel processes to use for speeding up the download and processing. Leave this unset to automatically use one fewer than the number of CPU cores on your computer.', pt: 'Quantos processos paralelos usar para acelerar o download e o processamento. Deixe sem definir para usar automaticamente um a menos que o número de núcleos de CPU do computador.', es: 'Cuántos procesos paralelos usar para acelerar la descarga y el procesamiento. Déjelo sin definir para usar automáticamente un núcleo menos que el total disponible en su computadora.', zh: '用于加速下载和处理的并行进程数。留空则自动使用比电脑 CPU 核心数少一个的数值。' },
  'lcz_get_ucp.verbose': { en: 'When on (the default), progress messages are printed while the function runs, which is helpful for tracking long downloads. Turn it off if you want a quieter run.', pt: 'Quando ativado (padrão), mensagens de progresso são exibidas durante a execução, o que ajuda a acompanhar downloads longos. Desative para uma execução mais silenciosa.', es: 'Cuando está activado (opción por defecto), se imprimen mensajes de progreso mientras se ejecuta la función, útil para seguir descargas largas. Desactívelo si prefiere una ejecución más silenciosa.', zh: '开启时（默认），运行过程中会打印进度信息，便于跟踪长时间下载。若想要更安静的运行过程可关闭。' },
  'lcz_get_ucp.variables': { en: 'Restricts processing to specific parameter variables instead of the full set, e.g. only vegetation-related ones. Leave unset to process everything.', pt: 'Restringe o processamento a variáveis de parâmetro específicas em vez do conjunto completo, por exemplo apenas as relacionadas à vegetação. Deixe em branco para processar tudo.', es: 'Restringe el procesamiento a variables de parámetros concretas en lugar del conjunto completo, por ejemplo solo las relacionadas con vegetación. Déjelo sin definir para procesarlo todo.', zh: '将处理限定为特定的参数变量，而不是全部，例如只处理与植被相关的变量。留空则处理全部。' },
  'lcz_get_ucp.ghsl_tiles': { en: 'Specific map tile identifiers to use from the GHSL (Global Human Settlement Layer) dataset. Leave unset and the correct tiles for your study area are detected automatically.', pt: 'Identificadores de blocos (tiles) específicos a usar do conjunto de dados GHSL (Global Human Settlement Layer). Deixe em branco e os blocos corretos para sua área de estudo são detectados automaticamente.', es: 'Identificadores de teselas concretas a usar del conjunto de datos GHSL (Global Human Settlement Layer). Déjelo sin definir y las teselas correctas para su área de estudio se detectan automáticamente.', zh: '要使用的 GHSL（全球人类聚居层）数据集的具体图幅编号。留空会自动检测适用于你研究区的正确图幅。' },
  'lcz_get_ucp.process_ghsl': { en: 'Whether to include Global Human Settlement Layer data, such as building height and population, in the output. Leave on unless you specifically want to skip this dataset.', pt: 'Se deve incluir dados do Global Human Settlement Layer, como altura das edificações e população, na saída. Deixe ativado a menos que você queira especificamente pular esse conjunto de dados.', es: 'Si se incluyen o no en la salida los datos del Global Human Settlement Layer, como la altura de los edificios y la población. Déjelo activado salvo que quiera omitir específicamente este conjunto de datos.', zh: '是否在输出中包含全球人类聚居层数据，如建筑高度和人口。除非特意想跳过该数据集，否则保持开启。' },
  'lcz_get_ucp.process_wumpod': { en: 'Whether to include WUDAPT urban morphology and population/occupancy density (WUMPOD) data in the output. Leave on unless you specifically want to skip this dataset.', pt: 'Se deve incluir dados de morfologia urbana e densidade populacional/ocupacional WUDAPT (WUMPOD) na saída. Deixe ativado a menos que queira pular esse conjunto de dados.', es: 'Si se incluyen o no en la salida los datos WUDAPT de morfología urbana y densidad de población/ocupación (WUMPOD). Déjelo activado salvo que quiera omitir específicamente este conjunto de datos.', zh: '是否在输出中包含 WUDAPT 城市形态与人口/占用密度（WUMPOD）数据。除非特意想跳过该数据集，否则保持开启。' },
  'lcz_get_ucp.process_vegetation': { en: 'Whether to include vegetation-cover data in the output. Leave on unless you specifically want to skip this dataset.', pt: 'Se deve incluir dados de cobertura vegetal na saída. Deixe ativado a menos que queira pular esse conjunto de dados.', es: 'Si se incluyen o no en la salida los datos de cobertura vegetal. Déjelo activado salvo que quiera omitir específicamente este conjunto de datos.', zh: '是否在输出中包含植被覆盖数据。除非特意想跳过该数据集，否则保持开启。' },
  'lcz_get_ucp.process_directional': { en: 'Whether to compute direction-dependent parameters (such as street orientation or wind-exposure related metrics). Leave on unless you specifically want to skip these.', pt: 'Se deve calcular parâmetros dependentes de direção (como orientação das ruas ou métricas relacionadas à exposição ao vento). Deixe ativado a menos que queira pular esses cálculos.', es: 'Si se calculan o no parámetros que dependen de la dirección (como la orientación de las calles o métricas relacionadas con la exposición al viento). Déjelo activado salvo que quiera omitirlos.', zh: '是否计算方向相关的参数（如街道朝向或与风暴露相关的指标）。除非特意想跳过，否则保持开启。' },
  'lcz_get_ucp.use_threads': { en: 'An internal performance option controlling whether parallel work runs as lightweight threads (the default) or separate processes. Most users can leave this on the default.', pt: 'Uma opção interna de desempenho que controla se o trabalho paralelo roda como threads leves (padrão) ou processos separados. A maioria dos usuários pode deixar no padrão.', es: 'Una opción de rendimiento interna que controla si el trabajo paralelo se ejecuta como hilos ligeros (opción por defecto) o como procesos independientes. La mayoría de los usuarios puede dejarla en su valor por defecto.', zh: '一项内部性能选项，控制并行任务以轻量级线程（默认）还是独立进程运行。大多数用户可保持默认设置。' },
  'lcz_get_ucp.fail_fast': { en: 'When off (the default), the function keeps going and processes what it can even if one dataset fails, reporting errors at the end. Turn this on if you\'d rather the whole run stop immediately at the first error.', pt: 'Quando desativado (padrão), a função continua e processa o que conseguir mesmo que um conjunto de dados falhe, reportando os erros no final. Ative se preferir que toda a execução pare imediatamente no primeiro erro.', es: 'Cuando está desactivada (opción por defecto), la función continúa y procesa lo que puede aunque un conjunto de datos falle, e informa de los errores al final. Actívela si prefiere que toda la ejecución se detenga de inmediato ante el primer error.', zh: '关闭时（默认），即使某个数据集处理失败，函数也会继续处理其余部分，并在最后统一报告错误。若你希望在第一个错误发生时立即停止整个运行，可开启此项。' },
  'lcz_grid_chirps.x': { en: 'The LCZ map file (a GeoTIFF, typically produced by the map-download function) that defines the area to fetch rainfall for. The rainfall data is cropped to match this map\'s footprint exactly.', pt: 'O arquivo de mapa LCZ (um GeoTIFF, tipicamente produzido pela função de download de mapa) que define a área para a qual buscar a chuva. Os dados de chuva são recortados para corresponder exatamente à pegada desse mapa.', es: 'El archivo de mapa LCZ (un GeoTIFF, típicamente producido por la función de descarga de mapas) que define el área para la que obtener la lluvia. Los datos de lluvia se recortan exactamente a la huella de este mapa.', zh: '定义要获取降水数据区域的 LCZ 地图文件（GeoTIFF，通常由地图下载功能生成）。降水数据会被精确裁剪至此地图的范围。' },
  'lcz_grid_chirps.resolution': { en: 'How the rainfall is summarized over time: "monthly" gives total mm per month (the default), "daily" gives mm per day, and "annual" gives total mm per year. Pick "daily" only if you need fine time detail, since it produces far more data.', pt: 'Como a chuva é resumida ao longo do tempo: "monthly" dá total em mm por mês (padrão), "daily" dá mm por dia, e "annual" dá total em mm por ano. Escolha "daily" apenas se precisar de detalhe fino de tempo, já que produz muito mais dados.', es: 'Cómo se resume la lluvia en el tiempo: "monthly" da el total en mm por mes (valor por defecto), "daily" da mm por día y "annual" da el total en mm por año. Elija "daily" solo si necesita mucho detalle temporal, ya que produce muchos más datos.', zh: '如何在时间上汇总降水量：“monthly”给出每月总毫米数（默认），“daily”给出每日毫米数，“annual”给出每年总毫米数。仅在需要精细时间细节时选择“daily”，因为它会生成远多得多的数据。' },
  'lcz_grid_chirps.years': { en: 'Which calendar years to download, e.g. [2020, 2021, 2022]. Data is available from 1981 to the present (or through 2024 for annual totals); if you leave this blank, the last two complete years are used automatically.', pt: 'Quais anos do calendário baixar, por exemplo [2020, 2021, 2022]. Dados disponíveis de 1981 até o presente (ou até 2024 para totais anuais); se deixado em branco, os dois últimos anos completos são usados automaticamente.', es: 'Qué años del calendario descargar, por ejemplo [2020, 2021, 2022]. Los datos están disponibles desde 1981 hasta el presente (o hasta 2024 para totales anuales); si lo deja en blanco, se usan automáticamente los últimos dos años completos.', zh: '要下载的日历年份，例如 [2020, 2021, 2022]。数据覆盖 1981 年至今（年度总量数据截至 2024 年）；如果留空，会自动使用最近两个完整年份。' },
  'lcz_grid_chirps.months': { en: 'Which months (1 = January through 12 = December) to include, e.g. [6, 7, 8] for a summer season. Ignored when resolution is "annual"; leave blank to get all 12 months.', pt: 'Quais meses (1 = janeiro até 12 = dezembro) incluir, por exemplo [6, 7, 8] para uma estação de verão. Ignorado quando resolution é "annual"; deixe em branco para obter os 12 meses.', es: 'Qué meses (1 = enero a 12 = diciembre) incluir, por ejemplo [6, 7, 8] para una estación de verano. Se ignora cuando resolution es "annual"; déjelo en blanco para obtener los 12 meses.', zh: '要包含的月份（1 = 一月，12 = 十二月），例如 [6, 7, 8] 表示夏季。resolution 为“annual”时此项无效；留空则包含全部 12 个月。' },
  'lcz_grid_chirps.resampling': { en: 'How rainfall values are recalculated onto your LCZ map\'s grid cells. "average" (the default) works well for rainfall since it smooths values sensibly; "bilinear" also smooths but differently, while "nearest" just copies the closest source value without blending.', pt: 'Como os valores de chuva são recalculados sobre as células de grade do seu mapa LCZ. "average" (padrão) funciona bem para chuva, pois suaviza os valores de forma sensata; "bilinear" também suaviza, mas de outra forma, enquanto "nearest" simplesmente copia o valor de origem mais próximo, sem mistura.', es: 'Cómo se recalculan los valores de lluvia sobre las celdas de la cuadrícula de su mapa LCZ. "average" (por defecto) funciona bien para la lluvia porque suaviza los valores de forma razonable; "bilinear" también suaviza pero de otra manera, mientras que "nearest" simplemente copia el valor de origen más cercano sin mezclar.', zh: '如何将降水值重新计算到 LCZ 地图的网格单元上。“average”（默认）对降水而言效果很好，能合理地平滑数值；“bilinear”也会平滑但方式不同，而“nearest”只是直接复制最近的源数据值，不做混合。' },
  'lcz_grid_chirps.isave': { en: 'When turned on, also saves a copy of the downloaded rainfall data into your project\'s LCZ4r_output folder so you can find it again later without re-running the download.', pt: 'Quando ativado, também salva uma cópia dos dados de chuva baixados na pasta LCZ4r_output do seu projeto, para que você possa encontrá-los novamente sem repetir o download.', es: 'Al activarlo, guarda además una copia de los datos de lluvia descargados en la carpeta LCZ4r_output de su proyecto, para poder encontrarlos más tarde sin volver a descargarlos.', zh: '开启后还会将下载的降水数据副本保存到项目的 LCZ4r_output 文件夹，方便之后无需重新下载即可找到。' },
  'lcz_grid_chirps.cache': { en: 'When on (the default), reuses rainfall data you already downloaded for the same years, months, resolution, and map area, so repeat runs are much faster and don\'t re-download the same files.', pt: 'Quando ativado (padrão), reutiliza dados de chuva já baixados para os mesmos anos, meses, resolução e área do mapa, tornando execuções repetidas muito mais rápidas e evitando rebaixar os mesmos arquivos.', es: 'Cuando está activado (por defecto), reutiliza los datos de lluvia ya descargados para los mismos años, meses, resolución y área de mapa, de modo que las ejecuciones repetidas sean mucho más rápidas y no vuelvan a descargar los mismos archivos.', zh: '开启时（默认），会复用此前针对相同年份、月份、分辨率和地图区域已下载的降水数据，使重复运行速度大大加快，也不会重复下载相同文件。' },
  'lcz_grid_chirps.cache_dir': { en: 'The folder on your computer where downloaded rainfall files are stored for reuse. Most users can leave this at its default location and never need to change it.', pt: 'A pasta no seu computador onde os arquivos de chuva baixados são armazenados para reutilização. A maioria dos usuários pode deixar no local padrão e nunca precisa alterá-lo.', es: 'La carpeta de su computadora donde se guardan los archivos de lluvia descargados para reutilizarlos. La mayoría de los usuarios puede dejarla en su ubicación por defecto y nunca necesita cambiarla.', zh: '存储已下载降水文件以便复用的电脑文件夹。大多数用户可保持默认位置，无需更改。' },
  'lcz_grid_chirps.verbose': { en: 'When on (the default), prints progress messages while the data downloads, so you can see that the process is working rather than staring at a silent screen.', pt: 'Quando ativado (padrão), imprime mensagens de progresso enquanto os dados são baixados, para que você veja que o processo está funcionando em vez de olhar para uma tela silenciosa.', es: 'Cuando está activado (por defecto), imprime mensajes de progreso mientras se descargan los datos, para que pueda ver que el proceso está funcionando en lugar de mirar una pantalla silenciosa.', zh: '开启时（默认），数据下载过程中会打印进度信息，让你能看到进程正在运行，而不是面对一个静默无反应的屏幕。' },
  'lcz_grid_era5.x': { en: 'The LCZ map file (a GeoTIFF) whose area you want climate data for. Everything downloaded is cropped to this map\'s footprint.', pt: 'O arquivo de mapa LCZ (um GeoTIFF) cuja área você quer dados climáticos. Tudo que é baixado é recortado à pegada desse mapa.', es: 'El archivo de mapa LCZ (un GeoTIFF) cuya área desea usar para obtener datos climáticos. Todo lo descargado se recorta a la huella de este mapa.', zh: '你想获取气候数据的 LCZ 地图文件（GeoTIFF）所对应的区域。所有下载的数据都会被裁剪至此地图的范围。' },
  'lcz_grid_era5.years': { en: 'The years to import, e.g. [2015, 2016, 2017]. Data is available from 1950 through 2025; this parameter is required, so you must specify at least one year.', pt: 'Os anos a importar, por exemplo [2015, 2016, 2017]. Dados disponíveis de 1950 a 2025; este parâmetro é obrigatório, então você deve especificar pelo menos um ano.', es: 'Los años a importar, por ejemplo [2015, 2016, 2017]. Los datos están disponibles desde 1950 hasta 2025; este parámetro es obligatorio, así que debe especificar al menos un año.', zh: '要导入的年份，例如 [2015, 2016, 2017]。数据覆盖 1950 至 2025 年；此参数为必填项，因此你必须至少指定一个年份。' },
  'lcz_grid_era5.months': { en: 'Which months (1-12) to include, e.g. [1, 2, 12] for a winter analysis. Leave blank to get all 12 months of each requested year.', pt: 'Quais meses (1-12) incluir, por exemplo [1, 2, 12] para uma análise de inverno. Deixe em branco para obter os 12 meses de cada ano solicitado.', es: 'Qué meses (1-12) incluir, por ejemplo [1, 2, 12] para un análisis de invierno. Déjelo en blanco para obtener los 12 meses de cada año solicitado.', zh: '要包含的月份（1-12），例如 [1, 2, 12] 表示冬季分析。留空则获取每个请求年份的全部 12 个月。' },
  'lcz_grid_era5.vars': { en: 'Which climate variables to fetch: t2m (2-m air temperature), t2m_max/t2m_min (daily max/min temperature), td2m (dew point), u10/v10 (wind components), sp (surface pressure), tp (total precipitation), or "all" for every variable. Defaults to temperature and precipitation (t2m, tp).', pt: 'Quais variáveis climáticas buscar: t2m (temperatura do ar a 2 m), t2m_max/t2m_min (temperatura máxima/mínima diária), td2m (ponto de orvalho), u10/v10 (componentes do vento), sp (pressão de superfície), tp (precipitação total), ou "all" para todas as variáveis. O padrão é temperatura e precipitação (t2m, tp).', es: 'Qué variables climáticas obtener: t2m (temperatura del aire a 2 m), t2m_max/t2m_min (temperatura diaria máxima/mínima), td2m (punto de rocío), u10/v10 (componentes del viento), sp (presión superficial), tp (precipitación total), o "all" para todas las variables. Por defecto son temperatura y precipitación (t2m, tp).', zh: '要获取的气候变量：t2m（2 米气温）、t2m_max/t2m_min（日最高/最低气温）、td2m（露点温度）、u10/v10（风速分量）、sp（地面气压）、tp（总降水量），或“all”表示所有变量。默认获取气温和降水（t2m、tp）。' },
  'lcz_grid_era5.resampling': { en: 'How values are recalculated onto your LCZ map\'s grid. "average" (the default) is a sensible general choice; "bilinear" gives smoother interpolation for continuous fields like temperature; "nearest" just copies the closest value without blending.', pt: 'Como os valores são recalculados sobre a grade do seu mapa LCZ. "average" (padrão) é uma escolha geral sensata; "bilinear" dá interpolação mais suave para campos contínuos como temperatura; "nearest" apenas copia o valor mais próximo sem mistura.', es: 'Cómo se recalculan los valores sobre la cuadrícula de su mapa LCZ. "average" (por defecto) es una elección general razonable; "bilinear" da una interpolación más suave para campos continuos como la temperatura; "nearest" simplemente copia el valor más cercano sin mezclar.', zh: '如何将数值重新计算到 LCZ 地图的网格上。“average”（默认）是合理的通用选择；“bilinear”为气温等连续场提供更平滑的插值；“nearest”只是直接复制最近的值，不做混合。' },
  'lcz_grid_era5.isave': { en: 'When turned on, also saves a copy of the downloaded data into your project\'s LCZ4r_output folder for easy reuse later.', pt: 'Quando ativado, também salva uma cópia dos dados baixados na pasta LCZ4r_output do seu projeto, para reutilização fácil mais tarde.', es: 'Al activarlo, guarda además una copia de los datos descargados en la carpeta LCZ4r_output de su proyecto para facilitar su reutilización posterior.', zh: '开启后还会将下载的数据副本保存到项目的 LCZ4r_output 文件夹，便于日后重复使用。' },
  'lcz_grid_era5.cache': { en: 'When on (the default), reuses previously downloaded and processed data for the same years, months, variables, and map area, avoiding repeat downloads.', pt: 'Quando ativado (padrão), reutiliza dados já baixados e processados para os mesmos anos, meses, variáveis e área do mapa, evitando downloads repetidos.', es: 'Cuando está activado (por defecto), reutiliza los datos ya descargados y procesados para los mismos años, meses, variables y área de mapa, evitando descargas repetidas.', zh: '开启时（默认），会复用此前针对相同年份、月份、变量和地图区域已下载和处理过的数据，避免重复下载。' },
  'lcz_grid_era5.cache_dir': { en: 'The folder where downloaded climate files are stored for reuse. Most users can leave this at its default and never touch it.', pt: 'A pasta onde os arquivos climáticos baixados são armazenados para reutilização. A maioria dos usuários pode deixar no padrão e nunca mexer.', es: 'La carpeta donde se almacenan los archivos climáticos descargados para reutilizarlos. La mayoría de los usuarios puede dejarla en su valor por defecto y nunca tocarla.', zh: '存储已下载气候文件以便复用的文件夹。大多数用户可保持默认设置，无需更改。' },
  'lcz_grid_era5.verbose': { en: 'When on (the default), prints progress messages during download so you can follow along as the data comes in.', pt: 'Quando ativado (padrão), imprime mensagens de progresso durante o download, para que você acompanhe conforme os dados chegam.', es: 'Cuando está activado (por defecto), imprime mensajes de progreso durante la descarga para que pueda seguir cómo van llegando los datos.', zh: '开启时（默认），下载过程中会打印进度信息，便于你跟踪数据获取进度。' },
  'lcz_grid_era5_global.x': { en: 'The LCZ map file (a GeoTIFF) whose area you want global climate data for, covering any region worldwide.', pt: 'O arquivo de mapa LCZ (um GeoTIFF) cuja área você quer dados climáticos globais, cobrindo qualquer região do mundo.', es: 'El archivo de mapa LCZ (un GeoTIFF) cuya área desea usar para obtener datos climáticos globales, en cualquier región del mundo.', zh: '你想获取全球气候数据的 LCZ 地图文件（GeoTIFF），可覆盖世界任意地区。' },
  'lcz_grid_era5_global.years': { en: 'The years to import, e.g. [2018, 2019, 2020]. Data is available from 1950 to the present; you must specify at least one year.', pt: 'Os anos a importar, por exemplo [2018, 2019, 2020]. Dados disponíveis de 1950 até o presente; é necessário especificar pelo menos um ano.', es: 'Los años a importar, por ejemplo [2018, 2019, 2020]. Los datos están disponibles desde 1950 hasta el presente; debe especificar al menos un año.', zh: '要导入的年份，例如 [2018, 2019, 2020]。数据覆盖 1950 年至今；你必须至少指定一个年份。' },
  'lcz_grid_era5_global.months': { en: 'Which months (1-12) to include, e.g. [3, 4, 5] for a spring analysis. Leave blank to get all 12 months.', pt: 'Quais meses (1-12) incluir, por exemplo [3, 4, 5] para uma análise de primavera. Deixe em branco para obter todos os 12 meses.', es: 'Qué meses (1-12) incluir, por ejemplo [3, 4, 5] para un análisis de primavera. Déjelo en blanco para obtener los 12 meses.', zh: '要包含的月份（1-12），例如 [3, 4, 5] 表示春季分析。留空则获取全部 12 个月。' },
  'lcz_grid_era5_global.vars': { en: 'Which climate variables to fetch: t2m (temperature), td2m (dew point), u10/v10 (wind components), sp (surface pressure), tp (precipitation), skt (skin temperature), or "all". Defaults to temperature and precipitation. Note that daily max/min temperature is not available here since this product only provides monthly averages.', pt: 'Quais variáveis climáticas buscar: t2m (temperatura), td2m (ponto de orvalho), u10/v10 (componentes do vento), sp (pressão de superfície), tp (precipitação), skt (temperatura da pele/superfície), ou "all". O padrão é temperatura e precipitação. Observe que temperatura máxima/mínima diária não está disponível aqui, já que este produto só fornece médias mensais.', es: 'Qué variables climáticas obtener: t2m (temperatura), td2m (punto de rocío), u10/v10 (componentes del viento), sp (presión superficial), tp (precipitación), skt (temperatura de la piel terrestre), o "all". Por defecto son temperatura y precipitación. Tenga en cuenta que aquí no está disponible la temperatura máxima/mínima diaria, ya que este producto solo ofrece promedios mensuales.', zh: '要获取的气候变量：t2m（气温）、td2m（露点温度）、u10/v10（风速分量）、sp（地面气压）、tp（降水量）、skt（地表皮肤温度），或“all”。默认获取气温和降水。注意此处不提供日最高/最低气温，因为该产品只提供月平均值。' },
  'lcz_grid_era5_global.resampling': { en: 'How values are recalculated onto your LCZ map\'s grid. "average" (the default) is a safe general choice; "bilinear" smooths continuous fields like temperature; "nearest" copies the closest value with no blending.', pt: 'Como os valores são recalculados sobre a grade do seu mapa LCZ. "average" (padrão) é uma escolha geral segura; "bilinear" suaviza campos contínuos como temperatura; "nearest" copia o valor mais próximo sem mistura.', es: 'Cómo se recalculan los valores sobre la cuadrícula de su mapa LCZ. "average" (por defecto) es una opción general segura; "bilinear" suaviza campos continuos como la temperatura; "nearest" copia el valor más cercano sin mezclar.', zh: '如何将数值重新计算到 LCZ 地图的网格上。“average”（默认）是稳妥的通用选择；“bilinear”会平滑气温等连续场；“nearest”直接复制最近的值，不做混合。' },
  'lcz_grid_era5_global.cds_key': { en: 'Your Copernicus Climate Data Store API key, needed to authorize the download. If left blank, it is read automatically from a CDSAPI_KEY environment variable or a saved ~/.cdsapirc credentials file, so most users can set this up once and ignore the parameter afterward.', pt: 'Sua chave de API do Copernicus Climate Data Store, necessária para autorizar o download. Se deixada em branco, é lida automaticamente de uma variável de ambiente CDSAPI_KEY ou de um arquivo de credenciais salvo ~/.cdsapirc, então a maioria dos usuários pode configurá-la uma vez e ignorar o parâmetro depois.', es: 'Su clave de API del Copernicus Climate Data Store, necesaria para autorizar la descarga. Si se deja en blanco, se lee automáticamente de una variable de entorno CDSAPI_KEY o de un archivo de credenciales ~/.cdsapirc guardado, así que la mayoría de los usuarios puede configurarla una sola vez y luego ignorar el parámetro.', zh: '你的哥白尼气候数据存储库 API 密钥，用于授权下载。留空则自动从 CDSAPI_KEY 环境变量或已保存的 ~/.cdsapirc 凭据文件中读取，因此大多数用户只需设置一次，之后可以忽略此参数。' },
  'lcz_grid_era5_global.cds_url': { en: 'The Copernicus Climate Data Store server address paired with your API key. Like cds_key, it is normally read automatically from your environment or credentials file, so you can usually leave it blank.', pt: 'O endereço do servidor do Copernicus Climate Data Store associado à sua chave de API. Assim como cds_key, normalmente é lido automaticamente do seu ambiente ou arquivo de credenciais, então geralmente pode ser deixado em branco.', es: 'La dirección del servidor del Copernicus Climate Data Store, junto con su clave de API. Igual que cds_key, normalmente se lee automáticamente del entorno o del archivo de credenciales, así que por lo general puede dejarla en blanco.', zh: '与你的 API 密钥配对的哥白尼气候数据存储库服务器地址。与 cds_key 一样，通常会自动从你的环境变量或凭据文件中读取，因此一般可以留空。' },
  'lcz_grid_era5_global.isave': { en: 'When turned on, also saves a copy of the downloaded data into your project\'s LCZ4r_output folder.', pt: 'Quando ativado, também salva uma cópia dos dados baixados na pasta LCZ4r_output do seu projeto.', es: 'Al activarlo, guarda además una copia de los datos descargados en la carpeta LCZ4r_output de su proyecto.', zh: '开启后还会将下载的数据副本保存到项目的 LCZ4r_output 文件夹。' },
  'lcz_grid_era5_global.cache': { en: 'When on (the default), reuses previously downloaded and processed data for the same years, months, variables, and map area, saving time on repeat requests.', pt: 'Quando ativado (padrão), reutiliza dados já baixados e processados para os mesmos anos, meses, variáveis e área do mapa, economizando tempo em pedidos repetidos.', es: 'Cuando está activado (por defecto), reutiliza los datos ya descargados y procesados para los mismos años, meses, variables y área de mapa, ahorrando tiempo en solicitudes repetidas.', zh: '开启时（默认），会复用此前针对相同年份、月份、变量和地图区域已下载和处理过的数据，节省重复请求的时间。' },
  'lcz_grid_era5_global.cache_dir': { en: 'The folder where downloaded files are stored for reuse. Most users can leave this at its default location.', pt: 'A pasta onde os arquivos baixados são armazenados para reutilização. A maioria dos usuários pode deixar no local padrão.', es: 'La carpeta donde se almacenan los archivos descargados para reutilizarlos. La mayoría de los usuarios puede dejarla en su ubicación por defecto.', zh: '存储已下载文件以便复用的文件夹。大多数用户可保持默认位置。' },
  'lcz_grid_era5_global.verbose': { en: 'When on (the default), prints progress messages while data downloads.', pt: 'Quando ativado (padrão), imprime mensagens de progresso enquanto os dados são baixados.', es: 'Cuando está activado (por defecto), imprime mensajes de progreso mientras se descargan los datos.', zh: '开启时（默认），数据下载过程中会打印进度信息。' },
  'lcz_grid_pdsi.x': { en: 'The LCZ map file (a GeoTIFF) whose area you want drought index data for.', pt: 'O arquivo de mapa LCZ (um GeoTIFF) cuja área você quer dados de índice de seca.', es: 'El archivo de mapa LCZ (un GeoTIFF) cuya área desea usar para obtener datos del índice de sequía.', zh: '你想获取干旱指数数据的 LCZ 地图文件（GeoTIFF）所对应的区域。' },
  'lcz_grid_pdsi.years': { en: 'Which years to download, e.g. [2019, 2020]. Available range depends on the source: 1950-2025 for TerraClimate, 1850-2018 for NOAA PSL. Leave blank to get the last two complete years automatically.', pt: 'Quais anos baixar, por exemplo [2019, 2020]. O intervalo disponível depende da fonte: 1950-2025 para TerraClimate, 1850-2018 para NOAA PSL. Deixe em branco para obter os dois últimos anos completos automaticamente.', es: 'Qué años descargar, por ejemplo [2019, 2020]. El rango disponible depende de la fuente: 1950-2025 para TerraClimate, 1850-2018 para NOAA PSL. Déjelo en blanco para obtener automáticamente los últimos dos años completos.', zh: '要下载的年份，例如 [2019, 2020]。可用范围取决于数据来源：TerraClimate 为 1950-2025 年，NOAA PSL 为 1850-2018 年。留空则自动获取最近两个完整年份。' },
  'lcz_grid_pdsi.months': { en: 'Which months (1-12) to include, e.g. [7, 8, 9] for a dry-season check. Leave blank to include all 12 months.', pt: 'Quais meses (1-12) incluir, por exemplo [7, 8, 9] para verificar a estação seca. Deixe em branco para incluir todos os 12 meses.', es: 'Qué meses (1-12) incluir, por ejemplo [7, 8, 9] para revisar la temporada seca. Déjelo en blanco para incluir los 12 meses.', zh: '要包含的月份（1-12），例如 [7, 8, 9] 用于检查旱季情况。留空则包含全部 12 个月。' },
  'lcz_grid_pdsi.source': { en: 'Which drought dataset to use: "terraclimate" (the default, finer detail at about 4 km resolution but only back to 1950) or "noaa_psl" (coarser at about 2.5 degrees, but with a much longer historical record back to 1850).', pt: 'Qual conjunto de dados de seca usar: "terraclimate" (padrão, detalhe mais fino, cerca de 4 km de resolução, mas somente desde 1950) ou "noaa_psl" (mais grosseiro, cerca de 2,5 graus, porém com um registro histórico bem mais longo, desde 1850).', es: 'Qué conjunto de datos de sequía usar: "terraclimate" (por defecto, más detalle, con unos 4 km de resolución, pero solo desde 1950) o "noaa_psl" (más grueso, unos 2,5 grados, pero con un registro histórico mucho más largo, desde 1850).', zh: '要使用的干旱数据集：“terraclimate”（默认，约 4 公里分辨率更精细，但只能追溯到 1950 年），或“noaa_psl”（约 2.5 度分辨率较粗，但历史记录长得多，可追溯到 1850 年）。' },
  'lcz_grid_pdsi.resampling': { en: 'How values are recalculated onto your LCZ map\'s grid. "average" (the default) is a good general choice; "bilinear" gives smoother results; "nearest" copies the closest value directly.', pt: 'Como os valores são recalculados sobre a grade do seu mapa LCZ. "average" (padrão) é uma boa escolha geral; "bilinear" dá resultados mais suaves; "nearest" copia diretamente o valor mais próximo.', es: 'Cómo se recalculan los valores sobre la cuadrícula de su mapa LCZ. "average" (por defecto) es una buena elección general; "bilinear" da resultados más suaves; "nearest" copia directamente el valor más cercano.', zh: '如何将数值重新计算到 LCZ 地图的网格上。“average”（默认）是不错的通用选择；“bilinear”结果更平滑；“nearest”直接复制最近的值。' },
  'lcz_grid_pdsi.isave': { en: 'When turned on, also saves a copy of the downloaded data into your project\'s LCZ4r_output folder.', pt: 'Quando ativado, também salva uma cópia dos dados baixados na pasta LCZ4r_output do seu projeto.', es: 'Al activarlo, guarda además una copia de los datos descargados en la carpeta LCZ4r_output de su proyecto.', zh: '开启后还会将下载的数据副本保存到项目的 LCZ4r_output 文件夹。' },
  'lcz_grid_pdsi.cache': { en: 'When on (the default), reuses previously downloaded and processed data for the same source, years, months, and map area, so repeat runs are faster.', pt: 'Quando ativado (padrão), reutiliza dados já baixados e processados para a mesma fonte, anos, meses e área do mapa, tornando execuções repetidas mais rápidas.', es: 'Cuando está activado (por defecto), reutiliza los datos ya descargados y procesados para la misma fuente, años, meses y área de mapa, de modo que las ejecuciones repetidas sean más rápidas.', zh: '开启时（默认），会复用此前针对相同数据源、年份、月份和地图区域已下载和处理过的数据，使重复运行更快。' },
  'lcz_grid_pdsi.cache_dir': { en: 'The folder where downloaded files are stored for reuse. Most users can leave this at its default location.', pt: 'A pasta onde os arquivos baixados são armazenados para reutilização. A maioria dos usuários pode deixar no local padrão.', es: 'La carpeta donde se almacenan los archivos descargados para reutilizarlos. La mayoría de los usuarios puede dejarla en su ubicación por defecto.', zh: '存储已下载文件以便复用的文件夹。大多数用户可保持默认位置。' },
  'lcz_grid_pdsi.verbose': { en: 'When on (the default), prints progress messages while data downloads.', pt: 'Quando ativado (padrão), imprime mensagens de progresso enquanto os dados são baixados.', es: 'Cuando está activado (por defecto), imprime mensajes de progreso mientras se descargan los datos.', zh: '开启时（默认），数据下载过程中会打印进度信息。' },
  'lcz_grid_pollution_ghap.x': { en: 'The LCZ map file (a GeoTIFF) whose area you want pollution data for.', pt: 'O arquivo de mapa LCZ (um GeoTIFF) cuja área você quer dados de poluição.', es: 'El archivo de mapa LCZ (un GeoTIFF) cuya área desea usar para obtener datos de contaminación.', zh: '你想获取污染数据的 LCZ 地图文件（GeoTIFF）所对应的区域。' },
  'lcz_grid_pollution_ghap.pollutants': { en: 'Which pollutant(s) to download: "pm25" (fine particulate matter, the default), "o3" (ozone), "co" (carbon monoxide), or "all" for every available pollutant. Nitrogen dioxide (no2) is not yet publicly available in this dataset.', pt: 'Qual(is) poluente(s) baixar: "pm25" (material particulado fino, padrão), "o3" (ozônio), "co" (monóxido de carbono), ou "all" para todos os poluentes disponíveis. O dióxido de nitrogênio (no2) ainda não está disponível publicamente neste conjunto de dados.', es: 'Qué contaminante o contaminantes descargar: "pm25" (material particulado fino, por defecto), "o3" (ozono), "co" (monóxido de carbono), o "all" para todos los contaminantes disponibles. El dióxido de nitrógeno (no2) aún no está disponible públicamente en este conjunto de datos.', zh: '要下载的污染物：“pm25”（细颗粒物，默认）、“o3”（臭氧）、“co”（一氧化碳），或“all”表示所有可用污染物。二氧化氮（no2）在此数据集中尚未公开提供。' },
  'lcz_grid_pollution_ghap.resolution': { en: 'How finely the data is summarized over time: "daily" or "monthly" (available for PM2.5 only), or "annual" (available for all pollutants). If you request ozone or carbon monoxide at daily or monthly resolution, the function automatically falls back to annual data.', pt: 'Com que detalhe os dados são resumidos ao longo do tempo: "daily" ou "monthly" (disponíveis apenas para PM2,5), ou "annual" (disponível para todos os poluentes). Se você solicitar ozônio ou monóxido de carbono em resolução diária ou mensal, a função retorna automaticamente para dados anuais.', es: 'Con qué finura se resumen los datos en el tiempo: "daily" o "monthly" (disponibles solo para PM2.5), o "annual" (disponible para todos los contaminantes). Si solicita ozono o monóxido de carbono con resolución diaria o mensual, la función recurre automáticamente a los datos anuales.', zh: '数据在时间上的汇总精细程度：“daily”或“monthly”（仅适用于 PM2.5），或“annual”（适用于所有污染物）。如果你以日或月分辨率请求臭氧或一氧化碳，函数会自动回退为年度数据。' },
  'lcz_grid_pollution_ghap.years': { en: 'Which years to download, e.g. [2021, 2022]. Leave blank to get all years available for the chosen pollutant and resolution.', pt: 'Quais anos baixar, por exemplo [2021, 2022]. Deixe em branco para obter todos os anos disponíveis para o poluente e a resolução escolhidos.', es: 'Qué años descargar, por ejemplo [2021, 2022]. Déjelo en blanco para obtener todos los años disponibles para el contaminante y la resolución elegidos.', zh: '要下载的年份，例如 [2021, 2022]。留空则获取所选污染物和分辨率下所有可用年份。' },
  'lcz_grid_pollution_ghap.months': { en: 'Which months (1-12) to include when using daily or monthly resolution, e.g. [1, 2, 3]. Leave blank to include all 12 months.', pt: 'Quais meses (1-12) incluir ao usar resolução diária ou mensal, por exemplo [1, 2, 3]. Deixe em branco para incluir todos os 12 meses.', es: 'Qué meses (1-12) incluir al usar resolución diaria o mensual, por ejemplo [1, 2, 3]. Déjelo en blanco para incluir los 12 meses.', zh: '使用日或月分辨率时要包含的月份（1-12），例如 [1, 2, 3]。留空则包含全部 12 个月。' },
  'lcz_grid_pollution_ghap.resampling': { en: 'How values are recalculated onto your LCZ map\'s grid. "average" (the default) is a sound general choice; "bilinear" gives smoother interpolation; "nearest" copies the closest value directly.', pt: 'Como os valores são recalculados sobre a grade do seu mapa LCZ. "average" (padrão) é uma boa escolha geral; "bilinear" dá interpolação mais suave; "nearest" copia diretamente o valor mais próximo.', es: 'Cómo se recalculan los valores sobre la cuadrícula de su mapa LCZ. "average" (por defecto) es una elección general sólida; "bilinear" da una interpolación más suave; "nearest" copia directamente el valor más cercano.', zh: '如何将数值重新计算到 LCZ 地图的网格上。“average”（默认）是稳妥的通用选择；“bilinear”提供更平滑的插值；“nearest”直接复制最近的值。' },
  'lcz_grid_pollution_ghap.isave': { en: 'When turned on, also saves a copy of the downloaded data into your project\'s LCZ4r_output folder.', pt: 'Quando ativado, também salva uma cópia dos dados baixados na pasta LCZ4r_output do seu projeto.', es: 'Al activarlo, guarda además una copia de los datos descargados en la carpeta LCZ4r_output de su proyecto.', zh: '开启后还会将下载的数据副本保存到项目的 LCZ4r_output 文件夹。' },
  'lcz_grid_pollution_ghap.cache': { en: 'When on (the default), reuses previously downloaded and processed data for the same pollutants, resolution, years, months, and map area, so repeat runs are faster.', pt: 'Quando ativado (padrão), reutiliza dados já baixados e processados para os mesmos poluentes, resolução, anos, meses e área do mapa, tornando execuções repetidas mais rápidas.', es: 'Cuando está activado (por defecto), reutiliza los datos ya descargados y procesados para los mismos contaminantes, resolución, años, meses y área de mapa, de modo que las ejecuciones repetidas sean más rápidas.', zh: '开启时（默认），会复用此前针对相同污染物、分辨率、年份、月份和地图区域已下载和处理过的数据，使重复运行更快。' },
  'lcz_grid_pollution_ghap.cache_dir': { en: 'The folder where downloaded files are stored for reuse. Most users can leave this at its default location.', pt: 'A pasta onde os arquivos baixados são armazenados para reutilização. A maioria dos usuários pode deixar no local padrão.', es: 'La carpeta donde se almacenan los archivos descargados para reutilizarlos. La mayoría de los usuarios puede dejarla en su ubicación por defecto.', zh: '存储已下载文件以便复用的文件夹。大多数用户可保持默认位置。' },
  'lcz_grid_pollution_ghap.verbose': { en: 'When on (the default), prints progress messages while data downloads.', pt: 'Quando ativado (padrão), imprime mensagens de progresso enquanto os dados são baixados.', es: 'Cuando está activado (por defecto), imprime mensajes de progreso mientras se descargan los datos.', zh: '开启时（默认），数据下载过程中会打印进度信息。' },
  'lcz_grid_pollution_merra2.x': { en: 'The LCZ map file (a GeoTIFF) whose area you want aerosol/pollution data for.', pt: 'O arquivo de mapa LCZ (um GeoTIFF) cuja área você quer dados de aerossóis/poluição.', es: 'El archivo de mapa LCZ (un GeoTIFF) cuya área desea usar para obtener datos de aerosoles/contaminación.', zh: '你想获取气溶胶/污染数据的 LCZ 地图文件（GeoTIFF）所对应的区域。' },
  'lcz_grid_pollution_merra2.pollutants': { en: 'Which variable(s) to download: "pm25" (fine particulate matter), "aod" (aerosol optical depth, a measure of haze and dust in the atmosphere), or "so2" (sulfur dioxide). Defaults to pm25 and aod together.', pt: 'Qual(is) variável(is) baixar: "pm25" (material particulado fino), "aod" (profundidade óptica de aerossóis, uma medida de neblina e poeira na atmosfera), ou "so2" (dióxido de enxofre). O padrão é pm25 e aod juntos.', es: 'Qué variable o variables descargar: "pm25" (material particulado fino), "aod" (profundidad óptica de aerosoles, una medida de la neblina y el polvo en la atmósfera), o "so2" (dióxido de azufre). Por defecto pm25 y aod juntos.', zh: '要下载的变量：“pm25”（细颗粒物）、“aod”（气溶胶光学厚度，衡量大气中雾霾和扬尘程度的指标），或“so2”（二氧化硫）。默认同时获取 pm25 和 aod。' },
  'lcz_grid_pollution_merra2.resolution': { en: 'How the data is summarized over time: "monthly" (the default) or "daily". Sulfur dioxide (so2) is only available at monthly resolution.', pt: 'Como os dados são resumidos ao longo do tempo: "monthly" (padrão) ou "daily". O dióxido de enxofre (so2) só está disponível em resolução mensal.', es: 'Cómo se resumen los datos en el tiempo: "monthly" (por defecto) o "daily". El dióxido de azufre (so2) solo está disponible con resolución mensual.', zh: '数据在时间上的汇总方式：“monthly”（默认）或“daily”。二氧化硫（so2）仅提供月分辨率。' },
  'lcz_grid_pollution_merra2.years': { en: 'Which years to download, e.g. [2020, 2021]. Data is available from 1980 to the present; leave blank to get the last two complete years automatically.', pt: 'Quais anos baixar, por exemplo [2020, 2021]. Dados disponíveis de 1980 até o presente; deixe em branco para obter os dois últimos anos completos automaticamente.', es: 'Qué años descargar, por ejemplo [2020, 2021]. Los datos están disponibles desde 1980 hasta el presente; déjelo en blanco para obtener automáticamente los últimos dos años completos.', zh: '要下载的年份，例如 [2020, 2021]。数据覆盖 1980 年至今；留空则自动获取最近两个完整年份。' },
  'lcz_grid_pollution_merra2.months': { en: 'Which months (1-12) to include, e.g. [6, 7, 8]. Leave blank to include all 12 months.', pt: 'Quais meses (1-12) incluir, por exemplo [6, 7, 8]. Deixe em branco para incluir todos os 12 meses.', es: 'Qué meses (1-12) incluir, por ejemplo [6, 7, 8]. Déjelo en blanco para incluir los 12 meses.', zh: '要包含的月份（1-12），例如 [6, 7, 8]。留空则包含全部 12 个月。' },
  'lcz_grid_pollution_merra2.resampling': { en: 'How values are recalculated onto your LCZ map\'s grid. "average" (the default) is a good general choice; "bilinear" smooths continuous fields; "nearest" copies the closest value directly.', pt: 'Como os valores são recalculados sobre a grade do seu mapa LCZ. "average" (padrão) é uma boa escolha geral; "bilinear" suaviza campos contínuos; "nearest" copia diretamente o valor mais próximo.', es: 'Cómo se recalculan los valores sobre la cuadrícula de su mapa LCZ. "average" (por defecto) es una buena elección general; "bilinear" suaviza campos continuos; "nearest" copia directamente el valor más cercano.', zh: '如何将数值重新计算到 LCZ 地图的网格上。“average”（默认）是不错的通用选择；“bilinear”会平滑连续场；“nearest”直接复制最近的值。' },
  'lcz_grid_pollution_merra2.earthdata_user': { en: 'Your NASA Earthdata Login username, needed to authorize the download. If left blank, it is read automatically from an EARTHDATA_USER environment variable, so most users can set this up once and skip entering it each time.', pt: 'Seu nome de usuário do NASA Earthdata Login, necessário para autorizar o download. Se deixado em branco, é lido automaticamente de uma variável de ambiente EARTHDATA_USER, então a maioria dos usuários pode configurá-la uma vez e não precisa digitá-la de novo.', es: 'Su nombre de usuario de NASA Earthdata Login, necesario para autorizar la descarga. Si se deja en blanco, se lee automáticamente de una variable de entorno EARTHDATA_USER, así que la mayoría de los usuarios puede configurarla una sola vez y no volver a escribirla cada vez.', zh: '你的 NASA Earthdata 登录用户名，用于授权下载。留空则自动从 EARTHDATA_USER 环境变量读取，因此大多数用户只需设置一次，之后无需每次输入。' },
  'lcz_grid_pollution_merra2.earthdata_pass': { en: 'Your NASA Earthdata Login password, paired with earthdata_user. If left blank, it is read automatically from an EARTHDATA_PASSWORD environment variable.', pt: 'Sua senha do NASA Earthdata Login, associada a earthdata_user. Se deixada em branco, é lida automaticamente de uma variável de ambiente EARTHDATA_PASSWORD.', es: 'Su contraseña de NASA Earthdata Login, junto con earthdata_user. Si se deja en blanco, se lee automáticamente de una variable de entorno EARTHDATA_PASSWORD.', zh: '你的 NASA Earthdata 登录密码，与 earthdata_user 配对使用。留空则自动从 EARTHDATA_PASSWORD 环境变量读取。' },
  'lcz_grid_pollution_merra2.netrc_path': { en: 'An advanced option pointing to a saved credentials file (.netrc) instead of typing your username and password directly; if provided, it overrides them. Typical users can leave this blank and rely on the username/password or environment variables instead.', pt: 'Uma opção avançada apontando para um arquivo de credenciais salvo (.netrc) em vez de digitar seu usuário e senha diretamente; se informado, tem prioridade sobre eles. A maioria dos usuários pode deixar em branco e confiar no usuário/senha ou nas variáveis de ambiente.', es: 'Una opción avanzada que apunta a un archivo de credenciales guardado (.netrc) en lugar de escribir directamente su usuario y contraseña; si se indica, tiene prioridad sobre ellos. Los usuarios habituales pueden dejarlo en blanco y confiar en el usuario/contraseña o en las variables de entorno.', zh: '一个高级选项，指向已保存的凭据文件（.netrc），而不是直接输入用户名和密码；如提供此项，会覆盖用户名和密码设置。一般用户可留空，改用用户名/密码或环境变量。' },
  'lcz_grid_pollution_merra2.isave': { en: 'When turned on, also saves a copy of the downloaded data into your project\'s LCZ4r_output folder.', pt: 'Quando ativado, também salva uma cópia dos dados baixados na pasta LCZ4r_output do seu projeto.', es: 'Al activarlo, guarda además una copia de los datos descargados en la carpeta LCZ4r_output de su proyecto.', zh: '开启后还会将下载的数据副本保存到项目的 LCZ4r_output 文件夹。' },
  'lcz_grid_pollution_merra2.cache': { en: 'When on (the default), reuses previously downloaded and processed data for the same pollutants, years, months, and map area, so repeat runs are faster.', pt: 'Quando ativado (padrão), reutiliza dados já baixados e processados para os mesmos poluentes, anos, meses e área do mapa, tornando execuções repetidas mais rápidas.', es: 'Cuando está activado (por defecto), reutiliza los datos ya descargados y procesados para los mismos contaminantes, años, meses y área de mapa, de modo que las ejecuciones repetidas sean más rápidas.', zh: '开启时（默认），会复用此前针对相同污染物、年份、月份和地图区域已下载和处理过的数据，使重复运行更快。' },
  'lcz_grid_pollution_merra2.cache_dir': { en: 'The folder where downloaded files are stored for reuse. Most users can leave this at its default location.', pt: 'A pasta onde os arquivos baixados são armazenados para reutilização. A maioria dos usuários pode deixar no local padrão.', es: 'La carpeta donde se almacenan los archivos descargados para reutilizarlos. La mayoría de los usuarios puede dejarla en su ubicación por defecto.', zh: '存储已下载文件以便复用的文件夹。大多数用户可保持默认位置。' },
  'lcz_grid_pollution_merra2.verbose': { en: 'When on (the default), prints progress messages while data downloads.', pt: 'Quando ativado (padrão), imprime mensagens de progresso enquanto os dados são baixados.', es: 'Cuando está activado (por defecto), imprime mensajes de progreso mientras se descargan los datos.', zh: '开启时（默认），数据下载过程中会打印进度信息。' },
  'lcz_interp_eval.x': { en: 'The LCZ raster map for your study area. It sets the coordinate system and boundary the accuracy test runs within.', pt: 'O raster LCZ da sua área de estudo. Define o sistema de coordenadas e o limite dentro do qual o teste de precisão roda.', es: 'El mapa ráster LCZ de su área de estudio. Establece el sistema de coordenadas y el límite dentro del cual se ejecuta la prueba de precisión.', zh: '你研究区的 LCZ 栅格地图。它设定了精度测试所依据的坐标系统和边界。' },
  'lcz_interp_eval.data_frame': { en: 'Your table of station observations, with columns for date, station, variable, latitude, and longitude — for example, hourly air-temperature readings from a network of weather stations.', pt: 'Sua tabela de observações de estações, com colunas para data, estação, variável, latitude e longitude — por exemplo, leituras horárias de temperatura do ar de uma rede de estações meteorológicas.', es: 'Su tabla de observaciones de estaciones, con columnas para fecha, estación, variable, latitud y longitud, por ejemplo lecturas horarias de temperatura del aire de una red de estaciones meteorológicas.', zh: '你的站点观测数据表，包含日期、站点、变量、纬度和经度列——例如来自气象站网络的逐小时气温读数。' },
  'lcz_interp_eval.var': { en: 'The name of the column that holds the variable you want to test, such as "airT" for air temperature.', pt: 'O nome da coluna que contém a variável que você quer testar, como "airT" para temperatura do ar.', es: 'El nombre de la columna que contiene la variable que quiere probar, como "airT" para temperatura del aire.', zh: '保存你想测试的变量的列名，例如“airT”表示气温。' },
  'lcz_interp_eval.station_id': { en: 'The name of the column that identifies each station, such as "station_id" or "site_name".', pt: 'O nome da coluna que identifica cada estação, como "station_id" ou "site_name".', es: 'El nombre de la columna que identifica a cada estación, como "station_id" o "site_name".', zh: '标识每个站点的列名，例如“station_id”或“site_name”。' },
  'lcz_interp_eval.LOOCV': { en: 'Chooses the validation method. Leave this on (the default) to test each station one at a time against all the others, which works well with small networks; turn it off to instead hold back a random subset of stations for testing, sized by split_ratio.', pt: 'Escolhe o método de validação. Deixe ativado (padrão) para testar cada estação uma de cada vez contra todas as outras, o que funciona bem com redes pequenas; desative para em vez disso reservar um subconjunto aleatório de estações para teste, dimensionado por split_ratio.', es: 'Elige el método de validación. Déjelo activado (por defecto) para probar cada estación una a una frente a todas las demás, lo que funciona bien con redes pequeñas; desactívelo para en cambio reservar un subconjunto aleatorio de estaciones para pruebas, según split_ratio.', zh: '选择验证方法。保持默认开启可对每个站点逐一进行留一测试（与其余所有站点比较），这在小型站网中效果良好；关闭此项则改为保留一部分随机抽取的站点用于测试，比例由 split_ratio 决定。' },
  'lcz_interp_eval.split_ratio': { en: 'Only used when LOOCV is turned off. Sets what fraction of stations train the model versus get held back for testing — 0.8 means 80% of stations train the model and 20% check its accuracy.', pt: 'Usado apenas quando LOOCV está desativado. Define qual fração das estações treina o modelo versus fica reservada para teste — 0,8 significa que 80% das estações treinam o modelo e 20% verificam sua precisão.', es: 'Solo se usa cuando LOOCV está desactivado. Fija qué fracción de estaciones entrena el modelo frente a las que se reservan para pruebas; 0,8 significa que el 80% de las estaciones entrena el modelo y el 20% comprueba su precisión.', zh: '仅在 LOOCV 关闭时使用。设定用于训练模型的站点比例，其余保留用于测试——0.8 表示 80% 的站点用于训练，20% 用于检验精度。' },
  'lcz_interp_eval.sp_res': { en: 'The size of each grid cell in the interpolation, in meters. The default of 100 gives a 100m x 100m grid; use a smaller value like 30 for a finer map, at the cost of longer processing.', pt: 'O tamanho de cada célula de grade na interpolação, em metros. O padrão de 100 dá uma grade de 100m x 100m; use um valor menor, como 30, para um mapa mais fino, ao custo de processamento mais longo.', es: 'El tamaño de cada celda de la cuadrícula en la interpolación, en metros. El valor por defecto de 100 da una cuadrícula de 100 m x 100 m; use un valor menor, como 30, para un mapa más fino, a costa de un procesamiento más largo.', zh: '插值网格每个格元的大小，单位为米。默认值 100 生成 100 米 x 100 米的网格；使用较小的值（如 30）可得到更精细的地图，但处理耗时更长。' },
  'lcz_interp_eval.tp_res': { en: 'How readings are averaged over time before interpolating, such as by "hour" (default), "day", or "month". Pick a coarser value if your data is noisy at fine time scales.', pt: 'Como as leituras são calculadas na média ao longo do tempo antes de interpolar, como por "hour" (padrão), "day", ou "month". Escolha um valor mais grosseiro se seus dados forem ruidosos em escalas de tempo finas.', es: 'Cómo se promedian las lecturas en el tiempo antes de interpolar, como por "hour" (por defecto), "day" o "month". Elija un valor más grueso si sus datos son ruidosos a escalas de tiempo finas.', zh: '插值前对读数进行时间平均的方式，例如按“hour”（默认）、“day”或“month”。如果数据在精细时间尺度上噪声较大，可选择更粗的值。' },
  'lcz_interp_eval.vg_model': { en: 'The mathematical curve shape used to describe how similarity between stations fades with distance. "Sph" (spherical, the default) works well for most urban temperature data; "Exp" (exponential), "Gau" (Gaussian), and "Ste" (Matern) are alternatives worth trying if the default fit looks poor.', pt: 'O formato da curva matemática usada para descrever como a semelhança entre estações desaparece com a distância. "Sph" (esférico, padrão) funciona bem para a maioria dos dados urbanos de temperatura; "Exp" (exponencial), "Gau" (Gaussiano) e "Ste" (Matérn) são alternativas que vale a pena testar se o ajuste padrão parecer fraco.', es: 'La forma matemática de la curva usada para describir cómo se desvanece con la distancia la similitud entre estaciones. "Sph" (esférico, por defecto) funciona bien para la mayoría de los datos de temperatura urbana; "Exp" (exponencial), "Gau" (gaussiano) y "Ste" (Matérn) son alternativas que vale la pena probar si el ajuste por defecto se ve deficiente.', zh: '用于描述站点间相似度随距离衰减规律的数学曲线形状。“Sph”（球状模型，默认）适用于大多数城市气温数据；如果默认拟合效果不佳，可尝试“Exp”（指数模型）、“Gau”（高斯模型）和“Ste”（马特恩模型）等替代方案。' },
  'lcz_interp_eval.isave': { en: 'Turn this on to save the accuracy results as a CSV file in the LCZ4r_output folder, so you can reopen or share the numbers later.', pt: 'Ative para salvar os resultados de precisão como um arquivo CSV na pasta LCZ4r_output, para que você possa reabrir ou compartilhar os números depois.', es: 'Actívelo para guardar los resultados de precisión como archivo CSV en la carpeta LCZ4r_output, para poder reabrir o compartir los números más tarde.', zh: '开启此项可将精度结果以 CSV 文件形式保存到 LCZ4r_output 文件夹，便于日后重新打开或分享这些数据。' },
  'lcz_interp_eval.LCZinterp': { en: 'When on (the default), the LCZ class of each location is used as an extra predictor during interpolation, which typically improves accuracy in cities with distinct climate zones.', pt: 'Quando ativado (padrão), a classe LCZ de cada localização é usada como um preditor extra durante a interpolação, o que normalmente melhora a precisão em cidades com zonas climáticas bem distintas.', es: 'Cuando está activado (por defecto), la clase LCZ de cada ubicación se usa como un predictor adicional durante la interpolación, lo que suele mejorar la precisión en ciudades con zonas climáticas bien diferenciadas.', zh: '开启时（默认），每个位置的 LCZ 类别会被用作插值的额外预测因子，这通常能提升气候区差异明显的城市中的精度。' },
  'lcz_interp_eval.year': { en: 'Restricts the evaluation to a specific year, such as 2023, if you only want to test that period.', pt: 'Restringe a avaliação a um ano específico, como 2023, se você quiser testar apenas esse período.', es: 'Restringe la evaluación a un año concreto, como 2023, si solo quiere probar ese periodo.', zh: '将评估限定为特定年份，如 2023，如果你只想测试该时段。' },
  'lcz_interp_eval.month': { en: 'Restricts the evaluation to a specific month (e.g. 7 for July), useful for checking summer versus winter accuracy separately.', pt: 'Restringe a avaliação a um mês específico (por exemplo, 7 para julho), útil para verificar a precisão de verão e de inverno separadamente.', es: 'Restringe la evaluación a un mes concreto (por ejemplo 7 para julio), útil para comprobar la precisión de verano frente a invierno por separado.', zh: '将评估限定为特定月份（例如 7 表示 7 月），便于分别检验夏季与冬季的精度。' },
  'lcz_interp_eval.day': { en: 'Restricts the evaluation to a specific day of the month.', pt: 'Restringe a avaliação a um dia específico do mês.', es: 'Restringe la evaluación a un día concreto del mes.', zh: '将评估限定为月份中的特定日期。' },
  'lcz_interp_eval.hour': { en: 'Restricts the evaluation to a specific hour of the day, such as 14 for 2pm, useful for checking daytime versus nighttime heat patterns.', pt: 'Restringe a avaliação a uma hora específica do dia, como 14 para as 14h, útil para verificar padrões de calor diurnos versus noturnos.', es: 'Restringe la evaluación a una hora concreta del día, como 14 para las 2 p. m., útil para comprobar los patrones de calor diurnos frente a los nocturnos.', zh: '将评估限定为一天中的特定小时，如 14 表示下午 2 点，便于检验白天与夜间的热量模式。' },
  'lcz_interp_eval.start': { en: 'The beginning of a custom date range to evaluate, such as "2023-06-01".', pt: 'O início de um intervalo de datas personalizado a avaliar, como "2023-06-01".', es: 'El inicio de un rango de fechas personalizado a evaluar, como "2023-06-01".', zh: '要评估的自定义日期范围起始点，如“2023-06-01”。' },
  'lcz_interp_eval.end': { en: 'The end of a custom date range to evaluate, such as "2023-08-31", paired with start to cover a full summer season.', pt: 'O fim de um intervalo de datas personalizado a avaliar, como "2023-08-31", combinado com start para cobrir uma estação de verão completa.', es: 'El fin de un rango de fechas personalizado a evaluar, como "2023-08-31", combinado con start para cubrir una temporada de verano completa.', zh: '要评估的自定义日期范围结束点，如“2023-08-31”，与 start 搭配可覆盖完整的夏季。' },
  'lcz_interp_eval_plus.x': { en: 'The LCZ raster map for your study area. It sets the coordinate system and boundary the accuracy test runs within.', pt: 'O raster LCZ da sua área de estudo. Define o sistema de coordenadas e o limite dentro do qual o teste de precisão roda.', es: 'El mapa ráster LCZ de su área de estudio. Establece el sistema de coordenadas y el límite dentro del cual se ejecuta la prueba de precisión.', zh: '你研究区的 LCZ 栅格地图。它设定了精度测试所依据的坐标系统和边界。' },
  'lcz_interp_eval_plus.data_frame': { en: 'Your table of station observations, with columns for date, station, variable, latitude, and longitude.', pt: 'Sua tabela de observações de estações, com colunas para data, estação, variável, latitude e longitude.', es: 'Su tabla de observaciones de estaciones, con columnas para fecha, estación, variable, latitud y longitud.', zh: '你的站点观测数据表，包含日期、站点、变量、纬度和经度列。' },
  'lcz_interp_eval_plus.var': { en: 'The name of the column that holds the variable you want to test, such as "airT" for air temperature.', pt: 'O nome da coluna que contém a variável que você quer testar, como "airT" para temperatura do ar.', es: 'El nombre de la columna que contiene la variable que quiere probar, como "airT" para temperatura del aire.', zh: '保存你想测试的变量的列名，例如“airT”表示气温。' },
  'lcz_interp_eval_plus.station_id': { en: 'The name of the column that identifies each station.', pt: 'O nome da coluna que identifica cada estação.', es: 'El nombre de la columna que identifica a cada estación.', zh: '标识每个站点的列名。' },
  'lcz_interp_eval_plus.ml_model': { en: 'Which machine-learning model to test. "rf" (Random Forest, the default) captures non-linear patterns and works well when many urban predictors are involved; "ols" (a standard linear regression) is faster and easier to interpret but assumes simpler, straight-line relationships.', pt: 'Qual modelo de aprendizado de máquina testar. "rf" (Random Forest, padrão) captura padrões não lineares e funciona bem quando muitos preditores urbanos estão envolvidos; "ols" (uma regressão linear padrão) é mais rápido e fácil de interpretar, mas assume relações mais simples e lineares.', es: 'Qué modelo de aprendizaje automático probar. "rf" (Random Forest, por defecto) capta patrones no lineales y funciona bien cuando intervienen muchos predictores urbanos; "ols" (una regresión lineal estándar) es más rápido y fácil de interpretar, pero asume relaciones más simples y lineales.', zh: '要测试的机器学习模型。“rf”（随机森林，默认）能捕捉非线性模式，适合涉及多个城市预测因子的场景；“ols”（标准线性回归）速度更快、更易解读，但假设关系更简单、呈直线关系。' },
  'lcz_interp_eval_plus.LOOCV': { en: 'Chooses the validation method. Leave this on (the default) to test each station one at a time against all the others; turn it off to instead hold back a random subset of stations for testing, sized by split_ratio.', pt: 'Escolhe o método de validação. Deixe ativado (padrão) para testar cada estação uma de cada vez contra todas as outras; desative para em vez disso reservar um subconjunto aleatório de estações para teste, dimensionado por split_ratio.', es: 'Elige el método de validación. Déjelo activado (por defecto) para probar cada estación una a una frente a todas las demás; desactívelo para en cambio reservar un subconjunto aleatorio de estaciones para pruebas, según split_ratio.', zh: '选择验证方法。保持默认开启可对每个站点逐一进行留一测试；关闭此项则改为保留一部分随机抽取的站点用于测试，比例由 split_ratio 决定。' },
  'lcz_interp_eval_plus.split_ratio': { en: 'Only used when LOOCV is turned off. Fraction of stations used for training versus held back for testing, e.g. 0.8 trains on 80% of stations and tests on the rest.', pt: 'Usado apenas quando LOOCV está desativado. Fração de estações usadas para treino versus reservadas para teste, por exemplo 0,8 treina em 80% das estações e testa no restante.', es: 'Solo se usa cuando LOOCV está desactivado. Fracción de estaciones usada para entrenar frente a las reservadas para pruebas, por ejemplo 0,8 entrena con el 80% de las estaciones y prueba con el resto.', zh: '仅在 LOOCV 关闭时使用。用于训练与保留测试的站点比例，例如 0.8 表示用 80% 的站点训练，其余用于测试。' },
  'lcz_interp_eval_plus.sp_res': { en: 'The size of each grid cell in meters. The default of 100 gives a 100m x 100m grid; a smaller value gives a finer map but takes longer to compute.', pt: 'O tamanho de cada célula de grade em metros. O padrão de 100 dá uma grade de 100m x 100m; um valor menor dá um mapa mais fino, mas leva mais tempo para calcular.', es: 'El tamaño de cada celda de la cuadrícula, en metros. El valor por defecto de 100 da una cuadrícula de 100 m x 100 m; un valor menor da un mapa más fino, pero tarda más en calcularse.', zh: '每个格元的大小，单位为米。默认值 100 生成 100 米 x 100 米的网格；较小的值可得到更精细的地图，但计算耗时更长。' },
  'lcz_interp_eval_plus.tp_res': { en: 'How readings are averaged over time before modeling, such as by "hour" (default), "day", or "month".', pt: 'Como as leituras são calculadas na média ao longo do tempo antes de modelar, como por "hour" (padrão), "day", ou "month".', es: 'Cómo se promedian las lecturas en el tiempo antes de modelar, como por "hour" (por defecto), "day" o "month".', zh: '建模前对读数进行时间平均的方式，例如按“hour”（默认）、“day”或“month”。' },
  'lcz_interp_eval_plus.by': { en: 'Groups the evaluation by a time category — for example "season" to get separate accuracy scores for summer versus winter — instead of evaluating every timestamp individually.', pt: 'Agrupa a avaliação por uma categoria temporal — por exemplo "season" para obter pontuações de precisão separadas para verão e inverno — em vez de avaliar cada marca de tempo individualmente.', es: 'Agrupa la evaluación por una categoría temporal —por ejemplo "season" para obtener puntuaciones de precisión separadas para verano frente a invierno— en lugar de evaluar cada instante individualmente.', zh: '按时间类别（例如“season”，分别得到夏季与冬季各自的精度评分）对评估进行分组，而不是逐一评估每个时间戳。' },
  'lcz_interp_eval_plus.ucp_variables': { en: 'Which urban characterization parameters (like building height, sky view factor, or impervious surface fraction) to fetch and use as predictors alongside station data. Leave unset to use the model\'s default set.', pt: 'Quais parâmetros de caracterização urbana (como altura das edificações, fator de visão do céu, ou fração de superfície impermeável) buscar e usar como preditores junto com os dados de estação. Deixe em branco para usar o conjunto padrão do modelo.', es: 'Qué parámetros de caracterización urbana (como altura de edificios, factor de visión del cielo o fracción de superficie impermeable) obtener y usar como predictores junto con los datos de estación. Déjelo sin definir para usar el conjunto por defecto del modelo.', zh: '要获取并用作预测因子的城市特征参数（如建筑高度、天空可视因子或不透水面比例），与站点数据一同使用。留空则使用模型的默认参数集。' },
  'lcz_interp_eval_plus.n_estimators': { en: 'The number of decision trees the Random Forest builds; only applies when ml_model is "rf". The default of 200 is a reasonable balance — raising it (e.g. to 500) can slightly improve accuracy at the cost of speed.', pt: 'O número de árvores de decisão que o Random Forest constrói; aplica-se apenas quando ml_model é "rf". O padrão de 200 é um equilíbrio razoável — aumentá-lo (por exemplo, para 500) pode melhorar levemente a precisão ao custo de velocidade.', es: 'El número de árboles de decisión que construye el Random Forest; solo se aplica cuando ml_model es "rf". El valor por defecto de 200 es un equilibrio razonable; subirlo (por ejemplo a 500) puede mejorar ligeramente la precisión a costa de la velocidad.', zh: '随机森林构建的决策树数量；仅在 ml_model 为“rf”时适用。默认值 200 是一个合理的平衡点——提高该值（如提高到 500）可能略微提升精度，但会牺牲速度。' },
  'lcz_interp_eval_plus.process_ghsl': { en: 'Whether to download and use Global Human Settlement Layer data (built-up density and population) as a predictor. Leave on unless you want a faster run without that data source.', pt: 'Se deve baixar e usar dados do Global Human Settlement Layer (densidade construtiva e população) como preditor. Deixe ativado a menos que você queira uma execução mais rápida sem essa fonte de dados.', es: 'Si se descargan y usan o no como predictor datos del Global Human Settlement Layer (densidad construida y población). Déjelo activado salvo que quiera una ejecución más rápida sin esa fuente de datos.', zh: '是否下载并使用全球人类聚居层数据（建成密度和人口）作为预测因子。除非你想在不使用该数据源的情况下加快运行速度，否则保持开启。' },
  'lcz_interp_eval_plus.process_wumpod': { en: 'Whether to download and use World Urban Morphology data (building form and street pattern) as a predictor. Leave on unless you want a faster run without it.', pt: 'Se deve baixar e usar dados de morfologia urbana mundial (forma das edificações e padrão de ruas) como preditor. Deixe ativado a menos que queira uma execução mais rápida sem eles.', es: 'Si se descargan y usan o no como predictor datos de morfología urbana mundial (forma de los edificios y patrón de calles). Déjelo activado salvo que quiera una ejecución más rápida sin ellos.', zh: '是否下载并使用世界城市形态数据（建筑形态和街道模式）作为预测因子。除非你想加快运行速度而不使用它，否则保持开启。' },
  'lcz_interp_eval_plus.process_vegetation': { en: 'Whether to download and use vegetation/greenness data as a predictor. Leave on to capture the cooling effect of parks and tree cover.', pt: 'Se deve baixar e usar dados de vegetação/verdor como preditor. Deixe ativado para capturar o efeito de resfriamento de parques e cobertura arbórea.', es: 'Si se descargan y usan o no como predictor datos de vegetación/verdor. Déjelo activado para captar el efecto refrescante de los parques y la cobertura arbórea.', zh: '是否下载并使用植被/绿度数据作为预测因子。保持开启可捕捉公园和树冠覆盖带来的降温效应。' },
  'lcz_interp_eval_plus.process_directional': { en: 'Whether to compute direction-dependent urban form measures (e.g. street orientation relative to sun or wind). Off by default because it adds processing time; turn on only if directional effects matter for your study.', pt: 'Se deve calcular medidas de forma urbana dependentes de direção (por exemplo, orientação das ruas em relação ao sol ou ao vento). Desativado por padrão, pois adiciona tempo de processamento; ative apenas se efeitos direcionais importarem para o seu estudo.', es: 'Si se calculan o no medidas de forma urbana que dependen de la dirección (por ejemplo, la orientación de las calles respecto al sol o al viento). Desactivado por defecto porque añade tiempo de procesamiento; actívelo solo si los efectos direccionales importan para su estudio.', zh: '是否计算方向相关的城市形态指标（例如街道朝向相对于太阳或风向）。默认关闭，因为会增加处理时间；只有当方向性效应对你的研究很重要时才开启。' },
  'lcz_interp_eval_plus.isave': { en: 'Turn this on to save the accuracy results as a CSV file in the LCZ4r_output folder.', pt: 'Ative para salvar os resultados de precisão como um arquivo CSV na pasta LCZ4r_output.', es: 'Actívelo para guardar los resultados de precisión como archivo CSV en la carpeta LCZ4r_output.', zh: '开启此项可将精度结果以 CSV 文件形式保存到 LCZ4r_output 文件夹。' },
  'lcz_interp_eval_plus.n_jobs': { en: 'An advanced setting for how many CPU cores to use when downloading urban parameter data. The default of -1 uses all available cores automatically, so most users can leave this alone.', pt: 'Uma configuração avançada para quantos núcleos de CPU usar ao baixar dados de parâmetros urbanos. O padrão de -1 usa todos os núcleos disponíveis automaticamente, então a maioria dos usuários pode deixar como está.', es: 'Un ajuste avanzado para cuántos núcleos de CPU usar al descargar datos de parámetros urbanos. El valor por defecto de -1 usa automáticamente todos los núcleos disponibles, así que la mayoría de los usuarios puede dejarlo tal cual.', zh: '一项高级设置，控制下载城市参数数据时使用的 CPU 核心数。默认值 -1 会自动使用所有可用核心，因此大多数用户无需调整。' },
  'lcz_interp_eval_plus.year': { en: 'Restricts the evaluation to a specific year, such as 2023.', pt: 'Restringe a avaliação a um ano específico, como 2023.', es: 'Restringe la evaluación a un año concreto, como 2023.', zh: '将评估限定为特定年份，如 2023。' },
  'lcz_interp_eval_plus.month': { en: 'Restricts the evaluation to a specific month, such as 7 for July.', pt: 'Restringe a avaliação a um mês específico, como 7 para julho.', es: 'Restringe la evaluación a un mes concreto, como 7 para julio.', zh: '将评估限定为特定月份，如 7 表示 7 月。' },
  'lcz_interp_eval_plus.day': { en: 'Restricts the evaluation to a specific day of the month.', pt: 'Restringe a avaliação a um dia específico do mês.', es: 'Restringe la evaluación a un día concreto del mes.', zh: '将评估限定为月份中的特定日期。' },
  'lcz_interp_eval_plus.hour': { en: 'Restricts the evaluation to a specific hour of the day, such as 14 for 2pm.', pt: 'Restringe a avaliação a uma hora específica do dia, como 14 para as 14h.', es: 'Restringe la evaluación a una hora concreta del día, como 14 para las 2 p. m.', zh: '将评估限定为一天中的特定小时，如 14 表示下午 2 点。' },
  'lcz_interp_eval_plus.start': { en: 'The beginning of a custom date range to evaluate, such as "2023-06-01".', pt: 'O início de um intervalo de datas personalizado a avaliar, como "2023-06-01".', es: 'El inicio de un rango de fechas personalizado a evaluar, como "2023-06-01".', zh: '要评估的自定义日期范围起始点，如“2023-06-01”。' },
  'lcz_interp_eval_plus.end': { en: 'The end of a custom date range to evaluate, such as "2023-08-31".', pt: 'O fim de um intervalo de datas personalizado a avaliar, como "2023-08-31".', es: 'El fin de un rango de fechas personalizado a evaluar, como "2023-08-31".', zh: '要评估的自定义日期范围结束点，如“2023-08-31”。' },
  'lcz_interp_map.x': { en: 'The LCZ raster map for your study area. It defines the extent, resolution grid, and coordinate system of the output interpolation.', pt: 'O raster LCZ da sua área de estudo. Define a extensão, a grade de resolução e o sistema de coordenadas da interpolação de saída.', es: 'El mapa ráster LCZ de su área de estudio. Define la extensión, la cuadrícula de resolución y el sistema de coordenadas de la interpolación de salida.', zh: '你研究区的 LCZ 栅格地图。它定义了输出插值结果的范围、分辨率网格和坐标系统。' },
  'lcz_interp_map.data_frame': { en: 'Your table of station observations, with columns for date, station, variable, latitude, and longitude.', pt: 'Sua tabela de observações de estações, com colunas para data, estação, variável, latitude e longitude.', es: 'Su tabla de observaciones de estaciones, con columnas para fecha, estación, variable, latitud y longitud.', zh: '你的站点观测数据表，包含日期、站点、变量、纬度和经度列。' },
  'lcz_interp_map.var': { en: 'The name of the column that holds the variable to interpolate, such as "airT" for air temperature.', pt: 'O nome da coluna que contém a variável a interpolar, como "airT" para temperatura do ar.', es: 'El nombre de la columna que contiene la variable a interpolar, como "airT" para temperatura del aire.', zh: '保存要插值的变量的列名，例如“airT”表示气温。' },
  'lcz_interp_map.station_id': { en: 'The name of the column that identifies each station.', pt: 'O nome da coluna que identifica cada estação.', es: 'El nombre de la columna que identifica a cada estación.', zh: '标识每个站点的列名。' },
  'lcz_interp_map.sp_res': { en: 'The resolution of the output map, in meters per grid cell. The default of 100 produces a 100m x 100m grid; use a smaller number for a more detailed map, which takes longer to compute.', pt: 'A resolução do mapa de saída, em metros por célula de grade. O padrão de 100 produz uma grade de 100m x 100m; use um número menor para um mapa mais detalhado, que leva mais tempo para calcular.', es: 'La resolución del mapa de salida, en metros por celda de cuadrícula. El valor por defecto de 100 produce una cuadrícula de 100 m x 100 m; use un número menor para un mapa más detallado, lo que tarda más en calcularse.', zh: '输出地图的分辨率，以每格元所代表的米数计。默认值 100 生成 100 米 x 100 米的网格；数值越小地图越精细，但计算耗时也越长。' },
  'lcz_interp_map.tp_res': { en: 'How readings are averaged over time before interpolating, such as by "hour" (default), "day", or "month".', pt: 'Como as leituras são calculadas na média ao longo do tempo antes de interpolar, como por "hour" (padrão), "day", ou "month".', es: 'Cómo se promedian las lecturas en el tiempo antes de interpolar, como por "hour" (por defecto), "day" o "month".', zh: '插值前对读数进行时间平均的方式，例如按“hour”（默认）、“day”或“month”。' },
  'lcz_interp_map.by': { en: 'Groups all the timestamps within a category — such as "season", "month", or "weekday" versus "weekend" — and produces one averaged map per group instead of one map per individual timestamp. Leave unset to get one map layer for every timestamp in your data.', pt: 'Agrupa todas as marcas de tempo dentro de uma categoria — como "season", "month", ou "weekday" versus "weekend" — e produz um mapa médio por grupo em vez de um mapa por marca de tempo individual. Deixe em branco para obter uma camada de mapa para cada marca de tempo nos seus dados.', es: 'Agrupa todos los instantes temporales dentro de una categoría —como "season", "month" o "weekday" frente a "weekend"— y produce un mapa promediado por grupo en lugar de un mapa por cada instante individual. Déjelo sin definir para obtener una capa de mapa por cada instante de sus datos.', zh: '按类别（如“season”“month”，或“weekday”对“weekend”）对所有时间戳分组，为每组生成一张平均地图，而不是每个时间戳一张。留空则为数据中的每个时间戳生成一个地图图层。' },
  'lcz_interp_map.method': { en: 'The interpolation technique. "krige" (the default) uses kriging, which can factor in LCZ class as a covariate for more physically realistic results but requires enough stations to fit a variogram; "rbf" is a smooth spline-based method that works well with 10-200 stations and needs no variogram fitting; "idw" (inverse distance weighting) is the fastest and simplest option, weighting nearby stations more heavily, but ignores LCZ class entirely.', pt: 'A técnica de interpolação. "krige" (padrão) usa krigagem, que pode considerar a classe LCZ como covariável para resultados fisicamente mais realistas, mas exige estações suficientes para ajustar um variograma; "rbf" é um método suave baseado em splines que funciona bem com 10 a 200 estações e não precisa de ajuste de variograma; "idw" (ponderação pelo inverso da distância) é a opção mais rápida e simples, dando mais peso a estações próximas, mas ignora completamente a classe LCZ.', es: 'La técnica de interpolación. "krige" (por defecto) usa kriging, que puede incorporar la clase LCZ como covariable para resultados más realistas físicamente, pero requiere suficientes estaciones para ajustar un variograma; "rbf" es un método suave basado en splines que funciona bien con entre 10 y 200 estaciones y no necesita ajustar ningún variograma; "idw" (ponderación por distancia inversa) es la opción más rápida y sencilla, dando más peso a las estaciones cercanas, pero ignora por completo la clase LCZ.', zh: '插值技术。“krige”（默认）使用克里金法，可以将 LCZ 类别作为协变量以获得更符合实际的结果，但需要有足够的站点来拟合变异函数；“rbf”是一种基于样条的平滑方法，适用于 10-200 个站点，无需拟合变异函数；“idw”（反距离加权）是最快、最简单的方法，对邻近站点赋予更高权重，但完全忽略 LCZ 类别。' },
  'lcz_interp_map.vg_model': { en: 'Only used when method is "krige". The mathematical curve shape describing how similarity between stations fades with distance: "Sph" (spherical, the default), "Exp" (exponential), "Gau" (Gaussian), or "Ste" (Matern).', pt: 'Usado apenas quando method é "krige". O formato da curva matemática que descreve como a semelhança entre estações desaparece com a distância: "Sph" (esférico, padrão), "Exp" (exponencial), "Gau" (Gaussiano), ou "Ste" (Matérn).', es: 'Solo se usa cuando method es "krige". La forma matemática de la curva que describe cómo se desvanece con la distancia la similitud entre estaciones: "Sph" (esférico, por defecto), "Exp" (exponencial), "Gau" (gaussiano) o "Ste" (Matérn).', zh: '仅在 method 为“krige”时使用。描述站点间相似度随距离衰减规律的数学曲线形状：“Sph”（球状模型，默认）、“Exp”（指数模型）、“Gau”（高斯模型）或“Ste”（马特恩模型）。' },
  'lcz_interp_map.isave': { en: 'Turn this on to save the interpolated map as a GeoTIFF file in the LCZ4r_output folder.', pt: 'Ative para salvar o mapa interpolado como um arquivo GeoTIFF na pasta LCZ4r_output.', es: 'Actívelo para guardar el mapa interpolado como archivo GeoTIFF en la carpeta LCZ4r_output.', zh: '开启此项可将插值地图以 GeoTIFF 文件形式保存到 LCZ4r_output 文件夹。' },
  'lcz_interp_map.LCZinterp': { en: 'Only applies when method is "krige". When on (the default) and your data spans at least two different LCZ classes, the LCZ class of each location is used as an extra predictor, generally improving accuracy in cities with varied climate zones.', pt: 'Aplica-se apenas quando method é "krige". Quando ativado (padrão) e seus dados abrangem pelo menos duas classes LCZ diferentes, a classe LCZ de cada localização é usada como preditor extra, geralmente melhorando a precisão em cidades com zonas climáticas variadas.', es: 'Solo se aplica cuando method es "krige". Cuando está activado (por defecto) y sus datos abarcan al menos dos clases LCZ distintas, la clase LCZ de cada ubicación se usa como predictor adicional, mejorando generalmente la precisión en ciudades con zonas climáticas variadas.', zh: '仅在 method 为“krige”时适用。开启时（默认）且你的数据跨越至少两个不同的 LCZ 类别，每个位置的 LCZ 类别会被用作额外的预测因子，通常能提升气候区多样的城市中的精度。' },
  'lcz_interp_map.n_jobs': { en: 'An advanced setting controlling how many CPU cores are used for processing. The default of -1 automatically uses all available cores, so most users can leave this alone.', pt: 'Uma configuração avançada controlando quantos núcleos de CPU são usados no processamento. O padrão de -1 usa automaticamente todos os núcleos disponíveis, então a maioria dos usuários pode deixar como está.', es: 'Un ajuste avanzado que controla cuántos núcleos de CPU se usan para el procesamiento. El valor por defecto de -1 usa automáticamente todos los núcleos disponibles, así que la mayoría de los usuarios puede dejarlo tal cual.', zh: '一项高级设置，控制处理所用的 CPU 核心数。默认值 -1 会自动使用所有可用核心，因此大多数用户无需调整。' },
  'lcz_interp_map.year': { en: 'Restricts the interpolation to a specific year, such as 2023.', pt: 'Restringe a interpolação a um ano específico, como 2023.', es: 'Restringe la interpolación a un año concreto, como 2023.', zh: '将插值限定为特定年份，如 2023。' },
  'lcz_interp_map.month': { en: 'Restricts the interpolation to a specific month, such as 7 for July.', pt: 'Restringe a interpolação a um mês específico, como 7 para julho.', es: 'Restringe la interpolación a un mes concreto, como 7 para julio.', zh: '将插值限定为特定月份，如 7 表示 7 月。' },
  'lcz_interp_map.day': { en: 'Restricts the interpolation to a specific day of the month.', pt: 'Restringe a interpolação a um dia específico do mês.', es: 'Restringe la interpolación a un día concreto del mes.', zh: '将插值限定为月份中的特定日期。' },
  'lcz_interp_map.hour': { en: 'Restricts the interpolation to a specific hour of the day, such as 14 for 2pm, useful for mapping the daytime or nighttime heat pattern only.', pt: 'Restringe a interpolação a uma hora específica do dia, como 14 para as 14h, útil para mapear apenas o padrão de calor diurno ou noturno.', es: 'Restringe la interpolación a una hora concreta del día, como 14 para las 2 p. m., útil para mapear solo el patrón de calor diurno o nocturno.', zh: '将插值限定为一天中的特定小时，如 14 表示下午 2 点，适合只绘制白天或夜间的热量模式。' },
  'lcz_interp_map.start': { en: 'The beginning of a custom date range to interpolate, such as "2023-06-01".', pt: 'O início de um intervalo de datas personalizado a interpolar, como "2023-06-01".', es: 'El inicio de un rango de fechas personalizado a interpolar, como "2023-06-01".', zh: '要插值的自定义日期范围起始点，如“2023-06-01”。' },
  'lcz_interp_map.end': { en: 'The end of a custom date range to interpolate, such as "2023-08-31", paired with start to cover a full summer season.', pt: 'O fim de um intervalo de datas personalizado a interpolar, como "2023-08-31", combinado com start para cobrir uma estação de verão completa.', es: 'El fin de un rango de fechas personalizado a interpolar, como "2023-08-31", combinado con start para cubrir una temporada de verano completa.', zh: '要插值的自定义日期范围结束点，如“2023-08-31”，与 start 搭配可覆盖完整的夏季。' },
  'lcz_interp_map_plus.x': { en: 'The LCZ raster map for your study area. It defines the extent, resolution grid, and coordinate system of the output map.', pt: 'O raster LCZ da sua área de estudo. Define a extensão, a grade de resolução e o sistema de coordenadas do mapa de saída.', es: 'El mapa ráster LCZ de su área de estudio. Define la extensión, la cuadrícula de resolución y el sistema de coordenadas del mapa de salida.', zh: '你研究区的 LCZ 栅格地图。它定义了输出地图的范围、分辨率网格和坐标系统。' },
  'lcz_interp_map_plus.data_frame': { en: 'Your table of station observations, with columns for date, station, variable, latitude, and longitude.', pt: 'Sua tabela de observações de estações, com colunas para data, estação, variável, latitude e longitude.', es: 'Su tabla de observaciones de estaciones, con columnas para fecha, estación, variable, latitud y longitud.', zh: '你的站点观测数据表，包含日期、站点、变量、纬度和经度列。' },
  'lcz_interp_map_plus.var': { en: 'The name of the column that holds the variable to model, such as "airT" for air temperature.', pt: 'O nome da coluna que contém a variável a modelar, como "airT" para temperatura do ar.', es: 'El nombre de la columna que contiene la variable a modelar, como "airT" para temperatura del aire.', zh: '保存要建模的变量的列名，例如“airT”表示气温。' },
  'lcz_interp_map_plus.station_id': { en: 'The name of the column that identifies each station.', pt: 'O nome da coluna que identifica cada estação.', es: 'El nombre de la columna que identifica a cada estación.', zh: '标识每个站点的列名。' },
  'lcz_interp_map_plus.ml_model': { en: 'Which machine-learning model to use. "rf" (Random Forest, the default) handles non-linear relationships well, is robust to outliers, and reports how uncertain each prediction is; "ols" (a standard linear regression) is faster, easier to interpret, and reports multicollinearity diagnostics, but assumes simpler straight-line relationships.', pt: 'Qual modelo de aprendizado de máquina usar. "rf" (Random Forest, padrão) lida bem com relações não lineares, é robusto a valores discrepantes e informa o quão incerta é cada previsão; "ols" (uma regressão linear padrão) é mais rápido, mais fácil de interpretar e informa diagnósticos de multicolinearidade, mas assume relações mais simples e lineares.', es: 'Qué modelo de aprendizaje automático usar. "rf" (Random Forest, por defecto) maneja bien las relaciones no lineales, es robusto ante valores atípicos y reporta cuán incierta es cada predicción; "ols" (una regresión lineal estándar) es más rápido, más fácil de interpretar y reporta diagnósticos de multicolinealidad, pero asume relaciones más simples y lineales.', zh: '要使用的机器学习模型。“rf”（随机森林，默认）能很好地处理非线性关系，对离群值稳健，并会报告每次预测的不确定性；“ols”（标准线性回归）速度更快、更易解读，并报告多重共线性诊断，但假设关系更简单、呈直线关系。' },
  'lcz_interp_map_plus.sp_res': { en: 'The resolution of the output map, in meters per grid cell. The default of 100 gives a 100m x 100m grid; use a smaller number for a more detailed map.', pt: 'A resolução do mapa de saída, em metros por célula de grade. O padrão de 100 dá uma grade de 100m x 100m; use um número menor para um mapa mais detalhado.', es: 'La resolución del mapa de salida, en metros por celda de cuadrícula. El valor por defecto de 100 da una cuadrícula de 100 m x 100 m; use un número menor para un mapa más detallado.', zh: '输出地图的分辨率，以每格元所代表的米数计。默认值 100 生成 100 米 x 100 米的网格；数值越小地图越精细。' },
  'lcz_interp_map_plus.tp_res': { en: 'How readings are averaged over time before modeling, such as by "hour" (default), "day", or "month".', pt: 'Como as leituras são calculadas na média ao longo do tempo antes de modelar, como por "hour" (padrão), "day", ou "month".', es: 'Cómo se promedian las lecturas en el tiempo antes de modelar, como por "hour" (por defecto), "day" o "month".', zh: '建模前对读数进行时间平均的方式，例如按“hour”（默认）、“day”或“month”。' },
  'lcz_interp_map_plus.by': { en: 'Groups all the timestamps within a category — such as "season" or "month" — and produces one averaged map per group instead of per individual timestamp.', pt: 'Agrupa todas as marcas de tempo dentro de uma categoria — como "season" ou "month" — e produz um mapa médio por grupo em vez de por marca de tempo individual.', es: 'Agrupa todos los instantes temporales dentro de una categoría —como "season" o "month"— y produce un mapa promediado por grupo en lugar de por cada instante individual.', zh: '按类别（如“season”或“month”）对所有时间戳分组，为每组生成一张平均地图，而不是每个时间戳一张。' },
  'lcz_interp_map_plus.bbox': { en: 'A bounding box that limits the mapped area to a sub-region of the LCZ raster, given as (min longitude, min latitude, max longitude, max latitude) — useful for focusing on a neighborhood instead of an entire city, and for speeding up urban-data downloads.', pt: 'Uma caixa delimitadora que restringe a área mapeada a uma sub-região do raster LCZ, informada como (longitude mínima, latitude mínima, longitude máxima, latitude máxima) — útil para focar em um bairro em vez de uma cidade inteira, e para acelerar downloads de dados urbanos.', es: 'Un cuadro delimitador que limita el área mapeada a una subregión del ráster LCZ, indicado como (longitud mínima, latitud mínima, longitud máxima, latitud máxima); útil para centrarse en un barrio en lugar de en toda una ciudad, y para acelerar las descargas de datos urbanos.', zh: '将建图区域限定为 LCZ 栅格的一个子区域，以（最小经度、最小纬度、最大经度、最大纬度）形式给出——适合聚焦某个街区而非整座城市，也有助于加快城市数据的下载速度。' },
  'lcz_interp_map_plus.ucp_variables': { en: 'Which urban characterization parameters (like building height, sky view factor, or impervious surface fraction) to download and use as model predictors. Leave unset to use the tool\'s default set.', pt: 'Quais parâmetros de caracterização urbana (como altura das edificações, fator de visão do céu, ou fração de superfície impermeável) baixar e usar como preditores do modelo. Deixe em branco para usar o conjunto padrão da ferramenta.', es: 'Qué parámetros de caracterización urbana (como altura de edificios, factor de visión del cielo o fracción de superficie impermeable) descargar y usar como predictores del modelo. Déjelo sin definir para usar el conjunto por defecto de la herramienta.', zh: '要下载并用作模型预测因子的城市特征参数（如建筑高度、天空可视因子或不透水面比例）。留空则使用工具的默认参数集。' },
  'lcz_interp_map_plus.n_estimators': { en: 'The number of decision trees the Random Forest builds; only applies when ml_model is "rf". The default of 200 is a good balance between accuracy and speed.', pt: 'O número de árvores de decisão que o Random Forest constrói; aplica-se apenas quando ml_model é "rf". O padrão de 200 é um bom equilíbrio entre precisão e velocidade.', es: 'El número de árboles de decisión que construye el Random Forest; solo se aplica cuando ml_model es "rf". El valor por defecto de 200 es un buen equilibrio entre precisión y velocidad.', zh: '随机森林构建的决策树数量；仅在 ml_model 为“rf”时适用。默认值 200 在精度与速度之间取得了良好平衡。' },
  'lcz_interp_map_plus.min_samples': { en: 'The minimum number of valid stations required within a time group before a model is fit for that group. The default of 3 avoids fitting unreliable models on too little data; raise it if you want stricter quality control.', pt: 'O número mínimo de estações válidas exigido dentro de um grupo de tempo antes de um modelo ser ajustado para esse grupo. O padrão de 3 evita ajustar modelos pouco confiáveis com dados de menos; aumente se quiser um controle de qualidade mais rígido.', es: 'El número mínimo de estaciones válidas requeridas dentro de un grupo temporal antes de ajustar un modelo para ese grupo. El valor por defecto de 3 evita ajustar modelos poco fiables con muy pocos datos; súbalo si quiere un control de calidad más estricto.', zh: '在为某个时间分组拟合模型之前，该分组内所需的最少有效站点数。默认值 3 可避免在数据过少的情况下拟合出不可靠的模型；如需更严格的质量控制，可提高此值。' },
  'lcz_interp_map_plus.use_pca': { en: 'Turns on Principal Component Analysis to compress many correlated urban predictors (like several related building-density measures) into a smaller set of combined features before modeling. Useful when you\'ve included many urban parameters that overlap in what they measure.', pt: 'Ativa a Análise de Componentes Principais para comprimir muitos preditores urbanos correlacionados (como várias medidas relacionadas de densidade construtiva) em um conjunto menor de características combinadas antes de modelar. Útil quando você incluiu muitos parâmetros urbanos que se sobrepõem no que medem.', es: 'Activa el Análisis de Componentes Principales para comprimir muchos predictores urbanos correlacionados (como varias medidas relacionadas de densidad de edificación) en un conjunto más pequeño de rasgos combinados antes de modelar. Útil cuando ha incluido muchos parámetros urbanos que se solapan en lo que miden.', zh: '开启主成分分析，将多个高度相关的城市预测因子（如若干相关的建筑密度指标）压缩为更少的组合特征后再建模。当你纳入了许多在测量内容上有所重叠的城市参数时，此项很有用。' },
  'lcz_interp_map_plus.n_pca_components': { en: 'How many combined PCA features to keep, only used when use_pca is on. The default of 0 keeps all of them (equivalent to leaving PCA off); set a smaller number, like 5, to force a more compact feature set.', pt: 'Quantas características combinadas do PCA manter, usado apenas quando use_pca está ativado. O padrão de 0 mantém todas (equivalente a deixar o PCA desativado); defina um número menor, como 5, para forçar um conjunto de características mais compacto.', es: 'Cuántos rasgos combinados de PCA conservar, solo se usa cuando use_pca está activado. El valor por defecto de 0 los conserva todos (equivalente a dejar el PCA desactivado); fije un número menor, como 5, para forzar un conjunto de rasgos más compacto.', zh: '要保留的组合 PCA 特征数量，仅在 use_pca 开启时使用。默认值 0 表示保留全部（相当于关闭 PCA）；设置较小的值（如 5）可强制得到更紧凑的特征集。' },
  'lcz_interp_map_plus.process_ghsl': { en: 'Whether to download and use Global Human Settlement Layer data (built-up density and population) as a predictor. Leave on unless you want a faster run without that data source.', pt: 'Se deve baixar e usar dados do Global Human Settlement Layer (densidade construtiva e população) como preditor. Deixe ativado a menos que você queira uma execução mais rápida sem essa fonte de dados.', es: 'Si se descargan y usan o no como predictor datos del Global Human Settlement Layer (densidad construida y población). Déjelo activado salvo que quiera una ejecución más rápida sin esa fuente de datos.', zh: '是否下载并使用全球人类聚居层数据（建成密度和人口）作为预测因子。除非你想在不使用该数据源的情况下加快运行速度，否则保持开启。' },
  'lcz_interp_map_plus.process_wumpod': { en: 'Whether to download and use World Urban Morphology data (building form and street pattern) as a predictor. Leave on unless you want a faster run without it.', pt: 'Se deve baixar e usar dados de morfologia urbana mundial (forma das edificações e padrão de ruas) como preditor. Deixe ativado a menos que queira uma execução mais rápida sem eles.', es: 'Si se descargan y usan o no como predictor datos de morfología urbana mundial (forma de los edificios y patrón de calles). Déjelo activado salvo que quiera una ejecución más rápida sin ellos.', zh: '是否下载并使用世界城市形态数据（建筑形态和街道模式）作为预测因子。除非你想加快运行速度而不使用它，否则保持开启。' },
  'lcz_interp_map_plus.process_vegetation': { en: 'Whether to download and use vegetation/greenness data as a predictor, to capture the cooling effect of parks and tree cover.', pt: 'Se deve baixar e usar dados de vegetação/verdor como preditor, para capturar o efeito de resfriamento de parques e cobertura arbórea.', es: 'Si se descargan y usan o no como predictor datos de vegetación/verdor, para captar el efecto refrescante de los parques y la cobertura arbórea.', zh: '是否下载并使用植被/绿度数据作为预测因子，以捕捉公园和树冠覆盖带来的降温效应。' },
  'lcz_interp_map_plus.process_directional': { en: 'Whether to compute direction-dependent urban form measures, such as street orientation. Off by default because it adds processing time; turn on only if directional effects matter for your study.', pt: 'Se deve calcular medidas de forma urbana dependentes de direção, como orientação das ruas. Desativado por padrão, pois adiciona tempo de processamento; ative apenas se efeitos direcionais importarem para o seu estudo.', es: 'Si se calculan o no medidas de forma urbana que dependen de la dirección, como la orientación de las calles. Desactivado por defecto porque añade tiempo de procesamiento; actívelo solo si los efectos direccionales importan para su estudio.', zh: '是否计算方向相关的城市形态指标，例如街道朝向。默认关闭，因为会增加处理时间；只有当方向性效应对你的研究很重要时才开启。' },
  'lcz_interp_map_plus.use_lcz_params': { en: 'Turn this on to bring in standard LCZ morphological parameters (like typical building height or surface roughness for each zone) from a lookup table as additional model features, rather than relying only on downloaded urban data.', pt: 'Ative para trazer parâmetros morfológicos LCZ padrão (como altura típica das edificações ou rugosidade de superfície de cada zona) de uma tabela de referência como características adicionais do modelo, em vez de depender apenas de dados urbanos baixados.', es: 'Actívelo para incorporar los parámetros morfológicos LCZ estándar (como la altura típica de los edificios o la rugosidad de superficie de cada zona) desde una tabla de referencia como rasgos adicionales del modelo, en lugar de depender solo de los datos urbanos descargados.', zh: '开启此项可从查找表中引入标准的 LCZ 形态参数（如每个区域典型的建筑高度或地表粗糙度）作为额外的模型特征，而不仅仅依赖下载的城市数据。' },
  'lcz_interp_map_plus.isave': { en: 'Turn this on to save the output map as a GeoTIFF file in the LCZ4r_output folder.', pt: 'Ative para salvar o mapa de saída como um arquivo GeoTIFF na pasta LCZ4r_output.', es: 'Actívelo para guardar el mapa de salida como archivo GeoTIFF en la carpeta LCZ4r_output.', zh: '开启此项可将输出地图以 GeoTIFF 文件形式保存到 LCZ4r_output 文件夹。' },
  'lcz_interp_map_plus.n_jobs': { en: 'An advanced setting for how many CPU cores to use for processing. The default of -1 automatically uses all available cores, so most users can leave this alone.', pt: 'Uma configuração avançada para quantos núcleos de CPU usar no processamento. O padrão de -1 usa automaticamente todos os núcleos disponíveis, então a maioria dos usuários pode deixar como está.', es: 'Un ajuste avanzado para cuántos núcleos de CPU usar en el procesamiento. El valor por defecto de -1 usa automáticamente todos los núcleos disponibles, así que la mayoría de los usuarios puede dejarlo tal cual.', zh: '一项高级设置，控制处理所用的 CPU 核心数。默认值 -1 会自动使用所有可用核心，因此大多数用户无需调整。' },
  'lcz_interp_map_plus.year': { en: 'Restricts the model to a specific year, such as 2023.', pt: 'Restringe o modelo a um ano específico, como 2023.', es: 'Restringe el modelo a un año concreto, como 2023.', zh: '将模型限定为特定年份，如 2023。' },
  'lcz_interp_map_plus.month': { en: 'Restricts the model to a specific month, such as 7 for July.', pt: 'Restringe o modelo a um mês específico, como 7 para julho.', es: 'Restringe el modelo a un mes concreto, como 7 para julio.', zh: '将模型限定为特定月份，如 7 表示 7 月。' },
  'lcz_interp_map_plus.day': { en: 'Restricts the model to a specific day of the month.', pt: 'Restringe o modelo a um dia específico do mês.', es: 'Restringe el modelo a un día concreto del mes.', zh: '将模型限定为月份中的特定日期。' },
  'lcz_interp_map_plus.hour': { en: 'Restricts the model to a specific hour of the day, such as 14 for 2pm.', pt: 'Restringe o modelo a uma hora específica do dia, como 14 para as 14h.', es: 'Restringe el modelo a una hora concreta del día, como 14 para las 2 p. m.', zh: '将模型限定为一天中的特定小时，如 14 表示下午 2 点。' },
  'lcz_interp_map_plus.start': { en: 'The beginning of a custom date range to model, such as "2023-06-01".', pt: 'O início de um intervalo de datas personalizado a modelar, como "2023-06-01".', es: 'El inicio de un rango de fechas personalizado a modelar, como "2023-06-01".', zh: '要建模的自定义日期范围起始点，如“2023-06-01”。' },
  'lcz_interp_map_plus.end': { en: 'The end of a custom date range to model, such as "2023-08-31".', pt: 'O fim de um intervalo de datas personalizado a modelar, como "2023-08-31".', es: 'El fin de un rango de fechas personalizado a modelar, como "2023-08-31".', zh: '要建模的自定义日期范围结束点，如“2023-08-31”。' },
  'lcz_list_pc_assets.collection': { en: 'Which data product to inspect, given as a short collection name (like "sentinel-2-l2a") or a raw Planetary Computer collection identifier.', pt: 'Qual produto de dados inspecionar, informado como um nome curto de coleção (como "sentinel-2-l2a") ou um identificador bruto de coleção do Planetary Computer.', es: 'Qué producto de datos inspeccionar, indicado como un nombre corto de colección (como "sentinel-2-l2a") o un identificador de colección de Planetary Computer sin procesar.', zh: '要查询的数据产品，可以是简短的数据集名称（如“sentinel-2-l2a”），也可以是原始的 Planetary Computer 数据集标识符。' },
  'lcz_list_pc_assets.x': { en: 'An LCZ map file (GeoTIFF) used only to define the geographic area to check; its actual data values aren\'t used, just its location and extent.', pt: 'Um arquivo de mapa LCZ (GeoTIFF) usado apenas para definir a área geográfica a verificar; seus valores de dados reais não são usados, apenas sua localização e extensão.', es: 'Un archivo de mapa LCZ (GeoTIFF) usado solo para definir el área geográfica a comprobar; sus valores de datos reales no se usan, solo su ubicación y extensión.', zh: '仅用于定义要查询的地理区域的 LCZ 地图文件（GeoTIFF）；其实际数据数值不会被使用，只使用其位置和范围信息。' },
  'lcz_plot_interp.x': { en: 'The interpolated raster to plot — typically the GeoTIFF output from lcz_interp_map or lcz_interp_map_plus, or a raw grid of values shaped as rows and columns (with an optional extra dimension for multiple time steps or bands).', pt: 'O raster interpolado a plotar — tipicamente a saída GeoTIFF de lcz_interp_map ou lcz_interp_map_plus, ou uma grade bruta de valores organizada em linhas e colunas (com uma dimensão extra opcional para vários passos de tempo ou bandas).', es: 'El ráster interpolado a graficar, típicamente la salida GeoTIFF de lcz_interp_map o lcz_interp_map_plus, o una cuadrícula cruda de valores en filas y columnas (con una dimensión extra opcional para varios instantes temporales o bandas).', zh: '要绘制的插值栅格——通常是 lcz_interp_map 或 lcz_interp_map_plus 输出的 GeoTIFF，也可以是按行列排列的原始数值网格（可附带一个表示多个时间步或波段的额外维度）。' },
  'lcz_plot_interp.palette': { en: 'The color scheme used for the heatmap. The default, "muted", uses a diverging set of colors that reads well for showing values above and below a midpoint, such as warmer versus cooler temperatures.', pt: 'O esquema de cores usado para o mapa de calor. O padrão, "muted", usa um conjunto divergente de cores que funciona bem para mostrar valores acima e abaixo de um ponto médio, como temperaturas mais quentes versus mais frias.', es: 'El esquema de color usado para el mapa de calor. El valor por defecto, "muted", usa un conjunto divergente de colores que se lee bien para mostrar valores por encima y por debajo de un punto medio, como temperaturas más cálidas frente a más frescas.', zh: '热力图使用的配色方案。默认值“muted”使用一套发散型配色，能很好地展示高于和低于中间值的数值，例如较暖与较冷的温度。' },
  'lcz_plot_interp.direction': { en: 'Flips the color order. Leave at 1 for the normal palette order, or set to -1 to reverse it, for example to swap which end of the scale reads as "hot" versus "cold".', pt: 'Inverte a ordem das cores. Deixe em 1 para a ordem normal da paleta, ou defina como -1 para invertê-la, por exemplo para trocar qual extremo da escala representa "quente" versus "frio".', es: 'Invierte el orden del color. Déjelo en 1 para el orden normal de la paleta, o fíjelo en -1 para invertirlo, por ejemplo para intercambiar qué extremo de la escala se lee como "caliente" frente a "frío".', zh: '翻转配色顺序。保持默认值 1 使用正常的配色顺序，或设为 -1 反转顺序，例如交换色阶两端所代表的“热”与“冷”。' },
  'lcz_plot_interp.isave': { en: 'Turn this on to save the figure to the LCZ4r_output folder instead of only viewing it interactively.', pt: 'Ative para salvar a figura na pasta LCZ4r_output em vez de apenas visualizá-la interativamente.', es: 'Actívelo para guardar la figura en la carpeta LCZ4r_output en lugar de solo verla de forma interactiva.', zh: '开启此项可将图像保存到 LCZ4r_output 文件夹，而不仅仅是交互式查看。' },
  'lcz_plot_interp.save_extension': { en: 'The file format to save in, when isave is on. Choose "html" (the default) for an interactive figure others can explore in a browser, or "png"/"pdf" for a static image suitable for printing or pasting into a document.', pt: 'O formato de arquivo para salvar, quando isave está ativado. Escolha "html" (padrão) para uma figura interativa que outros podem explorar no navegador, ou "png"/"pdf" para uma imagem estática adequada para impressão ou inserção em um documento.', es: 'El formato de archivo en que guardar, cuando isave está activado. Elija "html" (por defecto) para una figura interactiva que otros puedan explorar en un navegador, o "png"/"pdf" para una imagen estática apta para imprimir o pegar en un documento.', zh: 'isave 开启时使用的文件保存格式。选择“html”（默认）生成他人可在浏览器中探索的交互式图像，或选择“png”/“pdf”生成适合打印或粘贴到文档中的静态图片。' },
  'lcz_plot_interp.title': { en: 'Custom text to use as the figure\'s title, replacing the automatically generated default — for example, "Summer Afternoon Heat Map, Sao Paulo".', pt: 'Texto personalizado a usar como título da figura, substituindo o padrão gerado automaticamente — por exemplo, "Mapa de Calor de Tarde de Verão, São Paulo".', es: 'Texto personalizado para usar como título de la figura, en lugar del generado automáticamente por defecto, por ejemplo "Mapa de Calor de la Tarde de Verano, São Paulo".', zh: '用作图像标题的自定义文字，替换自动生成的默认标题——例如“夏季午后热力地图，圣保罗”。' },
  'lcz_plot_interp.caption': { en: 'A short note added below the figure, useful for citing the data source or adding a methodology reminder, such as "Interpolated from 30 stations, June-August 2023".', pt: 'Uma nota curta adicionada abaixo da figura, útil para citar a fonte dos dados ou adicionar um lembrete metodológico, como "Interpolado a partir de 30 estações, junho-agosto de 2023".', es: 'Una nota breve añadida debajo de la figura, útil para citar la fuente de datos o añadir un recordatorio de la metodología, como "Interpolado a partir de 30 estaciones, junio-agosto de 2023".', zh: '图像下方添加的简短说明，适合注明数据来源或补充方法提示，例如“基于 30 个站点插值，2023 年 6-8 月”。' },
  'lcz_plot_map.x': { en: 'The map to plot: either an LCZ classification raster (with class codes 1-17) or a continuous raster like a land surface temperature file produced by the Get LST tool. This is required.', pt: 'O mapa a plotar: um raster de classificação LCZ (com códigos de classe 1-17) ou um raster contínuo, como um arquivo de temperatura de superfície produzido pela ferramenta Obter LST. É obrigatório.', es: 'El mapa a graficar: ya sea un ráster de clasificación LCZ (con códigos de clase 1-17) o un ráster continuo como un archivo de temperatura de superficie producido por la herramienta Obtener LST. Es obligatorio.', zh: '要绘制的地图：可以是 LCZ 分类栅格（类别代码 1-17），也可以是连续型栅格，如“获取 LST”工具生成的地表温度文件。此项为必填。' },
  'lcz_plot_map.isave': { en: 'When turned on, saves the resulting figure to a file on your computer instead of only showing it on screen.', pt: 'Quando ativado, salva a figura resultante em um arquivo no seu computador, em vez de apenas mostrá-la em tela.', es: 'Al activarlo, guarda la figura resultante en un archivo en su computadora en lugar de solo mostrarla en pantalla.', zh: '开启后会将生成的图像保存到电脑上的文件，而不仅仅是在屏幕上显示。' },
  'lcz_plot_map.save_extension': { en: 'The file format for the saved figure: "html" keeps it interactive (zoomable/pannable) when reopened, while "png" or "pdf" produce a static image suitable for reports or presentations.', pt: 'O formato de arquivo para a figura salva: "html" a mantém interativa (com zoom e movimento) ao reabrir, enquanto "png" ou "pdf" produzem uma imagem estática adequada para relatórios ou apresentações.', es: 'El formato de archivo para la figura guardada: "html" la mantiene interactiva (con zoom/desplazamiento) al reabrirla, mientras que "png" o "pdf" producen una imagen estática apta para informes o presentaciones.', zh: '保存图像所用的文件格式：“html”在重新打开时保持交互性（可缩放/平移），“png”或“pdf”生成适合报告或演示的静态图片。' },
  'lcz_plot_map.show_legend': { en: 'When turned on (the default), shows the LCZ class legend (names and colors for each of the 17 classes) alongside the map. This is ignored for continuous data like temperature, which shows a colorbar instead.', pt: 'Quando ativado (padrão), mostra a legenda de classes LCZ (nomes e cores para cada uma das 17 classes) ao lado do mapa. É ignorado para dados contínuos, como temperatura, que mostram uma barra de cores em vez disso.', es: 'Cuando está activado (por defecto), muestra la leyenda de clases LCZ (nombres y colores de las 17 clases) junto al mapa. Se ignora para datos continuos como la temperatura, que muestran en su lugar una barra de color.', zh: '开启时（默认），会在地图旁显示 LCZ 类别图例（17 个类别各自的名称和颜色）。对于气温等连续型数据此项会被忽略，改为显示色阶条。' },
  'lcz_plot_map.inclusive': { en: 'When turned on, uses a colorblind-friendly version of the LCZ color palette instead of the standard WUDAPT colors. Turn this on if you or your audience have difficulty distinguishing the default palette\'s colors. Ignored for continuous data.', pt: 'Quando ativado, usa uma versão adequada para daltônicos da paleta de cores LCZ, em vez das cores WUDAPT padrão. Ative se você ou seu público tiverem dificuldade em distinguir as cores da paleta padrão. Ignorado para dados contínuos.', es: 'Al activarlo, usa una versión apta para daltónicos de la paleta de colores LCZ en lugar de los colores estándar de WUDAPT. Actívelo si usted o su audiencia tienen dificultad para distinguir los colores de la paleta estándar. Se ignora para datos continuos.', zh: '开启后使用色盲友好版的 LCZ 配色方案，而不是标准的 WUDAPT 配色。如果你或你的受众难以区分默认配色，请开启此项。对连续型数据此项会被忽略。' },
  'lcz_plot_map.use_webgl': { en: 'When turned on (the default), uses your graphics card to render large maps smoothly. Leave this on unless you run into display issues with big maps; ignored for continuous data.', pt: 'Quando ativado (padrão), usa a placa gráfica para renderizar mapas grandes de forma suave. Deixe ativado a menos que você tenha problemas de exibição com mapas grandes; ignorado para dados contínuos.', es: 'Cuando está activado (por defecto), usa su tarjeta gráfica para renderizar mapas grandes con fluidez. Déjelo activado salvo que tenga problemas de visualización con mapas grandes; se ignora para datos continuos.', zh: '开启时（默认），会使用你的显卡来平滑渲染大型地图。除非在渲染大型地图时遇到显示问题，否则保持开启；对连续型数据此项会被忽略。' },
  'lcz_plot_map.use_geoarrow': { en: 'An internal setting that speeds up rendering of the map\'s polygon shapes using a faster data format. Most users can leave this at its default; ignored for continuous data.', pt: 'Uma configuração interna que acelera a renderização dos polígonos do mapa usando um formato de dados mais rápido. A maioria dos usuários pode deixar no padrão; ignorado para dados contínuos.', es: 'Un ajuste interno que acelera el renderizado de los polígonos del mapa usando un formato de datos más rápido. La mayoría de los usuarios puede dejarlo en su valor por defecto; se ignora para datos continuos.', zh: '一项内部设置，使用更快的数据格式加速渲染地图的多边形形状。大多数用户可保持默认设置；对连续型数据此项会被忽略。' },
  'lcz_plot_map.use_duckdb': { en: 'An internal setting that uses the DuckDB database engine to quickly compute the map legend. Most users can leave this at its default; ignored for continuous data.', pt: 'Uma configuração interna que usa o mecanismo de banco de dados DuckDB para calcular rapidamente a legenda do mapa. A maioria dos usuários pode deixar no padrão; ignorado para dados contínuos.', es: 'Un ajuste interno que usa el motor de base de datos DuckDB para calcular rápidamente la leyenda del mapa. La mayoría de los usuarios puede dejarlo en su valor por defecto; se ignora para datos continuos.', zh: '一项内部设置，使用 DuckDB 数据库引擎快速计算地图图例。大多数用户可保持默认设置；对连续型数据此项会被忽略。' },
  'lcz_plot_map.title': { en: 'An optional title text shown at the top of the figure, e.g. "Land Surface Temperature - Natal, June 2026".', pt: 'Um texto de título opcional exibido no topo da figura, por exemplo "Temperatura de Superfície - Natal, junho de 2026".', es: 'Un texto de título opcional mostrado en la parte superior de la figura, por ejemplo "Temperatura de Superficie - Natal, junio de 2026".', zh: '显示在图像顶部的可选标题文字，例如“地表温度 - 纳塔尔，2026 年 6 月”。' },
  'lcz_plot_map.subtitle': { en: 'An optional line of text shown below the title, for extra context such as a date range or data source.', pt: 'Uma linha opcional de texto exibida abaixo do título, para contexto adicional como um intervalo de datas ou fonte de dados.', es: 'Una línea de texto opcional mostrada debajo del título, para contexto adicional como un rango de fechas o una fuente de datos.', zh: '显示在标题下方的可选文字，用于补充日期范围或数据来源等背景信息。' },
  'lcz_plot_map.caption': { en: 'An optional line of text shown at the bottom of the figure, often used for crediting a data source or adding a short note.', pt: 'Uma linha opcional de texto exibida na parte inferior da figura, geralmente usada para creditar uma fonte de dados ou adicionar uma nota curta.', es: 'Una línea de texto opcional mostrada en la parte inferior de la figura, usada a menudo para citar una fuente de datos o añadir una nota breve.', zh: '显示在图像底部的可选文字，常用于注明数据来源或添加简短说明。' },
  'lcz_plot_map.max_pixels': { en: 'The maximum number of pixels to render before the map is automatically down-sampled (shrunk) for display, so very large rasters still plot quickly. The default (10,000,000 pixels) works well for most maps; lower it if plotting feels slow, or raise it if you need to see very fine detail.', pt: 'O número máximo de pixels a renderizar antes de o mapa ser reduzido automaticamente (encolhido) para exibição, de forma que rasters muito grandes ainda sejam plotados rapidamente. O padrão (10.000.000 de pixels) funciona bem para a maioria dos mapas; reduza se a plotagem parecer lenta, ou aumente se precisar ver detalhes muito finos.', es: 'El número máximo de píxeles a renderizar antes de que el mapa se reduzca automáticamente para su visualización, de modo que rásteres muy grandes se sigan graficando con rapidez. El valor por defecto (10.000.000 de píxeles) funciona bien para la mayoría de los mapas; redúzcalo si el graficado se siente lento, o auméntelo si necesita ver mucho detalle fino.', zh: '在地图自动降采样（缩小）以便显示之前允许渲染的最大像素数，从而让超大栅格也能快速绘制。默认值（10,000,000 像素）适用于大多数地图；如果绘图感觉迟缓可调低，如需查看非常精细的细节可调高。' },
  'lcz_plot_map.renderer': { en: 'Which plotting engine to use: "plotly" (the default) gives an interactive chart-style figure, while "maplibre" overlays the map on a real OpenStreetMap street/satellite basemap for geographic context. Note that continuous data (like temperature) only supports the "plotly" option.', pt: 'Qual motor de plotagem usar: "plotly" (padrão) dá uma figura interativa no estilo de gráfico, enquanto "maplibre" sobrepõe o mapa a um mapa-base real de ruas/satélite do OpenStreetMap para contexto geográfico. Observe que dados contínuos (como temperatura) só suportam a opção "plotly".', es: 'Qué motor de graficado usar: "plotly" (por defecto) da una figura interactiva de estilo gráfico, mientras que "maplibre" superpone el mapa sobre un mapa base real de calles/satélite de OpenStreetMap para dar contexto geográfico. Tenga en cuenta que los datos continuos (como la temperatura) solo admiten la opción "plotly".', zh: '使用哪种绘图引擎：“plotly”（默认）生成交互式图表样式的图像，而“maplibre”会将地图叠加在真实的 OpenStreetMap 街道/卫星底图上以提供地理背景。注意连续型数据（如气温）只支持“plotly”选项。' },
  'lcz_plot_map.opacity': { en: 'How see-through the map overlay is when using the "maplibre" renderer, from 0 (fully transparent) to 1 (fully solid); the default of 0.8 lets some of the basemap streets show through underneath.', pt: 'Quão transparente é a sobreposição do mapa ao usar o renderizador "maplibre", de 0 (totalmente transparente) a 1 (totalmente sólido); o padrão de 0,8 deixa algumas ruas do mapa-base aparecerem por baixo.', es: 'Cuán transparente es la capa del mapa al usar el renderizador "maplibre", de 0 (totalmente transparente) a 1 (totalmente sólida); el valor por defecto de 0,8 deja ver algo de las calles del mapa base debajo.', zh: '使用“maplibre”渲染引擎时地图叠加层的透明程度，从 0（完全透明）到 1（完全不透明）；默认值 0.8 会让底图街道略微透出。' },
  'lcz_plot_map.data_type': { en: 'Tells the tool whether the input is an LCZ class map or continuous data like temperature. The default, "auto", detects this automatically from the file; only set it manually if auto-detection picks the wrong type for your data.', pt: 'Informa à ferramenta se a entrada é um mapa de classes LCZ ou dados contínuos, como temperatura. O padrão, "auto", detecta isso automaticamente a partir do arquivo; defina manualmente apenas se a detecção automática escolher o tipo errado para seus dados.', es: 'Indica a la herramienta si la entrada es un mapa de clases LCZ o datos continuos como la temperatura. El valor por defecto, "auto", lo detecta automáticamente a partir del archivo; fíjelo manualmente solo si la detección automática elige el tipo equivocado para sus datos.', zh: '告知工具输入的是 LCZ 类别地图还是气温等连续型数据。默认值“auto”会根据文件自动检测；只有在自动检测判断错误时才需要手动设置。' },
  'lcz_plot_map.band': { en: 'For multi-band continuous rasters (such as an LST file with one temperature layer per date), which layer to plot: for example, enter the date "2026-06-01" to plot that day\'s data, or leave it empty to plot the first available layer. Not used for LCZ class maps.', pt: 'Para rasters contínuos multibanda (como um arquivo LST com uma camada de temperatura por data), qual camada plotar: por exemplo, informe a data "2026-06-01" para plotar os dados daquele dia, ou deixe em branco para plotar a primeira camada disponível. Não usado para mapas de classe LCZ.', es: 'Para rásteres continuos multibanda (como un archivo LST con una capa de temperatura por fecha), qué capa graficar: por ejemplo, escriba la fecha "2026-06-01" para graficar los datos de ese día, o déjelo vacío para graficar la primera capa disponible. No se usa para mapas de clases LCZ.', zh: '对于多波段连续型栅格（如每个日期一个温度图层的 LST 文件），要绘制哪一层：例如输入日期“2026-06-01”绘制该日数据，或留空绘制第一个可用图层。不适用于 LCZ 类别地图。' },
  'lcz_plot_map.colorscale': { en: 'The color gradient used to shade continuous data such as temperature. The default, "RdBu_r", shows cold areas in blue and hot areas in red; change it if you prefer a different color scheme for your figure.', pt: 'O gradiente de cores usado para colorir dados contínuos, como temperatura. O padrão, "RdBu_r", mostra áreas frias em azul e quentes em vermelho; altere se preferir outro esquema de cores para sua figura.', es: 'El degradado de color usado para sombrear los datos continuos como la temperatura. El valor por defecto, "RdBu_r", muestra las áreas frías en azul y las cálidas en rojo; cámbielo si prefiere otro esquema de colores para su figura.', zh: '用于给连续型数据（如气温）着色的色阶。默认值“RdBu_r”将寒冷区域显示为蓝色、炎热区域显示为红色；如果你偏好不同的配色方案，可以更改此项。' },
  'lcz_plot_parameters.x': { en: 'The parameter data to plot. This can be a file path to a parameter raster (like the output of lcz_get_parameters), or the result returned directly by lcz_get_ucp when it processes a whole map area.', pt: 'Os dados de parâmetros a plotar. Pode ser o caminho de um arquivo raster de parâmetro (como a saída de lcz_get_parameters), ou o resultado retornado diretamente por lcz_get_ucp quando processa uma área de mapa inteira.', es: 'Los datos de parámetros a graficar. Puede ser la ruta a un archivo ráster de parámetros (como la salida de lcz_get_parameters), o el resultado devuelto directamente por lcz_get_ucp cuando procesa toda un área de mapa.', zh: '要绘制的参数数据。可以是参数栅格文件的路径（如 lcz_get_parameters 的输出），也可以是 lcz_get_ucp 处理整个地图区域后直接返回的结果。' },
  'lcz_plot_parameters.iselect': { en: 'The name(s) of the specific parameter(s) to plot, e.g. "NDVI" or "Sky View Factor". Leave unset to use sensible defaults, or to restrict which parameters feed a non-map chart.', pt: 'O(s) nome(s) do(s) parâmetro(s) específico(s) a plotar, por exemplo "NDVI" ou "Fator de Visão do Céu". Deixe em branco para usar padrões sensatos, ou para restringir quais parâmetros alimentam um gráfico que não seja de mapa.', es: 'El nombre o nombres de los parámetros concretos a graficar, por ejemplo "NDVI" o "Factor de Visión del Cielo". Déjelo sin definir para usar valores por defecto razonables, o para restringir qué parámetros alimentan un gráfico que no sea de tipo mapa.', zh: '要绘制的具体参数名称，例如“NDVI”或“天空可视因子”。留空则使用合理的默认值，或用于限定参与非地图图表的参数。' },
  'lcz_plot_parameters.all_params': { en: 'Turn this on to plot every available parameter at once instead of picking specific ones. Only applies to the default map view.', pt: 'Ative para plotar todos os parâmetros disponíveis de uma vez, em vez de escolher parâmetros específicos. Aplica-se apenas à visualização padrão em mapa.', es: 'Actívelo para graficar todos los parámetros disponibles a la vez en lugar de elegir unos concretos. Solo se aplica a la vista de mapa por defecto.', zh: '开启后会一次性绘制所有可用参数，而不是挑选特定的几个。仅适用于默认的地图视图。' },
  'lcz_plot_parameters.has_class_band': { en: 'Tells the function whether the first layer of the data is an LCZ-class layer that should be skipped when plotting all parameters. Leave this on the default (True) for output from lcz_get_parameters; turn it off for data that has no class layer, such as output from lcz_get_indices.', pt: 'Informa à função se a primeira camada dos dados é uma camada de classe LCZ que deve ser ignorada ao plotar todos os parâmetros. Deixe no padrão (True) para saídas de lcz_get_parameters; desative para dados sem camada de classe, como a saída de lcz_get_indices.', es: 'Indica a la función si la primera capa de los datos es una capa de clase LCZ que debe omitirse al graficar todos los parámetros. Déjelo en su valor por defecto (True) para la salida de lcz_get_parameters; desactívelo para datos sin capa de clase, como la salida de lcz_get_indices.', zh: '告知函数数据的第一层是否为需要在绘制全部参数时跳过的 LCZ 类别图层。对于 lcz_get_parameters 的输出，保持默认开启（True）；对于没有类别图层的数据（如 lcz_get_indices 的输出），请关闭此项。' },
  'lcz_plot_parameters.chart_type': { en: 'The kind of chart to draw: "map" (default) for a spatial heatmap, "scatter" to compare two parameters point-by-point, "radar" to compare LCZ classes across several parameters on a polar chart, or "correlation" to see how strongly parameters relate to one another.', pt: 'O tipo de gráfico a desenhar: "map" (padrão) para um mapa de calor espacial, "scatter" para comparar dois parâmetros ponto a ponto, "radar" para comparar classes LCZ em vários parâmetros num gráfico polar, ou "correlation" para ver o quanto os parâmetros se relacionam entre si.', es: 'El tipo de gráfico a dibujar: "map" (por defecto) para un mapa de calor espacial, "scatter" para comparar dos parámetros punto por punto, "radar" para comparar clases LCZ en varios parámetros sobre un gráfico polar, o "correlation" para ver cuán estrechamente se relacionan los parámetros entre sí.', zh: '要绘制的图表类型：“map”（默认）为空间热力图，“scatter”逐点比较两个参数，“radar”在极坐标图上跨多个参数比较 LCZ 类别，“correlation”查看参数之间的相关强度。' },
  'lcz_plot_parameters.lcz_map': { en: 'The path to the LCZ classification map (classes 1-17) matching the same grid as your data. Required for every chart type except "map".', pt: 'O caminho do mapa de classificação LCZ (classes 1 a 17) alinhado à mesma grade dos seus dados. Obrigatório para todo tipo de gráfico exceto "map".', es: 'La ruta al mapa de clasificación LCZ (clases 1-17) que coincide con la misma cuadrícula que sus datos. Obligatorio para cualquier tipo de gráfico excepto "map".', zh: '与你的数据网格一致的 LCZ 分类地图路径（类别 1-17）。除“map”外的所有图表类型都需要提供此项。' },
  'lcz_plot_parameters.index_x': { en: 'The parameter to plot on the horizontal axis of a scatter chart. Required when chart_type is "scatter".', pt: 'O parâmetro a ser plotado no eixo horizontal de um gráfico de dispersão. Obrigatório quando chart_type é "scatter".', es: 'El parámetro a representar en el eje horizontal de un gráfico de dispersión. Obligatorio cuando chart_type es "scatter".', zh: '散点图水平轴上绘制的参数。chart_type 为“scatter”时必填。' },
  'lcz_plot_parameters.index_y': { en: 'The parameter to plot on the vertical axis of a scatter chart. Required when chart_type is "scatter".', pt: 'O parâmetro a ser plotado no eixo vertical de um gráfico de dispersão. Obrigatório quando chart_type é "scatter".', es: 'El parámetro a representar en el eje vertical de un gráfico de dispersión. Obligatorio cuando chart_type es "scatter".', zh: '散点图垂直轴上绘制的参数。chart_type 为“scatter”时必填。' },
  'lcz_plot_parameters.size_by': { en: 'An optional third parameter that controls how large each point is drawn in a scatter chart, letting you visualize three variables at once.', pt: 'Um terceiro parâmetro opcional que controla o tamanho de cada ponto no gráfico de dispersão, permitindo visualizar três variáveis ao mesmo tempo.', es: 'Un tercer parámetro opcional que controla el tamaño con que se dibuja cada punto en un gráfico de dispersión, permitiendo visualizar tres variables a la vez.', zh: '可选的第三个参数，用于控制散点图中每个点的绘制大小，让你可以同时可视化三个变量。' },
  'lcz_plot_parameters.lcz_classes': { en: 'Limits a radar chart to specific LCZ classes, e.g. [2, 6, 8] to compare only Compact Midrise, Open Lowrise, and Large Lowrise.', pt: 'Restringe um gráfico radar a classes LCZ específicas, por exemplo [2, 6, 8] para comparar apenas Compacta de Média Altura, Aberta de Baixa Altura e Aberta de Grande Altura.', es: 'Limita un gráfico de radar a clases LCZ concretas, por ejemplo [2, 6, 8] para comparar solo Media altura compacta, Baja altura abierta y Baja altura grande.', zh: '将雷达图限定为特定的 LCZ 类别，例如 [2, 6, 8] 只比较紧凑中层、开敞低层和大型低层。' },
  'lcz_plot_parameters.normalize_radar': { en: 'When on (the default), each parameter\'s axis on the radar chart is rescaled to a common 0-1 range so that parameters with very different natural scales, like temperature versus a percentage, remain visually comparable.', pt: 'Quando ativado (padrão), o eixo de cada parâmetro no gráfico radar é reescalado para uma faixa comum de 0 a 1, para que parâmetros com escalas naturais muito diferentes, como temperatura versus porcentagem, permaneçam comparáveis visualmente.', es: 'Cuando está activado (opción por defecto), el eje de cada parámetro en el gráfico de radar se reescala a un rango común de 0 a 1, para que parámetros con escalas naturales muy distintas, como una temperatura frente a un porcentaje, sigan siendo comparables visualmente.', zh: '开启时（默认），雷达图上每个参数的坐标轴都会被重新缩放到统一的 0-1 区间，使自然量纲差异很大的参数（例如温度与百分比）在视觉上仍可比较。' },
  'lcz_plot_parameters.inclusive': { en: 'Turn this on to use a colorblind-friendly color palette instead of the standard one.', pt: 'Ative para usar uma paleta de cores adequada para daltônicos em vez da paleta padrão.', es: 'Actívelo para usar una paleta de colores apta para daltónicos en lugar de la estándar.', zh: '开启后使用色盲友好的配色方案，而不是标准配色。' },
  'lcz_plot_parameters.isave': { en: 'Turn this on to save the rendered chart to a file instead of only displaying it.', pt: 'Ative para salvar o gráfico gerado em um arquivo em vez de apenas exibi-lo.', es: 'Actívelo para guardar el gráfico generado en un archivo en lugar de solo mostrarlo.', zh: '开启后会将渲染出的图表保存为文件，而不仅仅是显示出来。' },
  'lcz_plot_parameters.save_extension': { en: 'The file format to save the chart in when isave is on: "html" for an interactive file you can open in a browser, or "png"/"pdf" for a static image.', pt: 'O formato de arquivo para salvar o gráfico quando isave está ativado: "html" para um arquivo interativo a abrir no navegador, ou "png"/"pdf" para uma imagem estática.', es: 'El formato de archivo en que se guarda el gráfico cuando isave está activado: "html" para un archivo interactivo que se puede abrir en un navegador, o "png"/"pdf" para una imagen estática.', zh: 'isave 开启时保存图表所用的文件格式：“html”生成可在浏览器中打开的交互式文件，“png”/“pdf”生成静态图片。' },
  'lcz_plot_parameters.max_pixels': { en: 'The maximum number of pixels to render before the map is automatically down-sampled for speed. The default (10,000,000) works well for most rasters; only lower it if large maps are rendering too slowly.', pt: 'O número máximo de pixels a renderizar antes de o mapa ser reduzido automaticamente para ganhar velocidade. O padrão (10.000.000) funciona bem para a maioria dos rasters; reduza apenas se mapas grandes estiverem sendo renderizados devagar demais.', es: 'El número máximo de píxeles a renderizar antes de que el mapa se reduzca automáticamente para ganar velocidad. El valor por defecto (10.000.000) funciona bien para la mayoría de los rásteres; redúzcalo solo si mapas grandes se renderizan demasiado lento.', zh: '在地图自动降采样以提升速度之前，允许渲染的最大像素数。默认值（10,000,000）适用于大多数栅格；仅当大型地图渲染过慢时才需要调低。' },
  'lcz_plot_parameters.use_datashader': { en: 'Turn this on (the default) to use the Datashader library for rendering very large rasters smoothly instead of freezing or crashing the chart.', pt: 'Ative (padrão) para usar a biblioteca Datashader e renderizar rasters muito grandes de forma suave, em vez de travar ou congelar o gráfico.', es: 'Actívelo (opción por defecto) para usar la biblioteca Datashader al renderizar rásteres muy grandes con fluidez, en lugar de que el gráfico se congele o falle.', zh: '开启此项（默认）后，会使用 Datashader 库平滑渲染超大栅格，避免图表卡死或崩溃。' },
  'lcz_plot_parameters.title': { en: 'An optional custom title to display above the chart.', pt: 'Um título personalizado opcional a exibir acima do gráfico.', es: 'Un título personalizado opcional para mostrar encima del gráfico.', zh: '显示在图表上方的可选自定义标题。' },
  'lcz_plot_parameters.subtitle': { en: 'An optional line of secondary text to display just below the title.', pt: 'Uma linha opcional de texto secundário a exibir logo abaixo do título.', es: 'Una línea opcional de texto secundario para mostrar justo debajo del título.', zh: '显示在标题正下方的可选副标题文字。' },
  'lcz_plot_parameters.caption': { en: 'Optional small print text to display below the chart, useful for data source notes or units.', pt: 'Um texto opcional em corpo pequeno a exibir abaixo do gráfico, útil para notas sobre a fonte dos dados ou unidades.', es: 'Texto opcional de letra pequeña para mostrar debajo del gráfico, útil para notas sobre la fuente de datos o las unidades.', zh: '显示在图表下方的可选小字说明，适合注明数据来源或单位。' },
  'lcz_plot_parameters.renderer': { en: 'Which drawing engine produces the map: "plotly" for standard interactive plotting, "datashader" for large-raster rendering, or "auto" (default) to let the function pick automatically based on data size.', pt: 'Qual mecanismo de desenho gera o mapa: "plotly" para plotagem interativa padrão, "datashader" para renderização de rasters grandes, ou "auto" (padrão) para deixar a função escolher automaticamente conforme o tamanho dos dados.', es: 'Qué motor de dibujo produce el mapa: "plotly" para graficado interactivo estándar, "datashader" para renderizar rásteres grandes, o "auto" (por defecto) para dejar que la función elija automáticamente según el tamaño de los datos.', zh: '由哪个绘图引擎生成地图：“plotly”用于标准交互式绘图，“datashader”用于超大栅格渲染，或“auto”（默认）由函数根据数据量自动选择。' },
  'lcz_ts.x': { en: 'The LCZ raster map used to determine which LCZ class each weather station falls into, based on its location.', pt: 'O raster LCZ usado para determinar em qual classe LCZ cada estação meteorológica se encontra, com base em sua localização.', es: 'El mapa ráster LCZ usado para determinar en qué clase LCZ cae cada estación meteorológica, según su ubicación.', zh: '根据位置判断每个气象站所属 LCZ 类别的 LCZ 栅格地图。' },
  'lcz_ts.data_frame': { en: 'Your table of station observations, with columns for date, station ID, the variable being measured, and each station\'s latitude/longitude.', pt: 'Sua tabela de observações de estações, com colunas para data, ID da estação, a variável medida e latitude/longitude de cada estação.', es: 'Su tabla de observaciones de estaciones, con columnas para fecha, identificador de estación, la variable medida y la latitud/longitud de cada estación.', zh: '你的站点观测数据表，包含日期、站点 ID、被测变量以及每个站点的经纬度列。' },
  'lcz_ts.var': { en: 'The name of the column holding the value to plot, for example "temp_c".', pt: 'O nome da coluna que contém o valor a plotar, por exemplo "temp_c".', es: 'El nombre de la columna que contiene el valor a graficar, por ejemplo "temp_c".', zh: '保存待绘制数值的列名，例如“temp_c”。' },
  'lcz_ts.station_id': { en: 'The name of the column that identifies which station each row of data belongs to.', pt: 'O nome da coluna que identifica a qual estação cada linha de dados pertence.', es: 'El nombre de la columna que identifica a qué estación pertenece cada fila de datos.', zh: '标识每行数据所属站点的列名。' },
  'lcz_ts.time_freq': { en: 'How finely to average the data over time before plotting, such as "hour" (default) or "day". Finer frequencies show more short-term detail; coarser ones produce a smoother line.', pt: 'Com que granularidade calcular a média dos dados ao longo do tempo antes de plotar, como "hour" (padrão) ou "day". Frequências mais finas mostram mais detalhe de curto prazo; as mais grosseiras produzem uma linha mais suave.', es: 'Con qué finura promediar los datos en el tiempo antes de graficar, como "hour" (por defecto) o "day". Frecuencias más finas muestran más detalle de corto plazo; las más gruesas producen una línea más suave.', zh: '绘图前对数据进行时间平均的精细程度，例如“hour”（默认）或“day”。频率越细，短期细节越丰富；越粗则曲线越平滑。' },
  'lcz_ts.by': { en: 'Splits the chart into separate panels by a time grouping. For example, use "season" for four panels, "weekday" vs "weekend" to compare work-week and weekend patterns, or "daylight" to shade daytime hours on a single combined chart. Leave unset for one combined chart.', pt: 'Divide o gráfico em painéis separados por um agrupamento temporal. Por exemplo, use "season" para quatro painéis, "weekday" vs "weekend" para comparar padrões de dias úteis e fins de semana, ou "daylight" para sombrear as horas de luz do dia em um único gráfico combinado. Deixe em branco para um único gráfico combinado.', es: 'Divide el gráfico en paneles separados según una agrupación temporal. Por ejemplo, use "season" para cuatro paneles, "weekday" frente a "weekend" para comparar patrones de la semana laboral y el fin de semana, o "daylight" para sombrear las horas diurnas en un solo gráfico combinado. Déjelo sin definir para un solo gráfico combinado.', zh: '按时间分组将图表拆分为多个独立面板。例如使用“season”得到四个面板，“weekday”对“weekend”比较工作日与周末模式，或“daylight”在一张综合图表上标出白天时段。留空则生成一张综合图表。' },
  'lcz_ts.plot_type': { en: 'The kind of chart to draw, such as "basic_line" (the default, a simple line chart) or "heatmap" (a grid showing every station and time period at once). Note that heatmap cannot be combined with the by option.', pt: 'O tipo de gráfico a desenhar, como "basic_line" (padrão, um gráfico de linha simples) ou "heatmap" (uma grade mostrando cada estação e período de tempo de uma só vez). Observe que o mapa de calor não pode ser combinado com a opção by.', es: 'El tipo de gráfico a dibujar, como "basic_line" (por defecto, un gráfico de líneas simple) o "heatmap" (una cuadrícula que muestra cada estación y periodo a la vez). Tenga en cuenta que el mapa de calor no se puede combinar con la opción by.', zh: '要绘制的图表类型，例如“basic_line”（默认，简单折线图）或“heatmap”（一次性展示所有站点和时间段的网格图）。注意 heatmap 不能与 by 选项同时使用。' },
  'lcz_ts.facet_plot': { en: 'When plot_type is "heatmap", the column used to organize the grid\'s facets — defaults to "lcz" so each panel represents one LCZ class.', pt: 'Quando plot_type é "heatmap", a coluna usada para organizar os painéis da grade — o padrão é "lcz", de modo que cada painel represente uma classe LCZ.', es: 'Cuando plot_type es "heatmap", la columna usada para organizar los paneles de la cuadrícula; por defecto "lcz", de modo que cada panel representa una clase LCZ.', zh: '当 plot_type 为“heatmap”时，用于组织网格分面的列——默认值为“lcz”，即每个面板对应一个 LCZ 类别。' },
  'lcz_ts.iplot': { en: 'Leave this on (the default) to get a chart back. Turn it off to instead get the averaged data as a table, for example to export it or feed it into another analysis.', pt: 'Deixe ativado (padrão) para obter um gráfico de volta. Desative para obter em vez disso os dados médios como tabela, por exemplo para exportá-los ou alimentar outra análise.', es: 'Déjelo activado (por defecto) para obtener un gráfico. Desactívelo para obtener en cambio los datos promediados como tabla, por ejemplo para exportarlos o usarlos en otro análisis.', zh: '保持默认开启以获得图表。关闭此项可改为获取时间平均后的数据表，例如用于导出或输入到其他分析。' },
  'lcz_ts.isave': { en: 'Turn this on to also save a copy of the chart to the LCZ4r_output folder on disk, in addition to displaying it.', pt: 'Ative para também salvar uma cópia do gráfico na pasta LCZ4r_output em disco, além de exibi-lo.', es: 'Actívelo para guardar además una copia del gráfico en la carpeta LCZ4r_output en disco, además de mostrarlo.', zh: '开启后除了显示图表外，还会将其副本保存到 LCZ4r_output 文件夹。' },
  'lcz_ts.save_extension': { en: 'The file format for the saved chart when isave is on: "html" keeps it interactive, while "png" or "pdf" produce a static image suitable for reports.', pt: 'O formato de arquivo para o gráfico salvo quando isave está ativado: "html" o mantém interativo, enquanto "png" ou "pdf" produzem uma imagem estática adequada para relatórios.', es: 'El formato de archivo para el gráfico guardado cuando isave está activado: "html" lo mantiene interactivo, mientras que "png" o "pdf" producen una imagen estática apta para informes.', zh: 'isave 开启时保存图表所用的文件格式：“html”保持交互性，“png”或“pdf”生成适合报告的静态图片。' },
  'lcz_ts.palette': { en: 'The color palette used for the different LCZ lines on the chart, named after the MetBrewer palette collection — the default "VanGogh2" gives a distinct, readable color for each class. Change it if you want a different visual style.', pt: 'A paleta de cores usada para as diferentes linhas de LCZ no gráfico, nomeada a partir da coleção de paletas MetBrewer — a padrão "VanGogh2" dá uma cor distinta e legível para cada classe. Altere se quiser um estilo visual diferente.', es: 'La paleta de colores usada para las distintas líneas de LCZ en el gráfico, nombrada según la colección de paletas MetBrewer; la opción por defecto "VanGogh2" da un color distinto y legible a cada clase. Cámbiela si quiere un estilo visual diferente.', zh: '图表上不同 LCZ 曲线所用的配色方案，以 MetBrewer 配色集合命名——默认的“VanGogh2”为每个类别提供清晰可辨的颜色。如果想要不同的视觉风格可以更改。' },
  'lcz_ts.ylab': { en: 'Custom text for the vertical axis label. Leave blank to use the app\'s automatic, translated label.', pt: 'Texto personalizado para o rótulo do eixo vertical. Deixe em branco para usar o rótulo automático e traduzido do aplicativo.', es: 'Texto personalizado para la etiqueta del eje vertical. Déjelo en blanco para usar la etiqueta automática y traducida de la aplicación.', zh: '垂直轴标签的自定义文字。留空则使用应用自动生成的翻译标签。' },
  'lcz_ts.xlab': { en: 'Custom text for the horizontal (time) axis label. Leave blank to use the app\'s automatic, translated label.', pt: 'Texto personalizado para o rótulo do eixo horizontal (tempo). Deixe em branco para usar o rótulo automático e traduzido do aplicativo.', es: 'Texto personalizado para la etiqueta del eje horizontal (tiempo). Déjelo en blanco para usar la etiqueta automática y traducida de la aplicación.', zh: '水平（时间）轴标签的自定义文字。留空则使用应用自动生成的翻译标签。' },
  'lcz_ts.title': { en: 'Custom text to replace the chart\'s default title, for example "Hourly Temperature by LCZ — São Paulo, 2023".', pt: 'Texto personalizado para substituir o título padrão do gráfico, por exemplo "Temperatura Horária por LCZ — São Paulo, 2023".', es: 'Texto personalizado para sustituir el título por defecto del gráfico, por ejemplo "Temperatura Horaria por LCZ — São Paulo, 2023".', zh: '替换图表默认标题的自定义文字，例如“逐小时气温按 LCZ 分类 — 圣保罗，2023”。' },
  'lcz_ts.caption': { en: 'Optional small note shown below the chart, useful for citing a data source or adding context.', pt: 'Nota pequena opcional exibida abaixo do gráfico, útil para citar uma fonte de dados ou adicionar contexto.', es: 'Nota pequeña opcional mostrada debajo del gráfico, útil para citar una fuente de datos o añadir contexto.', zh: '图表下方显示的可选小字说明，适合注明数据来源或补充背景信息。' },
  'lcz_ts.year': { en: 'Restrict the chart to one or more specific years. Leave blank to use all available years.', pt: 'Restringe o gráfico a um ou mais anos específicos. Deixe em branco para usar todos os anos disponíveis.', es: 'Restringe el gráfico a uno o varios años concretos. Déjelo en blanco para usar todos los años disponibles.', zh: '将图表限定为一个或多个具体年份。留空则使用所有可用年份。' },
  'lcz_ts.month': { en: 'Restrict the chart to specific months (1-12). Leave blank to use all months.', pt: 'Restringe o gráfico a meses específicos (1-12). Deixe em branco para usar todos os meses.', es: 'Restringe el gráfico a meses concretos (1-12). Déjelo en blanco para usar todos los meses.', zh: '将图表限定为具体月份（1-12）。留空则使用所有月份。' },
  'lcz_ts.day': { en: 'Restrict the chart to specific days of the month. Leave blank to use all days.', pt: 'Restringe o gráfico a dias específicos do mês. Deixe em branco para usar todos os dias.', es: 'Restringe el gráfico a días concretos del mes. Déjelo en blanco para usar todos los días.', zh: '将图表限定为月份中的具体日期。留空则使用所有日期。' },
  'lcz_ts.hour': { en: 'Restrict the chart to specific hours of the day (0-23). Leave blank to use all hours.', pt: 'Restringe o gráfico a horas específicas do dia (0-23). Deixe em branco para usar todas as horas.', es: 'Restringe el gráfico a horas concretas del día (0-23). Déjelo en blanco para usar todas las horas.', zh: '将图表限定为一天中的具体小时（0-23）。留空则使用所有小时。' },
  'lcz_ts.start': { en: 'The earliest date to include, for example "2023-01-01". Leave blank to start from the beginning of your data.', pt: 'A data mais antiga a incluir, por exemplo "2023-01-01". Deixe em branco para começar do início dos seus dados.', es: 'La fecha más temprana a incluir, por ejemplo "2023-01-01". Déjela en blanco para empezar desde el inicio de sus datos.', zh: '要包含的最早日期，例如“2023-01-01”。留空则从数据起始处开始。' },
  'lcz_ts.end': { en: 'The latest date to include, for example "2023-12-31". Leave blank to run through the end of your data.', pt: 'A data mais recente a incluir, por exemplo "2023-12-31". Deixe em branco para ir até o fim dos seus dados.', es: 'La fecha más tardía a incluir, por ejemplo "2023-12-31". Déjela en blanco para llegar hasta el final de sus datos.', zh: '要包含的最晚日期，例如“2023-12-31”。留空则运行至数据末尾。' },
  'lcz_uhi_intensity.x': { en: 'The LCZ raster map used to automatically decide which of your stations sit in urban zones and which sit in rural zones. Required whenever method is set to "LCZ" (the default).', pt: 'O mapa raster LCZ usado para decidir automaticamente quais das suas estações estão em zonas urbanas e quais estão em zonas rurais. Obrigatório sempre que method for "LCZ" (padrão).', es: 'El mapa ráster LCZ usado para decidir automáticamente cuáles de sus estaciones están en zonas urbanas y cuáles en zonas rurales. Obligatorio siempre que method esté fijado en "LCZ" (valor por defecto).', zh: '用于自动判断哪些站点位于城市区、哪些位于乡村区的 LCZ 栅格地图。当 method 设为“LCZ”（默认）时为必填项。' },
  'lcz_uhi_intensity.data_frame': { en: 'Your table of station observations, with columns for date, station ID, the variable being measured, and the station\'s latitude/longitude. This is the data the UHI calculation runs on.', pt: 'Sua tabela de observações de estações, com colunas para data, ID da estação, a variável medida e latitude/longitude da estação. É sobre estes dados que o cálculo de ICU roda.', es: 'Su tabla de observaciones de estaciones, con columnas para fecha, identificador de estación, la variable medida y la latitud/longitud de la estación. Sobre estos datos se realiza el cálculo de ICU.', zh: '你的站点观测数据表，包含日期、站点 ID、被测变量以及站点经纬度列。这是 UHI 计算所依据的数据。' },
  'lcz_uhi_intensity.var': { en: 'The name of the column in your data holding the value to analyze, typically air temperature — for example "temp_c".', pt: 'O nome da coluna nos seus dados que contém o valor a analisar, tipicamente a temperatura do ar — por exemplo "temp_c".', es: 'El nombre de la columna de sus datos que contiene el valor a analizar, típicamente temperatura del aire, por ejemplo "temp_c".', zh: '数据中保存待分析数值的列名，通常是气温，例如“temp_c”。' },
  'lcz_uhi_intensity.station_id': { en: 'The name of the column that identifies which station each row of data belongs to, for example "station".', pt: 'O nome da coluna que identifica a qual estação cada linha de dados pertence, por exemplo "station".', es: 'El nombre de la columna que identifica a qué estación pertenece cada fila de datos, por ejemplo "station".', zh: '标识每行数据所属站点的列名，例如“station”。' },
  'lcz_uhi_intensity.time_freq': { en: 'How finely to average the data over time before computing UHI, such as "hour" (default) or "day". Finer frequencies show more short-term detail; coarser ones smooth out noise.', pt: 'Com que granularidade calcular a média dos dados ao longo do tempo antes de calcular a ICU, como "hour" (padrão) ou "day". Frequências mais finas mostram mais detalhe de curto prazo; as mais grosseiras suavizam o ruído.', es: 'Con qué finura promediar los datos en el tiempo antes de calcular la ICU, como "hour" (por defecto) o "day". Frecuencias más finas muestran más detalle de corto plazo; las más gruesas suavizan el ruido.', zh: '在计算 UHI 之前对数据进行时间平均的精细程度，例如“hour”（默认）或“day”。频率越细，短期细节越丰富；越粗则噪声越平滑。' },
  'lcz_uhi_intensity.by': { en: 'Splits the chart into separate panels by a time grouping so you can compare patterns side by side. For example, use "season" to get four panels (one per season), "month" for twelve monthly panels, or "weekend" to compare weekdays against weekends; leave unset for one combined chart.', pt: 'Divide o gráfico em painéis separados por um agrupamento temporal, para que você possa comparar padrões lado a lado. Por exemplo, use "season" para obter quatro painéis (um por estação do ano), "month" para doze painéis mensais, ou "weekend" para comparar dias úteis e fins de semana; deixe em branco para um único gráfico combinado.', es: 'Divide el gráfico en paneles separados según una agrupación temporal para poder comparar patrones lado a lado. Por ejemplo, use "season" para obtener cuatro paneles (uno por estación del año), "month" para doce paneles mensuales, o "weekend" para comparar días laborables frente a fines de semana; déjelo sin definir para un solo gráfico combinado.', zh: '按时间分组将图表拆分为多个独立面板，便于并排比较模式。例如使用“season”得到四个季节面板，“month”得到十二个月度面板，或“weekend”比较工作日与周末；留空则生成一张综合图表。' },
  'lcz_uhi_intensity.method': { en: '"LCZ" (default) automatically labels stations as urban or rural using the LCZ map in x. Choose "manual" if you\'d rather specify exactly which stations count as urban or rural yourself, using the T_urban and T_rural parameters.', pt: '"LCZ" (padrão) rotula automaticamente as estações como urbanas ou rurais usando o mapa LCZ em x. Escolha "manual" se preferir especificar você mesmo exatamente quais estações contam como urbanas ou rurais, usando os parâmetros T_urban e T_rural.', es: '"LCZ" (por defecto) etiqueta automáticamente las estaciones como urbanas o rurales usando el mapa LCZ indicado en x. Elija "manual" si prefiere especificar usted mismo exactamente qué estaciones cuentan como urbanas o rurales, mediante los parámetros T_urban y T_rural.', zh: '“LCZ”（默认）使用 x 中的 LCZ 地图自动将站点标记为城市或乡村。如果你想自行精确指定哪些站点算作城市、哪些算作乡村，请选择“manual”，并配合使用 T_urban 和 T_rural 参数。' },
  'lcz_uhi_intensity.T_urban': { en: 'The list of station IDs to treat as "urban" reference points. Only used when method is set to "manual", for example ["STN001", "STN002"].', pt: 'A lista de IDs de estação a tratar como pontos de referência "urbanos". Usado apenas quando method é "manual", por exemplo ["STN001", "STN002"].', es: 'La lista de identificadores de estaciones a tratar como puntos de referencia "urbanos". Solo se usa cuando method está fijado en "manual", por ejemplo ["STN001", "STN002"].', zh: '作为“城市”参照点的站点 ID 列表。仅当 method 设为“manual”时使用，例如 ["STN001", "STN002"]。' },
  'lcz_uhi_intensity.T_rural': { en: 'The list of station IDs to treat as "rural" reference points. Only used when method is set to "manual", for example ["STN010"].', pt: 'A lista de IDs de estação a tratar como pontos de referência "rurais". Usado apenas quando method é "manual", por exemplo ["STN010"].', es: 'La lista de identificadores de estaciones a tratar como puntos de referencia "rurales". Solo se usa cuando method está fijado en "manual", por ejemplo ["STN010"].', zh: '作为“乡村”参照点的站点 ID 列表。仅当 method 设为“manual”时使用，例如 ["STN010"]。' },
  'lcz_uhi_intensity.group': { en: 'Turn this on to plot the urban and rural temperature curves alongside the UHI curve on two axes, so you can see both the underlying temperatures and their difference. Leave off to show only the UHI intensity line by itself.', pt: 'Ative para plotar as curvas de temperatura urbana e rural junto com a curva de ICU em dois eixos, para ver tanto as temperaturas subjacentes quanto sua diferença. Deixe desativado para mostrar apenas a linha de intensidade da ICU sozinha.', es: 'Actívelo para graficar las curvas de temperatura urbana y rural junto a la curva de ICU en dos ejes, de modo que pueda ver tanto las temperaturas subyacentes como su diferencia. Déjelo desactivado para mostrar solo la línea de intensidad de ICU por sí sola.', zh: '开启后会在两个坐标轴上同时绘制城市与乡村的温度曲线以及 UHI 曲线，让你既能看到底层温度也能看到它们之间的差值。关闭则只显示 UHI 强度曲线本身。' },
  'lcz_uhi_intensity.iplot': { en: 'Leave this on (the default) to get a chart back. Turn it off if you instead want the underlying calculated data as a table, for example to export it or feed it into another analysis.', pt: 'Deixe ativado (padrão) para obter um gráfico de volta. Desative se em vez disso você quiser os dados calculados subjacentes como tabela, por exemplo para exportá-los ou alimentar outra análise.', es: 'Déjelo activado (por defecto) para obtener un gráfico. Desactívelo si en cambio quiere los datos calculados subyacentes como tabla, por ejemplo para exportarlos o usarlos en otro análisis.', zh: '保持默认开启以获得图表。若你想改为获取底层计算数据的表格（例如用于导出或输入到其他分析），可关闭此项。' },
  'lcz_uhi_intensity.isave': { en: 'Turn this on to also save a copy of the chart to the LCZ4r_output folder on disk, in addition to displaying it.', pt: 'Ative para também salvar uma cópia do gráfico na pasta LCZ4r_output em disco, além de exibi-lo.', es: 'Actívelo para guardar además una copia del gráfico en la carpeta LCZ4r_output en disco, además de mostrarlo.', zh: '开启后除了显示图表外，还会将其副本保存到 LCZ4r_output 文件夹。' },
  'lcz_uhi_intensity.save_extension': { en: 'The file format for the saved chart when isave is on: "html" keeps it interactive (you can zoom and hover), while "png" or "pdf" produce a static image suitable for reports or papers.', pt: 'O formato de arquivo para o gráfico salvo quando isave está ativado: "html" o mantém interativo (com zoom e passagem do mouse), enquanto "png" ou "pdf" produzem uma imagem estática adequada para relatórios ou artigos.', es: 'El formato de archivo para el gráfico guardado cuando isave está activado: "html" lo mantiene interactivo (con zoom y datos al pasar el cursor), mientras que "png" o "pdf" producen una imagen estática apta para informes o artículos.', zh: 'isave 开启时保存图表所用的文件格式：“html”保持交互性（可缩放悬停），“png”或“pdf”生成适合报告或论文的静态图片。' },
  'lcz_uhi_intensity.ylab': { en: 'Custom text for the left vertical axis label. Leave blank to use the app\'s automatic, translated label.', pt: 'Texto personalizado para o rótulo do eixo vertical esquerdo. Deixe em branco para usar o rótulo automático e traduzido do aplicativo.', es: 'Texto personalizado para la etiqueta del eje vertical izquierdo. Déjelo en blanco para usar la etiqueta automática y traducida de la aplicación.', zh: '左侧垂直轴标签的自定义文字。留空则使用应用自动生成的翻译标签。' },
  'lcz_uhi_intensity.xlab': { en: 'Custom text for the horizontal (time) axis label. Leave blank to use the app\'s automatic, translated label.', pt: 'Texto personalizado para o rótulo do eixo horizontal (tempo). Deixe em branco para usar o rótulo automático e traduzido do aplicativo.', es: 'Texto personalizado para la etiqueta del eje horizontal (tiempo). Déjelo en blanco para usar la etiqueta automática y traducida de la aplicación.', zh: '水平（时间）轴标签的自定义文字。留空则使用应用自动生成的翻译标签。' },
  'lcz_uhi_intensity.ylab2': { en: 'Custom text for the second (right-hand) vertical axis label, used only when group is turned on. Leave blank to use the app\'s automatic, translated label.', pt: 'Texto personalizado para o rótulo do segundo eixo vertical (à direita), usado apenas quando group está ativado. Deixe em branco para usar o rótulo automático e traduzido do aplicativo.', es: 'Texto personalizado para la etiqueta del segundo eje vertical (derecho), usado solo cuando group está activado. Déjelo en blanco para usar la etiqueta automática y traducida de la aplicación.', zh: '第二个（右侧）垂直轴标签的自定义文字，仅在 group 开启时使用。留空则使用应用自动生成的翻译标签。' },
  'lcz_uhi_intensity.title': { en: 'Custom text to replace the chart\'s default title, for example "UHI Intensity — Recife, 2023".', pt: 'Texto personalizado para substituir o título padrão do gráfico, por exemplo "Intensidade da ICU — Recife, 2023".', es: 'Texto personalizado para sustituir el título por defecto del gráfico, por ejemplo "Intensidad de ICU — Recife, 2023".', zh: '替换图表默认标题的自定义文字，例如“UHI 强度 — 累西腓，2023”。' },
  'lcz_uhi_intensity.caption': { en: 'Optional small note shown below the chart, useful for citing a data source or adding context.', pt: 'Nota pequena opcional exibida abaixo do gráfico, útil para citar uma fonte de dados ou adicionar contexto.', es: 'Nota pequeña opcional mostrada debajo del gráfico, útil para citar una fuente de datos o añadir contexto.', zh: '图表下方显示的可选小字说明，适合注明数据来源或补充背景信息。' },
  'lcz_uhi_intensity.year': { en: 'Restrict the analysis to one or more specific years, for example 2022. Leave blank to use all available years.', pt: 'Restringe a análise a um ou mais anos específicos, por exemplo 2022. Deixe em branco para usar todos os anos disponíveis.', es: 'Restringe el análisis a uno o varios años concretos, por ejemplo 2022. Déjelo en blanco para usar todos los años disponibles.', zh: '将分析限定为一个或多个具体年份，例如 2022。留空则使用所有可用年份。' },
  'lcz_uhi_intensity.month': { en: 'Restrict the analysis to specific months (1-12), for example 7 for July only. Leave blank to use all months.', pt: 'Restringe a análise a meses específicos (1-12), por exemplo 7 para apenas julho. Deixe em branco para usar todos os meses.', es: 'Restringe el análisis a meses concretos (1-12), por ejemplo 7 solo para julio. Déjelo en blanco para usar todos los meses.', zh: '将分析限定为具体月份（1-12），例如 7 表示仅 7 月。留空则使用所有月份。' },
  'lcz_uhi_intensity.day': { en: 'Restrict the analysis to specific days of the month. Leave blank to use all days.', pt: 'Restringe a análise a dias específicos do mês. Deixe em branco para usar todos os dias.', es: 'Restringe el análisis a días concretos del mes. Déjelo en blanco para usar todos los días.', zh: '将分析限定为月份中的具体日期。留空则使用所有日期。' },
  'lcz_uhi_intensity.hour': { en: 'Restrict the analysis to specific hours of the day (0-23), for example to look only at nighttime hours. Leave blank to use all hours.', pt: 'Restringe a análise a horas específicas do dia (0-23), por exemplo para olhar apenas as horas noturnas. Deixe em branco para usar todas as horas.', es: 'Restringe el análisis a horas concretas del día (0-23), por ejemplo para mirar solo las horas nocturnas. Déjelo en blanco para usar todas las horas.', zh: '将分析限定为一天中的具体小时（0-23），例如只查看夜间时段。留空则使用所有小时。' },
  'lcz_uhi_intensity.start': { en: 'The earliest date to include, for example "2023-01-01". Leave blank to start from the beginning of your data.', pt: 'A data mais antiga a incluir, por exemplo "2023-01-01". Deixe em branco para começar do início dos seus dados.', es: 'La fecha más temprana a incluir, por ejemplo "2023-01-01". Déjela en blanco para empezar desde el inicio de sus datos.', zh: '要包含的最早日期，例如“2023-01-01”。留空则从数据起始处开始。' },
  'lcz_uhi_intensity.end': { en: 'The latest date to include, for example "2023-12-31". Leave blank to run through the end of your data.', pt: 'A data mais recente a incluir, por exemplo "2023-12-31". Deixe em branco para ir até o fim dos seus dados.', es: 'La fecha más tardía a incluir, por ejemplo "2023-12-31". Déjela en blanco para llegar hasta el final de sus datos.', zh: '要包含的最晚日期，例如“2023-12-31”。留空则运行至数据末尾。' },
  'lcz_uhi_surface.lcz_map': { en: 'Path to the LCZ classification map (a GeoTIFF with class codes 1-17) covering the same area and pixel grid as your land surface temperature data. This tells the function which LCZ class each temperature pixel belongs to.', pt: 'Caminho para o mapa de classificação LCZ (um GeoTIFF com códigos de classe 1-17) cobrindo a mesma área e grade de pixels dos seus dados de temperatura de superfície. Isso informa à função a qual classe LCZ cada pixel de temperatura pertence.', es: 'Ruta al mapa de clasificación LCZ (un GeoTIFF con códigos de clase 1-17) que cubre la misma área y cuadrícula de píxeles que sus datos de temperatura de superficie. Esto indica a la función a qué clase LCZ pertenece cada píxel de temperatura.', zh: '与地表温度数据处于同一区域和像元网格的 LCZ 分类地图路径（GeoTIFF，类别代码 1-17）。此项用于确定每个温度像元所属的 LCZ 类别。' },
  'lcz_uhi_surface.lst_x': { en: 'The land surface temperature data to analyze — either the file path to the image stack produced by the LCZ4r land-surface-temperature retrieval step, or that step\'s result object directly. The images must already be saved to disk (the default caching behavior handles this automatically).', pt: 'Os dados de temperatura de superfície a analisar — o caminho do arquivo da pilha de imagens produzida pela etapa de obtenção de temperatura de superfície do LCZ4r, ou o objeto de resultado dessa etapa diretamente. As imagens já devem estar salvas em disco (o cache padrão cuida disso automaticamente).', es: 'Los datos de temperatura de superficie a analizar: la ruta al archivo de la pila de imágenes producida por el paso de obtención de temperatura de superficie de LCZ4r, o el objeto resultado de ese paso directamente. Las imágenes ya deben estar guardadas en disco (el comportamiento de caché por defecto se encarga de esto automáticamente).', zh: '要分析的地表温度数据——可以是 LCZ4r 地表温度提取步骤生成的影像堆栈文件路径，也可以是该步骤直接返回的结果对象。影像必须已保存到磁盘上（默认的缓存行为会自动处理这一点）。' },
  'lcz_uhi_surface.method': { en: 'Which SUHI analysis to run. "urban_rural" (default) tracks the urban-minus-rural temperature difference over time; "percentile" does the same but uses a percentile of rural temperatures as the baseline instead of the mean; "lcz" compares each LCZ class\'s average temperature against a reference class; "utfvi" maps a heat-vulnerability index for one date; "hotspot" statistically detects hot/cold spot clusters for one date; "transect" profiles how temperature changes with distance from the urban core; "persistence" maps how often each pixel stays hotter than the rural baseline across all dates; "all" runs every method at once.', pt: 'Qual análise de ICS executar. "urban_rural" (padrão) acompanha a diferença de temperatura urbano-menos-rural ao longo do tempo; "percentile" faz o mesmo, mas usa um percentil das temperaturas rurais como referência em vez da média; "lcz" compara a temperatura média de cada classe LCZ contra uma classe de referência; "utfvi" mapeia um índice de vulnerabilidade ao calor para uma data; "hotspot" detecta estatisticamente agrupamentos de pontos quentes/frios para uma data; "transect" traça o perfil de como a temperatura muda com a distância do núcleo urbano; "persistence" mapeia com que frequência cada pixel permanece mais quente do que a referência rural ao longo de todas as datas; "all" roda todos os métodos de uma vez.', es: 'Qué análisis de ICUS ejecutar. "urban_rural" (por defecto) sigue en el tiempo la diferencia de temperatura urbano menos rural; "percentile" hace lo mismo pero usa un percentil de las temperaturas rurales como base en lugar de la media; "lcz" compara la temperatura media de cada clase LCZ frente a una clase de referencia; "utfvi" mapea un índice de vulnerabilidad al calor para una fecha; "hotspot" detecta estadísticamente conglomerados de focos cálidos/fríos en una fecha; "transect" perfila cómo cambia la temperatura con la distancia al núcleo urbano; "persistence" mapea con qué frecuencia cada píxel se mantiene más caliente que la base rural en todas las fechas; "all" ejecuta todos los métodos a la vez.', zh: '要运行的 SUHI 分析类型。“urban_rural”（默认）追踪城市减乡村温差随时间的变化；“percentile”做法类似，但使用乡村温度的某个百分位数而非平均值作为基准；“lcz”比较各 LCZ 类别的平均温度与参照类别的差异；“utfvi”为某一日期绘制热脆弱性指数地图；“hotspot”对某一日期进行热点/冷点聚类的统计检测；“transect”描绘温度随离城市核心距离变化的剖面；“persistence”统计每个像元在所有日期中持续高于乡村基准的频率；“all”一次性运行所有方法。' },
  'lcz_uhi_surface.reference_lcz': { en: 'The LCZ class used as the "normal" baseline when method is "lcz" — defaults to class 14 (Low plants), a typical vegetated reference. Change this if you\'d rather compare against a different land cover type.', pt: 'A classe LCZ usada como referência "normal" quando method é "lcz" — o padrão é a classe 14 (Vegetação rasteira), uma referência vegetada típica. Altere se preferir comparar contra outro tipo de cobertura do solo.', es: 'La clase LCZ usada como base "normal" cuando method es "lcz"; por defecto la clase 14 (Vegetación baja), una referencia vegetada típica. Cámbiela si prefiere comparar contra otro tipo de cobertura del suelo.', zh: 'method 为“lcz”时用作“正常”基准的 LCZ 类别——默认取第 14 类（低矮植被），一种典型的植被参照类型。若想改为与其他地表覆盖类型比较，可修改此值。' },
  'lcz_uhi_surface.percentile': { en: 'For method="percentile", which percentile of rural temperatures to use as the comparison baseline instead of the plain average, for example 10 for the coolest 10% of rural readings. Defaults to 10.', pt: 'Para method="percentile", qual percentil das temperaturas rurais usar como referência de comparação em vez da média simples, por exemplo 10 para os 10% mais frios das leituras rurais. O padrão é 10.', es: 'Para method="percentile", qué percentil de las temperaturas rurales usar como base de comparación en lugar del simple promedio, por ejemplo 10 para el 10% más fresco de las lecturas rurales. Por defecto es 10.', zh: 'method="percentile" 时，使用乡村温度的哪个百分位数作为比较基准，而不是简单平均值，例如 10 表示最凉爽的 10% 乡村读数。默认值为 10。' },
  'lcz_uhi_surface.hotspot_window': { en: 'The size, in pixels, of the local neighborhood examined when detecting hot/cold spots with method="hotspot". Must be an odd number; the default of 3 looks at each pixel plus its immediate 3x3 surroundings. Larger windows smooth out fine detail in favor of broader patterns.', pt: 'O tamanho, em pixels, da vizinhança local examinada ao detectar pontos quentes/frios com method="hotspot". Deve ser um número ímpar; o padrão de 3 examina cada pixel mais sua vizinhança imediata de 3x3. Janelas maiores suavizam o detalhe fino em favor de padrões mais amplos.', es: 'El tamaño, en píxeles, del entorno local examinado al detectar focos cálidos/fríos con method="hotspot". Debe ser un número impar; el valor por defecto de 3 examina cada píxel junto con su entorno inmediato de 3x3. Ventanas más grandes suavizan el detalle fino a favor de patrones más amplios.', zh: '使用 method="hotspot" 检测热点/冷点时，所考察的局部邻域大小（像元数）。必须为奇数；默认值 3 表示考察每个像元及其周围的 3x3 邻域。窗口越大，越会平滑掉细节而突出更宏观的格局。' },
  'lcz_uhi_surface.hotspot_confidence': { en: 'How statistically confident a cluster must be to count as a significant hot or cold spot when method="hotspot", for example 0.95 for 95% confidence. Higher values flag fewer, more certain hotspots.', pt: 'Quão estatisticamente confiante um agrupamento deve ser para contar como um ponto quente ou frio significativo com method="hotspot", por exemplo 0,95 para 95% de confiança. Valores mais altos sinalizam menos pontos quentes, porém mais certos.', es: 'Cuán estadísticamente seguro debe ser un conglomerado para contar como foco cálido o frío significativo con method="hotspot", por ejemplo 0,95 para un 95% de confianza. Valores más altos señalan menos focos, pero más certeros.', zh: '使用 method="hotspot" 时，聚类需要达到多高的统计置信度才算作显著热点或冷点，例如 0.95 表示 95% 置信度。数值越高，识别出的热点越少但越可靠。' },
  'lcz_uhi_surface.persistence_threshold': { en: 'For method="persistence", how many degrees above the day\'s rural baseline a pixel must be to count as "exceeding" that day, for example 1.0 degree. Lower values flag persistence more readily; higher values only count strong heat events.', pt: 'Para method="persistence", quantos graus acima da referência rural do dia um pixel precisa estar para contar como "excedente" naquele dia, por exemplo 1,0 grau. Valores mais baixos sinalizam persistência com mais facilidade; valores mais altos só contam eventos de calor intensos.', es: 'Para method="persistence", cuántos grados por encima de la base rural del día debe estar un píxel para contar como "excedente" ese día, por ejemplo 1,0 grado. Valores más bajos señalan persistencia con más facilidad; valores más altos solo cuentan eventos de calor fuertes.', zh: 'method="persistence" 时，像元温度需要比当天乡村基准高出多少度才算作“超出”当天基准，例如 1.0 度。数值越低，越容易被判定为持续高温；数值越高，只有强烈的高温事件才会被计入。' },
  'lcz_uhi_surface.n_bins': { en: 'For method="transect", how many distance-from-city-center bins to group pixels into when building the urban-rural temperature gradient profile. More bins give a finer-grained profile; fewer bins give a smoother one.', pt: 'Para method="transect", em quantas faixas de distância a partir do centro da cidade agrupar os pixels ao construir o perfil de gradiente de temperatura urbano-rural. Mais faixas dão um perfil mais detalhado; menos faixas dão um perfil mais suave.', es: 'Para method="transect", en cuántos intervalos de distancia al centro de la ciudad agrupar los píxeles al construir el perfil del gradiente de temperatura urbano-rural. Más intervalos dan un perfil más detallado; menos intervalos dan uno más suave.', zh: 'method="transect" 时，在构建城乡温度梯度剖面时，将像元按离城市中心距离分成的分箱数量。分箱越多，剖面越精细；分箱越少，剖面越平滑。' },
  'lcz_uhi_surface.date_index': { en: 'Which image in the time stack to use for the single-date methods ("utfvi" and "hotspot"), counting from 0 for the first date. Leave blank to automatically use the most recent date available.', pt: 'Qual imagem da pilha temporal usar para os métodos de data única ("utfvi" e "hotspot"), contando a partir de 0 para a primeira data. Deixe em branco para usar automaticamente a data mais recente disponível.', es: 'Qué imagen de la pila temporal usar para los métodos de fecha única ("utfvi" y "hotspot"), contando desde 0 para la primera fecha. Déjelo en blanco para usar automáticamente la fecha más reciente disponible.', zh: '对于单日期方法（“utfvi”和“hotspot”），使用时间堆栈中的哪一张影像，从 0 开始计数第一个日期。留空则自动使用最新的可用日期。' },
  'lcz_uhi_surface.iplot': { en: 'Leave this on (the default) to get charts and maps back. Turn it off to skip the visuals and get only the underlying statistics table (or, when method="all", a set of tables).', pt: 'Deixe ativado (padrão) para obter gráficos e mapas de volta. Desative para pular as visualizações e obter apenas a tabela estatística subjacente (ou, quando method="all", um conjunto de tabelas).', es: 'Déjelo activado (por defecto) para obtener gráficos y mapas. Desactívelo para omitir los elementos visuales y obtener solo la tabla de estadísticas subyacente (o, cuando method="all", un conjunto de tablas).', zh: '保持默认开启以获得图表和地图。关闭此项可跳过可视化，仅获取底层统计表（当 method="all" 时为一组表）。' },
  'lcz_uhi_surface.isave': { en: 'Turn this on to also save the resulting charts and a CSV of the statistics to the LCZ4r_output folder, in addition to displaying them.', pt: 'Ative para também salvar os gráficos resultantes e um CSV das estatísticas na pasta LCZ4r_output, além de exibi-los.', es: 'Actívelo para guardar además los gráficos resultantes y un CSV con las estadísticas en la carpeta LCZ4r_output, además de mostrarlos.', zh: '开启后除了显示图表和地图外，还会将结果图表和统计数据的 CSV 文件保存到 LCZ4r_output 文件夹。' },
  'lcz_uhi_surface.save_extension': { en: 'The file format for saved charts when isave is on: "html" for an interactive version, or "png"/"pdf" for a static image suitable for a report.', pt: 'O formato de arquivo para gráficos salvos quando isave está ativado: "html" para uma versão interativa, ou "png"/"pdf" para uma imagem estática adequada para um relatório.', es: 'El formato de archivo para los gráficos guardados cuando isave está activado: "html" para una versión interactiva, o "png"/"pdf" para una imagen estática apta para un informe.', zh: 'isave 开启时保存图表所用的文件格式：“html”为交互式版本，“png”/“pdf”为适合报告的静态图片。' },
  'lcz_uhi_surface.inclusive': { en: 'Turn this on to use the colorblind-friendly version of the LCZ color palette on bar charts, making the results easier to read for colorblind viewers.', pt: 'Ative para usar a versão adequada para daltônicos da paleta de cores LCZ nos gráficos de barras, tornando os resultados mais fáceis de ler para pessoas com daltonismo.', es: 'Actívelo para usar la versión apta para daltónicos de la paleta de colores LCZ en los gráficos de barras, facilitando la lectura de los resultados a personas con daltonismo.', zh: '开启后在条形图上使用色盲友好版的 LCZ 配色方案，使结果对色觉障碍观众更易读。' },
  'lcz_uhi_surface.title': { en: 'Custom text to replace the default chart or map title.', pt: 'Texto personalizado para substituir o título padrão do gráfico ou mapa.', es: 'Texto personalizado para sustituir el título por defecto del gráfico o mapa.', zh: '替换默认图表或地图标题的自定义文字。' },
  'lcz_uhi_surface.caption': { en: 'Optional small note shown below the chart or map, useful for citing a data source or adding context.', pt: 'Nota pequena opcional exibida abaixo do gráfico ou mapa, útil para citar uma fonte de dados ou adicionar contexto.', es: 'Nota pequeña opcional mostrada debajo del gráfico o mapa, útil para citar una fuente de datos o añadir contexto.', zh: '图表或地图下方显示的可选小字说明，适合注明数据来源或补充背景信息。' },
  'lcz_utci.air_temp': { en: 'The air temperature in degrees Celsius, either a single value or an array of values (e.g. one per station or per grid cell). This is the base temperature the whole index is built from.', pt: 'A temperatura do ar em graus Celsius, seja um único valor ou um vetor de valores (por exemplo, um por estação ou por célula de grade). É a temperatura base sobre a qual todo o índice é construído.', es: 'La temperatura del aire en grados Celsius, ya sea un único valor o un arreglo de valores (por ejemplo uno por estación o por celda de la cuadrícula). Es la temperatura base a partir de la cual se construye todo el índice.', zh: '以摄氏度表示的气温，可以是单个数值，也可以是数值数组（例如每个站点或每个网格单元一个）。这是整个指数计算的基础温度。' },
  'lcz_utci.wind_speed': { en: 'Wind speed in meters per second, measured or estimated at 10 meters above the ground. Higher wind speeds cool the perceived temperature in warm conditions, so this strongly affects the result.', pt: 'A velocidade do vento em metros por segundo, medida ou estimada a 10 metros acima do solo. Velocidades de vento mais altas esfriam a sensação térmica em condições quentes, afetando fortemente o resultado.', es: 'La velocidad del viento en metros por segundo, medida o estimada a 10 metros sobre el suelo. Velocidades de viento más altas enfrían la temperatura percibida en condiciones cálidas, por lo que afectan fuertemente al resultado.', zh: '以米每秒表示的风速，在离地 10 米处测量或估算。风速越高，在炎热条件下体感温度越凉，因此对结果影响很大。' },
  'lcz_utci.relative_humidity': { en: 'Relative humidity as a percentage (0-100), for example 65. Higher humidity makes hot conditions feel more oppressive.', pt: 'A umidade relativa em porcentagem (0-100), por exemplo 65. Umidade mais alta faz condições quentes parecerem mais opressivas.', es: 'La humedad relativa como porcentaje (0-100), por ejemplo 65. Una humedad más alta hace que las condiciones cálidas se sientan más agobiantes.', zh: '以百分比（0-100）表示的相对湿度，例如 65。湿度越高，炎热条件会让人感觉越闷热。' },
  'lcz_utci.mean_radiant_temp': { en: 'The mean radiant temperature in degrees Celsius, representing the net heat radiating onto a person from the sun and surrounding surfaces. If left blank, it\'s estimated from the LCZ class\'s typical sky exposure (when lc_z is given) or simply assumed equal to air temperature.', pt: 'A temperatura radiante média em graus Celsius, representando o calor líquido irradiado sobre uma pessoa pelo sol e pelas superfícies ao redor. Se deixada em branco, é estimada a partir da exposição típica ao céu da classe LCZ (quando lc_z é informado) ou simplesmente considerada igual à temperatura do ar.', es: 'La temperatura radiante media en grados Celsius, que representa el calor neto que irradia hacia una persona desde el sol y las superficies circundantes. Si se deja en blanco, se estima a partir de la exposición al cielo típica de la clase LCZ (cuando se indica lc_z) o simplemente se asume igual a la temperatura del aire.', zh: '以摄氏度表示的平均辐射温度，代表太阳和周围表面净辐射到人体上的热量。留空时会根据 LCZ 类别典型的天空暴露程度进行估算（若提供了 lc_z），否则直接假定等于气温。' },
  'lcz_utci.lc_z': { en: 'The LCZ class code(s) (1-17) for the location(s) being analyzed. Used only to estimate mean_radiant_temp from typical sky view factor when you haven\'t measured radiant temperature directly — for example, a dense LCZ 2 district blocks more sky than an open LCZ 6 suburb.', pt: 'O(s) código(s) de classe LCZ (1-17) da(s) localização(ões) analisada(s). Usado apenas para estimar mean_radiant_temp a partir do fator de visão do céu típico quando você não mediu a temperatura radiante diretamente — por exemplo, um distrito denso LCZ 2 bloqueia mais céu do que um subúrbio aberto LCZ 6.', es: 'El código o códigos de clase LCZ (1-17) de las ubicaciones analizadas. Se usa solo para estimar mean_radiant_temp a partir del factor de visión del cielo típico cuando no ha medido la temperatura radiante directamente; por ejemplo, un distrito denso de LCZ 2 bloquea más cielo que un suburbio abierto de LCZ 6.', zh: '被分析位置的 LCZ 类别代码（1-17）。仅在你未直接测量辐射温度时用于根据典型天空可视因子估算 mean_radiant_temp——例如，密集的 LCZ 2 街区遮挡的天空比开敞的 LCZ 6 郊区更多。' },
  'lcz_utci.output': { en: 'Choose "category" (default) to get plain-language thermal stress labels like "strong heat stress" or "no thermal stress", which are easier to interpret at a glance. Choose "index" to get the raw numeric UTCI value in degrees Celsius instead, useful if you want to do further calculations or plotting.', pt: 'Escolha "category" (padrão) para obter rótulos de estresse térmico em linguagem simples, como "forte estresse térmico" ou "sem estresse térmico", mais fáceis de interpretar rapidamente. Escolha "index" para obter em vez disso o valor numérico bruto do UTCI em graus Celsius, útil se você quiser fazer cálculos ou gráficos adicionais.', es: 'Elija "category" (por defecto) para obtener etiquetas de estrés térmico en lenguaje sencillo, como "estrés térmico fuerte" o "sin estrés térmico", más fáciles de interpretar de un vistazo. Elija "index" para obtener en cambio el valor numérico crudo del UTCI en grados Celsius, útil si quiere hacer cálculos o gráficos adicionales.', zh: '选择“category”（默认）获取通俗易懂的热应力等级标签，如“强烈热应力”或“无热应力”，便于一目了然地解读。选择“index”则获取原始的数值型 UTCI 结果（摄氏度），适合用于进一步计算或绘图。' },
  'lcz_variogram.x': { en: 'The LCZ raster map for your study area, used to determine the correct projected coordinate system for measuring real-world distances between stations.', pt: 'O raster LCZ da sua área de estudo, usado para determinar o sistema de coordenadas projetado correto para medir distâncias reais entre estações.', es: 'El mapa ráster LCZ de su área de estudio, usado para determinar el sistema de coordenadas proyectado correcto con el que medir distancias reales entre estaciones.', zh: '你研究区的 LCZ 栅格地图，用于确定测量站点间真实距离所需的正确投影坐标系统。' },
  'lcz_variogram.data_frame': { en: 'Your table of station observations, with columns for date, station, variable, latitude, and longitude.', pt: 'Sua tabela de observações de estações, com colunas para data, estação, variável, latitude e longitude.', es: 'Su tabla de observaciones de estaciones, con columnas para fecha, estación, variable, latitud y longitud.', zh: '你的站点观测数据表，包含日期、站点、变量、纬度和经度列。' },
  'lcz_variogram.var': { en: 'The name of the column that holds the variable to analyze, such as "airT" for air temperature. Required — there is no default.', pt: 'O nome da coluna que contém a variável a analisar, como "airT" para temperatura do ar. Obrigatório — não há valor padrão.', es: 'El nombre de la columna que contiene la variable a analizar, como "airT" para temperatura del aire. Obligatorio; no tiene valor por defecto.', zh: '保存待分析变量的列名，例如“airT”表示气温。此项为必填——没有默认值。' },
  'lcz_variogram.station_id': { en: 'The name of the column that identifies each station. Required — there is no default.', pt: 'O nome da coluna que identifica cada estação. Obrigatório — não há valor padrão.', es: 'El nombre de la columna que identifica a cada estación. Obligatorio; no tiene valor por defecto.', zh: '标识每个站点的列名。此项为必填——没有默认值。' },
  'lcz_variogram.sp_res': { en: 'A resolution value in meters used internally to prepare the coordinate system for the analysis; it does not control the size of any output grid, since a variogram is a diagnostic plot, not a map.', pt: 'Um valor de resolução em metros usado internamente para preparar o sistema de coordenadas da análise; não controla o tamanho de nenhuma grade de saída, já que um variograma é um gráfico diagnóstico, não um mapa.', es: 'Un valor de resolución en metros usado internamente para preparar el sistema de coordenadas del análisis; no controla el tamaño de ninguna cuadrícula de salida, ya que un variograma es un gráfico diagnóstico, no un mapa.', zh: '内部用于准备分析坐标系统的分辨率值，单位为米；它不控制任何输出网格的大小，因为变异函数是一种诊断图，而非地图。' },
  'lcz_variogram.model': { en: 'The theoretical curve shape to fit to the observed spatial pattern. "Sph" (spherical, the default) works well for most urban climate data; other options let you test whether a different shape, such as exponential or Gaussian, fits your data better.', pt: 'O formato de curva teórico a ajustar ao padrão espacial observado. "Sph" (esférico, padrão) funciona bem para a maioria dos dados de clima urbano; outras opções permitem testar se um formato diferente, como exponencial ou Gaussiano, se ajusta melhor aos seus dados.', es: 'La forma de curva teórica a ajustar al patrón espacial observado. "Sph" (esférico, por defecto) funciona bien para la mayoría de los datos de clima urbano; las demás opciones le permiten probar si otra forma, como exponencial o gaussiana, se ajusta mejor a sus datos.', zh: '拟合观测空间模式所用的理论曲线形状。“Sph”（球状模型，默认）适用于大多数城市气候数据；其他选项可用于测试指数或高斯等不同形状是否更适合你的数据。' },
  'lcz_variogram.n_lags': { en: 'How many distance bins to group station pairs into when measuring spatial correlation. The default of 20 gives a smooth curve for typical networks; use fewer bins (e.g. 10) if you only have a small number of stations.', pt: 'Em quantas faixas de distância agrupar os pares de estações ao medir a correlação espacial. O padrão de 20 dá uma curva suave para redes típicas; use menos faixas (por exemplo, 10) se você tiver poucas estações.', es: 'En cuántos intervalos de distancia agrupar los pares de estaciones al medir la correlación espacial. El valor por defecto de 20 da una curva suave para redes típicas; use menos intervalos (por ejemplo 10) si solo tiene un número pequeño de estaciones.', zh: '测量空间相关性时，将站点对分组的距离分箱数量。默认值 20 对典型站网能给出平滑的曲线；如果站点数量较少，可使用更少的分箱（如 10）。' },
  'lcz_variogram.max_dist': { en: 'The farthest station-to-station distance to include in the analysis, in meters. Leave unset to let the tool automatically use half the maximum distance between any two stations in your data, which is a reasonable default for most cases.', pt: 'A distância máxima entre estações a incluir na análise, em metros. Deixe em branco para que a ferramenta use automaticamente metade da distância máxima entre quaisquer duas estações nos seus dados, um padrão razoável para a maioria dos casos.', es: 'La distancia más lejana entre estaciones a incluir en el análisis, en metros. Déjelo sin definir para que la herramienta use automáticamente la mitad de la distancia máxima entre dos estaciones cualesquiera de sus datos, un valor por defecto razonable para la mayoría de los casos.', zh: '分析中包含的最远站点间距离，单位为米。留空则让工具自动使用数据中任意两站点间最大距离的一半，这对大多数情况都是合理的默认值。' },
  'lcz_variogram.year': { en: 'Restricts the analysis to a specific year, such as 2023.', pt: 'Restringe a análise a um ano específico, como 2023.', es: 'Restringe el análisis a un año concreto, como 2023.', zh: '将分析限定为特定年份，如 2023。' },
  'lcz_variogram.month': { en: 'Restricts the analysis to a specific month, such as 7 for July.', pt: 'Restringe a análise a um mês específico, como 7 para julho.', es: 'Restringe el análisis a un mes concreto, como 7 para julio.', zh: '将分析限定为特定月份，如 7 表示 7 月。' },
  'lcz_variogram.day': { en: 'Restricts the analysis to a specific day of the month.', pt: 'Restringe a análise a um dia específico do mês.', es: 'Restringe el análisis a un día concreto del mes.', zh: '将分析限定为月份中的特定日期。' },
  'lcz_variogram.hour': { en: 'Restricts the analysis to a specific hour of the day, such as 14 for 2pm.', pt: 'Restringe a análise a uma hora específica do dia, como 14 para as 14h.', es: 'Restringe el análisis a una hora concreta del día, como 14 para las 2 p. m.', zh: '将分析限定为一天中的特定小时，如 14 表示下午 2 点。' },
  'lcz_variogram.start': { en: 'The beginning of a custom date range to analyze, such as "2023-06-01".', pt: 'O início de um intervalo de datas personalizado a analisar, como "2023-06-01".', es: 'El inicio de un rango de fechas personalizado a analizar, como "2023-06-01".', zh: '要分析的自定义日期范围起始点，如“2023-06-01”。' },
  'lcz_variogram.end': { en: 'The end of a custom date range to analyze, such as "2023-08-31".', pt: 'O fim de um intervalo de datas personalizado a analisar, como "2023-08-31".', es: 'El fin de un rango de fechas personalizado a analizar, como "2023-08-31".', zh: '要分析的自定义日期范围结束点，如“2023-08-31”。' },
  'plot_grid_only.grid': { en: 'The spatial layer to draw, such as grid cells, zone polygons, or point locations. This is required and is the actual shape being plotted on the map.', pt: 'A camada espacial a desenhar, como células de grade, polígonos de zona ou localizações pontuais. É obrigatório e é a forma efetivamente plotada no mapa.', es: 'La capa espacial a dibujar, como celdas de cuadrícula, polígonos de zonas o ubicaciones puntuales. Es obligatoria y es la forma real que se dibuja en el mapa.', zh: '要绘制的空间图层，如网格单元、区域多边形或点位。这是必填项，也是实际要在地图上绘制的形状。' },
  'plot_grid_only.color_by': { en: 'The name of a data column to color the shapes by, e.g. a temperature or pollution value. Leave blank to draw every shape in a single flat color with no data-driven coloring.', pt: 'O nome de uma coluna de dados para colorir as formas, por exemplo um valor de temperatura ou de poluição. Deixe em branco para desenhar todas as formas em uma única cor sólida, sem coloração orientada por dados.', es: 'El nombre de una columna de datos con la que colorear las formas, por ejemplo un valor de temperatura o de contaminación. Déjelo en blanco para dibujar todas las formas en un solo color plano, sin coloreado basado en datos.', zh: '用来给图形着色的数据列名，例如温度或污染数值。留空则以单一纯色绘制所有图形，不进行数据驱动的着色。' },
  'plot_grid_only.cmap': { en: 'The color scale used when color_by is set, e.g. "viridis" (the default, a perceptually even blue-to-yellow scale), "plasma", or "RdYlBu" for diverging data. Any standard Matplotlib colormap name works.', pt: 'A escala de cores usada quando color_by está definido, por exemplo "viridis" (padrão, uma escala azul-para-amarelo perceptualmente uniforme), "plasma", ou "RdYlBu" para dados divergentes. Qualquer nome de mapa de cores padrão do Matplotlib funciona.', es: 'La escala de color usada cuando color_by está definido, por ejemplo "viridis" (por defecto, una escala perceptualmente uniforme de azul a amarillo), "plasma", o "RdYlBu" para datos divergentes. Funciona cualquier nombre estándar de mapa de color de Matplotlib.', zh: '设置 color_by 时使用的色阶，例如“viridis”（默认，一种从蓝到黄的感知均匀色阶）、“plasma”，或适用于发散型数据的“RdYlBu”。任何标准的 Matplotlib 色阶名称都可以使用。' },
  'plot_grid_only.edgecolor': { en: 'The color of the outline drawn around each shape. Defaults to "black"; set it to match your basemap or theme, e.g. "white" for a dark background.', pt: 'A cor do contorno desenhado ao redor de cada forma. O padrão é "black"; ajuste para combinar com seu mapa-base ou tema, por exemplo "white" para um fundo escuro.', es: 'El color del contorno dibujado alrededor de cada forma. Por defecto "black"; ajústelo para que coincida con su mapa base o tema, por ejemplo "white" para un fondo oscuro.', zh: '每个图形轮廓线的颜色。默认为“black”；可根据底图或主题调整，例如深色背景下设为“white”。' },
  'plot_grid_only.linewidth': { en: 'How thick the outline around each shape is, in points. The default of 0.3 gives thin, subtle borders; increase it for bolder outlines on a large-scale map.', pt: 'Quão grosso é o contorno ao redor de cada forma, em pontos. O padrão de 0,3 dá bordas finas e sutis; aumente para contornos mais destacados em um mapa de grande escala.', es: 'Cuán grueso es el contorno alrededor de cada forma, en puntos. El valor por defecto de 0,3 da bordes finos y discretos; auméntelo para contornos más marcados en un mapa a gran escala.', zh: '每个图形轮廓线的粗细，单位为点。默认值 0.3 提供纤细、含蓄的边框；在大比例尺地图上可增大数值以获得更粗的轮廓线。' },
  'plot_grid_only.alpha': { en: 'How transparent the fill color is, from 0 (invisible) to 1 (solid). The default of 0.7 lets the basemap show through slightly so streets remain visible under the data.', pt: 'Quão transparente é a cor de preenchimento, de 0 (invisível) a 1 (sólido). O padrão de 0,7 permite que o mapa-base apareça levemente por baixo, mantendo as ruas visíveis sob os dados.', es: 'Cuán transparente es el color de relleno, de 0 (invisible) a 1 (sólido). El valor por defecto de 0,7 deja que el mapa base se transparente un poco, para que las calles sigan visibles bajo los datos.', zh: '填充颜色的透明程度，从 0（完全不可见）到 1（完全不透明）。默认值 0.7 让底图略微透出，使街道在数据下方依然可见。' },
  'plot_grid_only.add_basemap': { en: 'When on (the default), overlays real-world streets and labels from OpenStreetMap behind your data. Turn it off for a plain map with no background context, or if the optional basemap library isn\'t installed (it\'s skipped automatically in that case).', pt: 'Quando ativado (padrão), sobrepõe ruas e rótulos reais do OpenStreetMap por trás dos seus dados. Desative para um mapa simples sem contexto de fundo, ou se a biblioteca opcional de mapa-base não estiver instalada (nesse caso é automaticamente ignorada).', es: 'Cuando está activado (por defecto), superpone calles y etiquetas reales de OpenStreetMap detrás de sus datos. Desactívelo para un mapa plano sin contexto de fondo, o si la biblioteca opcional de mapas base no está instalada (en ese caso se omite automáticamente).', zh: '开启时（默认），会在数据下方叠加来自 OpenStreetMap 的真实街道和标注。关闭此项可得到没有背景信息的纯地图，或在未安装可选底图库时（此时会自动跳过）使用。' },
  'plot_grid_only.basemap_source': { en: 'An advanced option to swap in a different background map style than the default OpenStreetMap street map, for example a lighter "CartoDB Positron" style for a cleaner look. Most users can leave this blank.', pt: 'Uma opção avançada para trocar o estilo de mapa de fundo padrão do OpenStreetMap por outro, por exemplo um estilo mais claro "CartoDB Positron" para um visual mais limpo. A maioria dos usuários pode deixar em branco.', es: 'Una opción avanzada para cambiar a un estilo de mapa de fondo distinto del OpenStreetMap por defecto, por ejemplo un estilo más claro "CartoDB Positron" para un aspecto más limpio. La mayoría de los usuarios puede dejarlo en blanco.', zh: '一个高级选项，用于替换默认的 OpenStreetMap 街道地图样式，例如更简洁的“CartoDB Positron”风格。大多数用户可以留空。' },
  'plot_grid_only.figsize': { en: 'The size of the output image in inches, as width and height, e.g. (10, 10) for a square figure. Increase both numbers for a larger, more detailed image.', pt: 'O tamanho da imagem de saída em polegadas, como largura e altura, por exemplo (10, 10) para uma figura quadrada. Aumente ambos os números para uma imagem maior e mais detalhada.', es: 'El tamaño de la imagen de salida en pulgadas, como ancho y alto, por ejemplo (10, 10) para una figura cuadrada. Aumente ambos números para una imagen más grande y con más detalle.', zh: '输出图片的尺寸，以宽和高（英寸）表示，例如 (10, 10) 表示正方形图幅。增大两个数值可获得更大、更细致的图片。' },
  'plot_grid_only.title': { en: 'The text shown above the map, e.g. "ERA5 Temperature Grid — São Paulo, 2023". Leave blank for no title.', pt: 'O texto exibido acima do mapa, por exemplo "Grade de Temperatura ERA5 — São Paulo, 2023". Deixe em branco para nenhum título.', es: 'El texto mostrado encima del mapa, por ejemplo "Cuadrícula de Temperatura ERA5 — São Paulo, 2023". Déjelo en blanco para no mostrar título.', zh: '显示在地图上方的文字，例如“ERA5 气温网格 — 圣保罗，2023”。留空则不显示标题。' },
  'plot_grid_only.isave': { en: 'When turned on, saves the map image to your project\'s LCZ4r_output folder instead of (or in addition to) just displaying it.', pt: 'Quando ativado, salva a imagem do mapa na pasta LCZ4r_output do seu projeto, em vez de (ou além de) apenas exibi-la.', es: 'Al activarlo, guarda la imagen del mapa en la carpeta LCZ4r_output de su proyecto en lugar de (o además de) solo mostrarla.', zh: '开启后会将地图图片保存到项目的 LCZ4r_output 文件夹，而不仅仅（或除了）显示出来。' },
  'plot_grid_only.save_extension': { en: 'The image file format used when isave is on, e.g. "png" (the default) for a standard image, or "pdf"/"svg" for a print-quality vector file.', pt: 'O formato de arquivo de imagem usado quando isave está ativado, por exemplo "png" (padrão) para uma imagem padrão, ou "pdf"/"svg" para um arquivo vetorial de qualidade de impressão.', es: 'El formato de archivo de imagen usado cuando isave está activado, por ejemplo "png" (por defecto) para una imagen estándar, o "pdf"/"svg" para un archivo vectorial de calidad de impresión.', zh: 'isave 开启时使用的图片文件格式，例如“png”（默认）用于标准图片，或“pdf”/“svg”用于印刷质量的矢量文件。' },
  'plot_lcz_relationship.lcz_path': { en: 'The LCZ classification map (a GeoTIFF with zone codes 1-17) that defines which zone each location belongs to.', pt: 'O mapa de classificação LCZ (um GeoTIFF com códigos de zona 1-17) que define a qual zona cada localização pertence.', es: 'El mapa de clasificación LCZ (un GeoTIFF con códigos de zona 1-17) que define a qué zona pertenece cada ubicación.', zh: '定义每个位置所属区域的 LCZ 分类地图（GeoTIFF，区域代码 1-17）。' },
  'plot_lcz_relationship.variable_path': { en: 'The environmental variable raster to compare against LCZ classes, e.g. a temperature, rainfall, or pollution GeoTIFF covering the same area and time period. It is automatically reprojected and resized to match the LCZ map\'s grid if they don\'t already line up.', pt: 'O raster da variável ambiental a comparar contra as classes LCZ, por exemplo um GeoTIFF de temperatura, chuva ou poluição cobrindo a mesma área e período de tempo. É reprojetado e redimensionado automaticamente para corresponder à grade do mapa LCZ, caso ainda não estejam alinhados.', es: 'El ráster de la variable ambiental a comparar con las clases LCZ, por ejemplo un GeoTIFF de temperatura, lluvia o contaminación que cubra la misma área y periodo de tiempo. Se reproyecta y redimensiona automáticamente para ajustarse a la cuadrícula del mapa LCZ si no coinciden entre sí.', zh: '要与 LCZ 类别对比的环境变量栅格，例如覆盖同一区域和时间段的气温、降水或污染 GeoTIFF。如果它与 LCZ 地图的网格不一致，会自动重投影并调整尺寸以匹配。' },
  'plot_lcz_relationship.variable_name': { en: 'The label used for the variable on the plot\'s value axis, e.g. "Temperature (°C)" or "PM2.5 (µg/m³)". Defaults to the generic word "value" if left blank.', pt: 'O rótulo usado para a variável no eixo de valores do gráfico, por exemplo "Temperatura (°C)" ou "PM2,5 (µg/m³)". Assume a palavra genérica "valor" se deixado em branco.', es: 'La etiqueta usada para la variable en el eje de valores del gráfico, por ejemplo "Temperatura (°C)" o "PM2.5 (µg/m³)". Por defecto usa la palabra genérica "value" si se deja en blanco.', zh: '图表数值轴上使用的变量标签，例如“气温 (°C)”或“PM2.5 (µg/m³)”。留空则默认使用通用词“value”。' },
  'plot_lcz_relationship.plot_type': { en: 'The style of chart to draw: "box" (default) or "violin" show the full distribution of values within each LCZ class; "scatter" shows individual pixel values plotted against their zone (useful for spotting outliers); "heatmap" condenses each zone down to a single summary value in one row, good for quick comparisons across many zones at once.', pt: 'O estilo de gráfico a desenhar: "box" (padrão) ou "violin" mostram a distribuição completa de valores dentro de cada classe LCZ; "scatter" mostra valores de pixels individuais plotados contra sua zona (útil para identificar valores discrepantes); "heatmap" condensa cada zona a um único valor-resumo em uma linha, bom para comparações rápidas entre muitas zonas de uma vez.', es: 'El estilo de gráfico a dibujar: "box" (por defecto) o "violin" muestran la distribución completa de valores dentro de cada clase LCZ; "scatter" muestra valores de píxeles individuales graficados según su zona (útil para detectar valores atípicos); "heatmap" condensa cada zona a un único valor resumen en una fila, ideal para comparaciones rápidas entre muchas zonas a la vez.', zh: '要绘制的图表样式：“box”（默认）或“violin”展示每个 LCZ 类别内数值的完整分布；“scatter”将单个像元数值相对于其所属区域绘制（便于发现离群值）；“heatmap”将每个区域压缩为一行摘要数值，适合快速比较大量区域。' },
  'plot_lcz_relationship.agg_fun': { en: 'The statistic used to summarize each zone\'s pixels when plot_type is "heatmap": "mean" (average, the default), "median" (middle value, less sensitive to outliers), or "sum" (total).', pt: 'A estatística usada para resumir os pixels de cada zona quando plot_type é "heatmap": "mean" (média, padrão), "median" (valor central, menos sensível a valores discrepantes), ou "sum" (total).', es: 'La estadística usada para resumir los píxeles de cada zona cuando plot_type es "heatmap": "mean" (promedio, por defecto), "median" (valor central, menos sensible a los valores atípicos), o "sum" (total).', zh: 'plot_type 为“heatmap”时用于汇总每个区域像元的统计量：“mean”（平均值，默认）、“median”（中位数，对离群值不敏感），或“sum”（总和）。' },
  'plot_lcz_relationship.isave': { en: 'When turned on, saves the chart to your project\'s LCZ4r_output folder instead of only displaying it.', pt: 'Quando ativado, salva o gráfico na pasta LCZ4r_output do seu projeto, em vez de apenas exibi-lo.', es: 'Al activarlo, guarda el gráfico en la carpeta LCZ4r_output de su proyecto en lugar de solo mostrarlo.', zh: '开启后会将图表保存到项目的 LCZ4r_output 文件夹，而不仅仅是显示出来。' },
  'plot_lcz_relationship.save_extension': { en: 'The file format used when isave is on, e.g. "html" (the default, an interactive chart you can open in a browser) or a static image format like "png".', pt: 'O formato de arquivo usado quando isave está ativado, por exemplo "html" (padrão, um gráfico interativo que você pode abrir no navegador) ou um formato de imagem estática como "png".', es: 'El formato de archivo usado cuando isave está activado, por ejemplo "html" (por defecto, un gráfico interactivo que se puede abrir en un navegador) o un formato de imagen estática como "png".', zh: 'isave 开启时使用的文件格式，例如“html”（默认，可在浏览器中打开的交互式图表）或“png”等静态图片格式。' },
}

export function getParamHelp(functionId: string, paramName: string, lang: Language): string | undefined {
  return PARAM_HELP[`${functionId}.${paramName}`]?.[lang]
}
